<title>Focus Dashboard</title>
<style>
  :root {
    --bg: #0d1117;
    --card: #161b22;
    --card-border: #21262d;
    --text: #e6edf3;
    --text-dim: #8b949e;
    --accent: #58a6ff;
    --accent-glow: rgba(88, 166, 255, 0.35);
    --green: #3fb950;
    --track: #21262d;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--text);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
  }

  .card {
    background: var(--card);
    border: 1px solid var(--card-border);
    border-radius: 16px;
    padding: 28px;
    width: 100%;
    max-width: 380px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  }

  .card-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 24px;
  }

  .card-header h1 { font-size: 1.05rem; font-weight: 600; }
  .card-header .date { font-size: 0.8rem; color: var(--text-dim); }

  /* --- Circular score gauge --- */
  .gauge-wrap {
    display: flex;
    justify-content: center;
    margin-bottom: 24px;
    position: relative;
  }

  .gauge { transform: rotate(-90deg); }
  .gauge .track { stroke: var(--track); }
  .gauge .progress {
    stroke: var(--accent);
    stroke-linecap: round;
    filter: drop-shadow(0 0 6px var(--accent-glow));
    transition: stroke-dashoffset 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .gauge-label {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    pointer-events: none;
  }

  .gauge-label .score {
    font-size: 2.4rem;
    font-weight: 700;
    line-height: 1;
    font-variant-numeric: tabular-nums;
  }

  .gauge-label .sub {
    font-size: 0.72rem;
    color: var(--text-dim);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-top: 6px;
  }

  /* --- Sparkline --- */
  .trend {
    margin-bottom: 24px;
  }

  .trend-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
  }

  .trend-header span { font-size: 0.8rem; color: var(--text-dim); }
  .trend-header .delta { color: var(--green); font-weight: 600; }

  .sparkline { width: 100%; height: 56px; display: block; }
  .sparkline .line {
    fill: none;
    stroke: var(--accent);
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  .sparkline .fill { fill: url(#sparkGrad); }
  .sparkline .dot { fill: var(--accent); }

  .day-labels {
    display: flex;
    justify-content: space-between;
    margin-top: 6px;
    font-size: 0.68rem;
    color: var(--text-dim);
  }

  /* --- Button --- */
  .focus-btn {
    width: 100%;
    padding: 14px;
    border: none;
    border-radius: 10px;
    background: linear-gradient(135deg, #1f6feb, #58a6ff);
    color: #fff;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
  }

  .focus-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px var(--accent-glow);
  }

  .focus-btn:active { transform: translateY(0); }

  .focus-btn.active {
    background: linear-gradient(135deg, #da3633, #f85149);
    font-variant-numeric: tabular-nums;
  }
</style>
</head>
