<script>
  (function () {
    // Weekly data (7 days, Mon..Sun). Last value = today's score.
    const weekly = [62, 70, 58, 74, 81, 68, 86];
    const targetScore = weekly[weekly.length - 1]; // today = 86

    // Ring geometry
    const r = 46;
    const circumference = 2 * Math.PI * r; // ≈ 289.03
    const ringFg = document.getElementById('ringFg');
    const scoreNum = document.getElementById('scoreNum');
    const statusText = document.getElementById('statusText');

    // Sparkline geometry
    const W = 300, H = 46, PAD = 6;
    const min = Math.min(...weekly) - 6;
    const max = Math.max(...weekly) + 6;

    function buildSparkline() {
      const n = weekly.length;
      const step = (W - PAD * 2) / (n - 1);
      const pts = weekly.map((v, i) => {
        const x = PAD + i * step;
        const y = H - PAD - ((v - min) / (max - min)) * (H - PAD * 2);
        return [x, y];
      });

      // Smooth polyline using Catmull-Rom -> cubic bezier
      let d = `M ${pts[0][0]} ${pts[0][1]}`;
      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[Math.max(0, i - 1)];
        const p1 = pts[i];
        const p2 = pts[i + 1];
        const p3 = pts[Math.min(pts.length - 1, i + 2)];
        const c1x = p1[0] + (p2[0] - p0[0]) / 6;
        const c1y = p1[1] + (p2[1] - p0[1]) / 6;
        const c2x = p2[0] - (p3[0] - p1[0]) / 6;
        const c2y = p2[1] - (p3[1] - p1[1]) / 6;
        d += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2[0].toFixed(2)} ${p2[1].toFixed(2)}`;
      }

      document.getElementById('sparkLine').setAttribute('d', d);
      document.getElementById('sparkArea').setAttribute('d', d + ` L ${pts[pts.length - 1][0].toFixed(2)} ${H} L ${pts[0][0].toFixed(2)} ${H} Z`);

      // Dot on last point
      const last = pts[pts.length - 1];
      document.getElementById('sparkDot').setAttribute('cx', last[0].toFixed(2));
      document.getElementById('sparkDot').setAttribute('cy', last[1].toFixed(2));
    }

    // Animate ring + number on load
    function animateScore() {
      const duration = 900;
      const start = performance.now();
      function frame(now) {
        const t = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - t, 3); // easeOutCubic
        const val = Math.round(targetScore * eased);
        scoreNum.textContent = val;
        ringFg.style.strokeDashoffset = circumference * (1 - eased);
        if (t < 1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    // Status text based on score
    function setStatus(score) {
      if (score >= 85) statusText.textContent = 'Excellent flow';
      else if (score >= 70) statusText.textContent = 'Great momentum';
      else if (score >= 55) statusText.textContent = 'Steady pace';
      else statusText.textContent = 'Needs a boost';
    }

    // Avg label
    const avg = Math.round(weekly.reduce((a, b) => a + b, 0) / weekly.length);
    document.getElementById('avgVal').textContent = avg;

    // Button toggle
    const btn = document.getElementById('startBtn');
    const btnText = document.getElementById('btnText');
    const btnIcon = document.getElementById('btnIcon');
    let running = false;

    btn.addEventListener('click', function () {
      running = !running;
      if (running) {
        btn.classList.add('running');
        btnText.textContent = 'Focusing… 24:59';
        btnIcon.innerHTML = '<rect x="3.5" y="3.5" width="9" height="9" rx="1.5"/>';
        // simple countdown demo
        let secs = 24 * 60 + 59;
        const timer = setInterval(() => {
          secs--;
          if (secs <= 0) { clearInterval(timer); resetBtn(); return; }
          const m = Math.floor(secs / 60);
          const s = secs % 60;
          btnText.textContent = 'Focusing… ' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
        }, 1000);
        btn._timer = timer;
      } else {
        resetBtn();
      }
    });

    function resetBtn() {
      if (btn._timer) { clearInterval(btn._timer); btn._timer = null; }
      btn.classList.remove('running');
      btnText.textContent = 'Start Focus';
      btnIcon.innerHTML = '<path d="M4 2.5v11l9-5.5-9-5.5z"/>';
      running = false;
    }

    // Init
    ringFg.style.strokeDasharray = circumference;
    buildSparkline();
    setStatus(targetScore);
    animateScore();
  })();
</script>

</body>
</html>
