<body>
    <canvas id="game"></canvas>
    <script>
        // ===================== SETUP =====================
        const canvas = document.getElementById('game');
        const ctx = canvas.getContext('2d');
        const W = 800,
            H = 600;
        canvas.width = W;
        canvas.height = H;

        // ===================== AUDIO (Web Audio API) =====================
        let audioCtx = null;

        function initAudio() {
            if (!audioCtx) {
                try {
                    audioCtx = new(window.AudioContext || window.webkitAudioContext)();
                } catch (e) { /* audio unavailable */ }
            }
            if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
        }

        function playTone(freq, dur, type = 'square', vol = 0.08, delay = 0) {
            if (!audioCtx) return;
            const t = audioCtx.currentTime + delay;
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq, t);
            gain.gain.setValueAtTime(vol, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start(t);
            osc.stop(t + dur);
        }

        function playSound(name) {
            if (!audioCtx) return;
            switch (name) {
                case 'paddle':
                    playTone(240, 0.08, 'square', 0.07);
                    break;
                case 'wall':
                    playTone(160, 0.05, 'triangle', 0.05);
                    break;
                case 'brick':
                    playTone(480 + Math.random() * 240, 0.09, 'square', 0.08);
                    break;
                case 'life':
                    playTone(320, 0.25, 'sawtooth', 0.09);
                    playTone(140, 0.4, 'sawtooth', 0.09, 0.15);
                    break;
                case 'level':
                    [523, 659, 784, 1047].forEach((f, i) => playTone(f, 0.15, 'square', 0.07, i * 0.12));
                    break;
                case 'gameover':
                    [400, 300, 200, 100].forEach((f, i) => playTone(f, 0.22, 'sawtooth', 0.08, i * 0.16));
                    break;
                case 'victory':
                    [523, 659, 784, 1047, 784, 1047, 1319].forEach((f, i) => playTone(f, 0.2, 'square', 0.07, i * 0.15));
                    break;
            }
        }

        // ===================== GAME STATE =====================
        let state = 'start'; // start | playing | levelComplete | gameOver | victory
        let level = 1;
        let score = 0;
        let lives = 3;
        let ballAttached = true;
        const MAX_LEVEL = 5;

        // ===================== OBJECTS =====================
        const paddle = { w: 110, h: 14, x: W / 2, y: H - 40, speed: 520 };
        const ball = { x: W / 2, y: H - 40 - 7 - 7, r: 7, vx: 0, vy: 0, speed: 320 };

        let bricks = [];
        let particles = [];
        let keys = {};
        let mouseX = null;

        const brickColors = ['#ff2d95', '#ff6b35', '#ffe600', '#39ff14', '#00e5ff', '#7a5cff', '#ff2d95'];
        const BRICK_PAD = 4;
        const BRICK_TOP = 70;
        const BRICK_COLS = 10;
        const BRICK_H = 20;

        function buildBricks() {
            bricks = [];
            const rows = Math.min(4 + level, 8);
            const bw = (W - (BRICK_COLS + 1) * BRICK_PAD) / BRICK_COLS;
            for (let r = 0; r < rows; r++) {
                bricks[r] = [];
                for (let c = 0; c < BRICK_COLS; c++) {
                    bricks[r][c] = {
                        x: BRICK_PAD + c * (bw + BRICK_PAD),
                        y: BRICK_TOP + r * (BRICK_H + BRICK_PAD),
                        w: bw,
                        h: BRICK_H,
                        alive: true,
                        color: brickColors[r % brickColors.length]
                    };
                }
            }
        }

        function resetBall() {
            ball.x = paddle.x;
            ball.y = paddle.y - paddle.h / 2 - ball.r;
            ball.vx = 0;
            ball.vy = 0;
            ballAttached = true;
        }

        function resetGame() {
            level = 1;
            score = 0;
            lives = 3;
            ball.speed = 320;
            buildBricks();
            resetBall();
            state = 'playing';
        }

        function nextLevel() {
            level++;
            if (level > MAX_LEVEL) {
                state = 'victory';
                playSound('victory');
                return;
            }
            ball.speed = 320 + (level - 1) * 35;
            buildBricks();
            resetBall();
            state = 'playing';
            playSound('level');
        }

        function launchBall() {
            if (!ballAttached) return;
            ballAttached = false;
            const angle = -Math.PI / 2 + (Math.random() * 0.4 - 0.2);
            ball.vx = Math.cos(angle);
            ball.vy = Math.sin(angle);
            playSound('paddle');
        }

        function loseLife() {
            lives--;
            playSound('life');
            if (lives <= 0) {
                state = 'gameOver';
                playSound('gameover');
            } else {
                resetBall();
            }
        }

        function handleAction() {
            initAudio();
            if (state === 'start') {
                state = 'playing';
                resetBall();
            } else if (state === 'levelComplete') {
                nextLevel();
            } else if (state === 'gameOver' || state === 'victory') {
                resetGame();
            } else if (state === 'playing' && ballAttached) {
                launchBall();
            }
        }

        // ===================== INPUT =====================
        function getCanvasPos(e) {
            const rect = canvas.getBoundingClientRect();
            const sx = W / rect.width;
            const sy = H / rect.height;
            const cx = e.touches ? e.touches[0].clientX : e.clientX;
            const cy = e.touches ? e.touches[0].clientY : e.clientY;
            return { x: (cx - rect.left) * sx, y: (cy - rect.top) * sy };
        }

        canvas.addEventListener('mousemove', e => {
            mouseX = getCanvasPos(e).x;
        });
        canvas.addEventListener('mousedown', e => {
            e.preventDefault();
            mouseX = getCanvasPos(e).x;
            handleAction();
        });

        canvas.addEventListener('touchstart', e => {
            e.preventDefault();
            const pos = getCanvasPos(e);
            mouseX = pos.x;
            handleAction();
        }, { passive: false });
        canvas.addEventListener('touchmove', e => {
            e.preventDefault();
            mouseX = getCanvasPos(e).x;
        }, { passive: false });

        window.addEventListener('keydown', e => {
            if (e.code === 'Space') {
                e.preventDefault();
                handleAction();
            }
            if (e.code === 'ArrowLeft') keys.left = true;
            if (e.code === 'ArrowRight') keys.right = true;
        });
        window.addEventListener('keyup', e => {
            if (e.code === 'ArrowLeft') keys.left = false;
            if (e.code === 'ArrowRight') keys.right = false;
        });

        // ===================== PHYSICS =====================
        function update(dt) {
            // Paddle movement
            let dir = 0;
            if (keys.left) dir -= 1;
            if (keys.right) dir += 1;
            if (dir !== 0) {
                paddle.x += dir * paddle.speed * dt;
                mouseX = null;
            } else if (mouseX !== null) {
                paddle.x = mouseX;
            }
            paddle.x = Math.max(paddle.w / 2, Math.min(W - paddle.w / 2, paddle.x));

            if (state !== 'playing') return;

            // Attached ball follows paddle
            if (ballAttached) {
                ball.x = paddle.x;
                ball.y = paddle.y - paddle.h / 2 - ball.r;
                return;
            }

            // Move ball
            ball.x += ball.vx * ball.speed * dt;
            ball.y += ball.vy * ball.speed * dt;

            // Wall collisions
            if (ball.x - ball.r < 0) { ball.x = ball.r;
                ball.vx = -ball.vx;
                playSound('wall'); }
            if (ball.x + ball.r > W) { ball.x = W - ball.r;
                ball.vx = -ball.vx;
                playSound('wall'); }
            if (ball.y - ball.r < 0) { ball.y = ball.r;
                ball.vy = -ball.vy;
                playSound('wall'); }
            if (ball.y - ball.r > H) {
                loseLife();
                return;
            }

            // Paddle collision
            if (ball.vy > 0 &&
                ball.y + ball.r >= paddle.y - paddle.h / 2 &&
                ball.y + ball.r <= paddle.y + paddle.h / 2 + 6 &&
                ball.x >= paddle.x - paddle.w / 2 - ball.r &&
                ball.x <= paddle.x + paddle.w / 2 + ball.r) {
                const hitPos = (ball.x - paddle.x) / (paddle.w / 2); // -1..1
                const angle = hitPos * Math.PI / 3;
                ball.vx = Math.sin(angle);
                ball.vy = -Math.cos(angle);
                // ensure minimum upward component
                if (Math.abs(ball.vy) < 0.3) ball.vy = -0.3;
                const len = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
                ball.vx /= len;
                ball.vy /= len;
                ball.y = paddle.y - paddle.h / 2 - ball.r;
                playSound('paddle');
            }

            // Brick collision
            checkBrickCollision();
        }

        function checkBrickCollision() {
            for (let r = 0; r < bricks.length; r++) {
                for (let c = 0; c < bricks[r].length; c++) {
                    const b = bricks[r][c];
                    if (!b.alive) continue;
                    const cx = b.x + b.w / 2,
                        cy = b.y + b.h / 2;
                    const dx = ball.x - cx,
                        dy = ball.y - cy;
                    const ox = (b.w / 2 + ball.r) - Math.abs(dx);
                    const oy = (b.h / 2 + ball.r) - Math.abs(dy);
                    if (ox > 0 && oy > 0) {
                        if (ox < oy) {
                            ball.vx = -ball.vx;
                            ball.x = cx + (dx > 0 ? (b.w / 2 + ball.r) : -(b.w / 2 + ball.r));
                        } else {
                            ball.vy = -ball.vy;
                            ball.y = cy + (dy > 0 ? (b.h / 2 + ball.r) : -(b.h / 2 + ball.r));
                        }
                        b.alive = false;
                        score += 10 * level;
                        spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color);
                        playSound('brick');
                        // check level complete
                        let remaining = 0;
                        for (let rr = 0; rr < bricks.length; rr++)
                            for (let cc = 0; cc < bricks[rr].length; cc++)
                                if (bricks[rr][cc].alive) remaining++;
                        if (remaining === 0) {
                            state = 'levelComplete';
                            playSound('level');
                        }
                        return;
                    }
                }
            }
        }

        // ===================== PARTICLES =====================
        function spawnParticles(x, y, color) {
            for (let i = 0; i < 14; i++) {
                const a = Math.random() * Math.PI * 2;
                const sp = Math.random() * 180 + 40;
                particles.push({
                    x,
                    y,
                    vx: Math.cos(a) * sp,
                    vy: Math.sin(a) * sp,
                    life: 1,
                    decay: Math.random() * 0.02 + 0.012,
                    size: Math.random() * 3.5 + 1,
                    color
                });
            }
        }

        function updateParticles(dt) {
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.vy += 120 * dt; // gravity
                p.life -= p.decay;
                if (p.life <= 0) particles.splice(i, 1);
            }
        }

        // ===================== DRAWING =====================
        function drawBackground() {
            const grad = ctx.createLinearGradient(0, 0, 0, H);
            grad.addColorStop(0, '#0a0a1e');
            grad.addColorStop(1, '#130826');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, W, H);
            // subtle grid
            ctx.strokeStyle = 'rgba(0,229,255,0.05)';
            ctx.lineWidth = 1;
            for (let x = 0; x <= W; x += 40) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, H);
                ctx.stroke();
            }
            for (let y = 0; y <= H; y += 40) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(W, y);
                ctx.stroke();
            }
        }

        function drawPaddle() {
            ctx.save();
            ctx.shadowColor = '#00e5ff';
            ctx.shadowBlur = 18;
            const grad = ctx.createLinearGradient(paddle.x - paddle.w / 2, 0, paddle.x + paddle.w / 2, 0);
            grad.addColorStop(0, '#00e5ff');
            grad.addColorStop(0.5, '#ffffff');
            grad.addColorStop(1, '#00e5ff');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.roundRect(paddle.x - paddle.w / 2, paddle.y - paddle.h / 2, paddle.w, paddle.h, 6);
            ctx.fill();
            ctx.restore();
        }

        function drawBall() {
            ctx.save();
            ctx.shadowColor = '#ff2d95';
            ctx.shadowBlur = 20;
            ctx.fillStyle = '#ffd1ec';
            ctx.beginPath();
            ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = 'rgba(255,45,149,0.4)';
            ctx.beginPath();
            ctx.arc(ball.x, ball.y, ball.r * 1.6, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();

            // launch guide line
            if (ballAttached && state === 'playing') {
                ctx.save();
                ctx.strokeStyle = 'rgba(255,45,149,0.3)';
                ctx.setLineDash([4, 6]);
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(ball.x, ball.y);
                ctx.lineTo(ball.x, ball.y - 120);
                ctx.stroke();
                ctx.restore();
            }
        }

        function drawBricks() {
            for (let r = 0; r < bricks.length; r++) {
                for (let c = 0; c < bricks[r].length; c++) {
                    const b = bricks[r][c];
                    if (!b.alive) continue;
                    ctx.save();
                    ctx.shadowColor = b.color;
                    ctx.shadowBlur = 12;
                    ctx.fillStyle = b.color;
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath();
                    ctx.roundRect(b.x, b.y, b.w, b.h, 3);
                    ctx.fill();
                    // inner highlight
                    ctx.globalAlpha = 0.25;
                    ctx.fillStyle = '#ffffff';
                    ctx.beginPath();
                    ctx.roundRect(b.x + 2, b.y + 2, b.w - 4, b.h / 2 - 1, 2);
                    ctx.fill();
                    ctx.restore();
                }
            }
        }

        function drawParticles() {
            for (const p of particles) {
                ctx.save();
                ctx.globalAlpha = Math.max(0, p.life);
                ctx.shadowColor = p.color;
                ctx.shadowBlur = 8;
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
        }

        function drawHUD() {
            ctx.save();
            ctx.font = 'bold 20px "Courier New", monospace';
            ctx.textBaseline = 'top';
            // Score
            ctx.shadowColor = '#39ff14';
            ctx.shadowBlur = 10;
            ctx.fillStyle = '#39ff14';
            ctx.fillText('SCORE', 20, 18);
            ctx.font = 'bold 26px "Courier New", monospace';
            ctx.fillText(String(score).padStart(6, '0'), 20, 42);
            // Level
            ctx.shadowColor = '#ffe600';
            ctx.fillStyle = '#ffe600';
            ctx.font = 'bold 20px "Courier New", monospace';
            ctx.textAlign = 'center';
            ctx.fillText('LEVEL ' + level, W / 2, 18);
            // Lives
            ctx.shadowColor = '#ff2d95';
            ctx.fillStyle = '#ff2d95';
            ctx.textAlign = 'right';
            let hearts = '';
            for (let i = 0; i < lives; i++) hearts += '◆ ';
            ctx.fillText(hearts, W - 20, 22);
            ctx.restore();
        }

        function drawOverlay() {
            if (state === 'playing') return;
            ctx.save();
            ctx.fillStyle = 'rgba(5,5,15,0.78)';
            ctx.fillRect(0, 0, W, H);

            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            let title = '',
                sub = '',
                tColor = '#00e5ff';

            if (state === 'start') {
                title = 'NEON BREAKER';
                sub = 'Press SPACE or CLICK to start';
                tColor = '#00e5ff';
            } else if (state === 'levelComplete') {
                title = 'LEVEL ' + level + ' COMPLETE!';
                sub = 'Press SPACE or CLICK for next level';
                tColor = '#39ff14';
            } else if (state === 'gameOver') {
                title = 'GAME OVER';
                sub = 'Score: ' + score + '   |   Press SPACE or CLICK to restart';
                tColor = '#ff2d95';
            } else if (state === 'victory') {
                title = 'YOU WIN!';
                sub = 'Final Score: ' + score + '   |   Press SPACE or CLICK to play again';
                tColor = '#ffe600';
            }

            ctx.shadowColor = tColor;
            ctx.shadowBlur = 30;
            ctx.fillStyle = tColor;
            ctx.font = 'bold 52px "Courier New", monospace';
            ctx.fillText(title, W / 2, H / 2 - 40);

            ctx.shadowBlur = 12;
            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 18px "Courier New", monospace';
            ctx.fillText(sub, W / 2, H / 2 + 30);

            if (state === 'start') {
                ctx.shadowBlur = 8;
                ctx.fillStyle = 'rgba(255,255,255,0.6)';
                ctx.font = '14px "Courier New", monospace';
                ctx.fillText('Move: Mouse / Arrow Keys / Touch', W / 2, H / 2 + 70);
            }
            ctx.restore();
        }

        function draw() {
            drawBackground();
            drawBricks();
            drawParticles();
            drawPaddle();
            drawBall();
            drawHUD();
            drawOverlay();
        }

        // ===================== MAIN LOOP =====================
        let lastTime = performance.now();

        function loop(t) {
            const dt = Math.min((t - lastTime) / 1000, 0.05);
            lastTime = t;
            update(dt);
            updateParticles(dt);
            draw();
            requestAnimationFrame(loop);
        }

        // ===================== INIT =====================
        buildBricks();
        resetBall();
        requestAnimationFrame(loop);
    </script>
</body>
</html>
