<script>
  /* ---------------- Data ---------------- */
  const data = [62, 70, 58, 74, 69, 81, 87];          // Mon → Sun
  const daysShort = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
  const daysFull  = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const score = data[data.length - 1];
  const prev  = data[data.length - 2];
  const delta = score - prev;
  const avg   = Math.round(data.reduce((a, b) => a + b, 0) / data.length);
  const best  = Math.max(...data);

  /* ---------------- Header / meta ---------------- */
  document.getElementById('dateLabel').textContent =
    new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });

  const badge = document.getElementById('deltaBadge');
  badge.textContent = (delta >= 0 ? '▲ +' : '▼ ') + delta + ' pts';
  if (delta < 0) badge.classList.add('negative');

  document.getElementById('statusLabel').textContent =
    score >= 85 ? 'Excellent' : score >= 70 ? 'Strong' : score >= 50 ? 'Moderate' : 'Low';
  document.getElementById('deltaText').innerHTML =
    (delta >= 0 ? '<strong>+' + delta + '</strong> vs yesterday' : '<strong>' + delta + '</strong> vs yesterday');
  document.getElementById('avgText').textContent = avg;
  document.getElementById('bestText').textContent = best;

  /* ---------------- Score ring + count-up ---------------- */
  const R = 58, CIRC = 2 * Math.PI * R;
  const ring = document.getElementById('ringProgress');
  ring.setAttribute('stroke-dasharray', CIRC);
  ring.setAttribute('stroke-dashoffset', CIRC);

  function setRing(pct) {
    ring.style.strokeDashoffset = CIRC * (1 - pct / 100);
  }

  function countUp(el, target, dur = 1200) {
    const start = performance.now();
    (function tick(now) {
      const t = Math.min(1, (now - start) / dur);
      const e = 1 - Math.pow(1 - t, 3);
      el.textContent = Math.round(target * e);
      if (t < 1) requestAnimationFrame(tick);
    })(start);
  }

  const scoreEl = document.getElementById('scoreNum');
  setTimeout(() => { setRing(score); countUp(scoreEl, score); }, 150);

  /* ---------------- Sparkline ---------------- */
  const W = 300, H = 84, PADX = 12, PADT = 10, PADB = 8;
  const min = Math.min(...data), max = Math.max(...data);
  const x = i => PADX + i * (W - 2 * PADX) / (data.length - 1);
  const y = v => PADT + (1 - (v - min) / (max - min)) * (H - PADT - PADB);
  const pts = data.map((v, i) => ({ x: x(i), y: y(v) }));

  function smoothPath(p) {
    let d = `M ${p[0].x},${p[0].y}`;
    for (let i = 0; i < p.length - 1; i++) {
      const p0 = p[Math.max(0, i - 1)], p1 = p[i], p2 = p[i + 1], p3 = p[Math.min(p.length - 1, i + 2)];
      d += ` C ${p1.x + (p2.x - p0.x) / 6},${p1.y + (p2.y - p0.y) / 6} `
         + `${p2.x - (p3.x - p1.x) / 6},${p2.y - (p3.y - p1.y) / 6} ${p2.x},${p2.y}`;
    }
    return d;
  }

  const lineD = smoothPath(pts);
  const line = document.getElementById('sparkLine');
  const area = document.getElementById('sparkArea');
  line.setAttribute('d', lineD);
  area.setAttribute('d', `${lineD} L ${pts[pts.length - 1].x},${H} L ${pts[0].x},${H} Z`);

  // Draw-in animation
  const len = line.getTotalLength();
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  requestAnimationFrame(() => {
    line.style.transition = 'stroke-dashoffset 1.4s ease 0.2s';
    line.style.strokeDashoffset = '0';
    area.style.opacity = '1';
  });

  // Dots + halo on today
  const dotsG = document.getElementById('sparkDots');
  pts.forEach((p, i) => {
    const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    c.setAttribute('cx', p.x); c.setAttribute('cy', p.y); c.setAttribute('r', 3.5);
    c.classList.add('dot');
    if (i === pts.length - 1) c.classList.add('today');
    const t = document.createElementNS('http://www.w3.org/2000/svg', 'title');
    t.textContent = `${daysFull[i]} · ${data[i]}`;
    c.appendChild(t);
    dotsG.appendChild(c);
    setTimeout(() => c.classList.add('show'), 350 + i * 120);

    if (i === pts.length - 1) {
      const halo = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      halo.setAttribute('cx', p.x); halo.setAttribute('cy', p.y); halo.setAttribute('r', 6);
      halo.classList.add('dot-halo');
      dotsG.appendChild(halo);
      setTimeout(() => halo.classList.add('show'), 350 + i * 120);
    }
  });

  // Day labels (today highlighted)
  const labelsEl = document.getElementById('dayLabels');
  daysShort.forEach((d, i) => {
    const s = document.createElement('span');
    s.textContent = d;
    if (i === daysShort.length - 1) s.classList.add('today');
    labelsEl.appendChild(s);
  });

  /* ---------------- Start Focus button (25-min timer) ---------------- */
  const FOCUS_SECONDS = 25 * 60;
  const btn = document.getElementById('focusBtn');
  const card = document.getElementById('card');
  let remaining = FOCUS_SECONDS, timerId = null;

  btn.addEventListener('click', () => timerId ? endSession(false) : startSession());

  function startSession() {
    remaining = FOCUS_SECONDS;
    card.classList.add('focusing');
    btn.classList.add('active');
    updateBtn();
    timerId = setInterval(() => {
      remaining--;
      remaining <= 0 ? endSession(true) : updateBtn();
    }, 1000);
  }

  function endSession(completed) {
    clearInterval(timerId);
    timerId = null;
    card.classList.remove('focusing');
    btn.classList.remove('active');
    if (completed) {
      btn.textContent = 'Session complete ✓';
      const newScore = Math.min(100, score + 1);
      scoreEl.textContent = newScore;
      setRing(newScore);
      setTimeout(() => (btn.textContent = 'Start Focus'), 2200);
    } else {
      btn.textContent = 'Start Focus';
    }
  }

  function updateBtn() {
    const m = String(Math.floor(remaining / 60)).padStart(2, '0');
    const s = String(remaining % 60).padStart(2, '0');
    btn.textContent = `${m}:${s} — tap to end`;
  }
</script>
</body>
</html>
```

**What's included:**

- **Focus score** — animated count-up number inside a gradient SVG progress ring, with a status label ("Excellent") and delta vs. yesterday
- **Weekly sparkline** — smooth Bézier curve generated in JS from a data array, with gradient area fill, draw-in animation, staggered dots, hover tooltips, and a pulsing halo on today
- **Start Focus button** — toggles a live 25:00 countdown; the card glows while a session runs, and completing a session bumps the score by +1
- **Dark mode polish** — ambient background glow, card shine line, gradient accents, fully responsive, zero external assets

To customize, just edit the `data` array at the top of the script — the score, badge, average, best day, and sparkline all update automatically.

