(() => {
'use strict';

/* ================= Constants ================= */
const W = 800, H = 600;                 // logical resolution
const WALL_L = 12, WALL_R = W - 12, WALL_T = 58;
const MAX_LEVEL = 5;
const PALETTE = ['#ff2d75','#ff9f1c','#ffe600','#39ff6a','#00e5ff','#b44dff','#ff4d6d','#4dffd2'];

/* ================= Canvas / responsive ================= */
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

function resize() {
  const dpr = window.devicePixelRatio || 1;
  const scale = Math.min(window.innerWidth / W, window.innerHeight / H) * 0.98;
  const cssW = Math.max(1, Math.floor(W * scale));
  const cssH = Math.max(1, Math.floor(H * scale));
  canvas.style.width  = cssW + 'px';
  canvas.style.height = cssH + 'px';
  canvas.width  = Math.floor(cssW * dpr);
  canvas.height = Math.floor(cssH * dpr);
  ctx.setTransform(canvas.width / W, 0, 0, canvas.height / H, 0, 0);
}
window.addEventListener('resize', resize);
resize();

/* ================= Web Audio (synthesized SFX) ================= */
let audioCtx = null, masterGain = null, muted = false;

function ensureAudio() {
  if (!audioCtx) {
    try {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      masterGain = audioCtx.createGain();
      masterGain.gain.value = 0.6;
      masterGain.connect(audioCtx.destination);
    } catch (e) { audioCtx = null; }
  }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}

function tone(freq, opts = {}) {
  if (!audioCtx || muted) return;
  const { end = freq, dur = 0.1, type = 'sine', vol = 0.2, when = 0 } = opts;
  const t0 = audioCtx.currentTime + when;
  const osc = audioCtx.createOscillator();
  const g = audioCtx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(Math.max(1, freq), t0);
  if (end !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(1, end), t0 + dur);
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  osc.connect(g); g.connect(masterGain);
  osc.start(t0); osc.stop(t0 + dur + 0.05);
}

function noiseBurst(dur = 0.12, vol = 0.25) {
  if (!audioCtx || muted) return;
  const len = Math.floor(audioCtx.sampleRate * dur);
  const buf = audioCtx.createBuffer(1, len, audioCtx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = audioCtx.createBufferSource();
  src.buffer = buf;
  const g = audioCtx.createGain();
  g.gain.value = vol;
  src.connect(g); g.connect(masterGain);
  src.start();
}

const sfx = {
  paddle()   { tone(240, { end: 150, dur: 0.09, type: 'triangle', vol: 0.3 }); },
  wall()     { tone(150, { dur: 0.05, type: 'sine', vol: 0.12 }); },
  brick()    { noiseBurst(0.14, 0.3); tone(520, { end: 120, dur: 0.14, type: 'square', vol: 0.16 }); },
  brickHit() { tone(330, { end: 260, dur: 0.06, type: 'square', vol: 0.16 }); },
  launch()   { tone(280, { end: 640, dur: 0.12, type: 'sine', vol: 0.22 }); },
  lose()     { tone(420, { end: 60,  dur: 0.7,  type: 'sawtooth', vol: 0.28 }); },
  level()    { [523,659,784,1047].forEach((f,i) => tone(f, { dur: 0.16, type: 'square', vol: 0.16, when: i * 0.1 })); },
  gameover() { [392,311,262,165].forEach((f,i) => tone(f, { dur: 0.32, type: 'sawtooth', vol: 0.2, when: i * 0.24 })); },
  victory()  { [523,659,784,1047,784,1047,1319,1568].forEach((f,i) => tone(f, { dur: 0.18, type: 'square', vol: 0.15, when: i * 0.13 })); }
};

/* ================= Game state ================= */
let state = 'start';           // start | serve | playing | levelclear | paused | gameover | victory
let prevState = 'serve';
let score = 0, lives = 3, level = 1;
let best = 0;
try { best = parseInt(localStorage.getItem('neonBreakerBest') || '0', 10) || 0; } catch (e) {}
let levelTimer = 0, levelBonus = 0;

const paddle = { w: 110, h: 14, x: W / 2, y: H - 36, speed: 9.5, targetX: null };
const ball   = { x: W / 2, y: 0, r: 8, dx: 0, dy: 0, speed: 6, stuck: true };
const bricks = [];
const particles = [];
const floatTexts = [];
const trail = [];
const keys = {};

const stars = [];
for (let i = 0; i < 70; i++)
  stars.push({ x: Math.random() * W, y: Math.random() * H, r: Math.random() * 1.4 + 0.4, p: Math.random() * Math.PI * 2, s: 0.4 + Math.random() * 1.2 });

/* ================= Level construction ================= */
function buildLevel(lv) {
  bricks.length = 0;
  const cols = 10;
  const rows = Math.min(4 + lv, 8);
  const gap = 8, left = 34, top = 92;
  const bw = (W - left * 2 - gap * (cols - 1)) / cols;
  const bh = 24;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let skip = false, hits = 1;
      if (lv === 1) {
        hits = 1;
      } else if (lv === 2) {
        skip = (r === rows - 1) && (c % 2 === 1);
        hits = (r < 2 && c % 3 === 0) ? 2 : 1;
      } else if (lv === 3) {
        skip = r > 1 && r < rows - 1 && c > 1 && c < cols - 2 && ((r + c) % 2 === 0);
        hits = r < 2 ? 2 : 1;
      } else if (lv === 4) {
        skip = (c % 4 === 3) && (r % 2 === 1);
        hits = r === 0 ? 3 : (r < 3 ? 2 : 1);
      } else {
        hits = r < 2 ? 3 : ((r + c) % 2 === 0 ? 2 : 1);
        skip = (r === rows - 1) && (c === 0 || c === cols - 1);
      }
      if (skip) continue;
      bricks.push({
        x: left + c * (bw + gap),
        y: top + r * (bh + gap),
        w: bw, h: bh,
        hits, maxHits: hits,
        color: PALETTE[r % PALETTE.length],
        alive: true,
        points: (rows - r) * 10 * hits
      });
    }
  }
}

function resetBall() {
  ball.stuck = true;
  ball.speed = Math.min(5.2 + level * 0.55, 10);
  ball.dx = 0; ball.dy = 0;
  ball.x = paddle.x;
  ball.y = paddle.y - ball.r - 2;
  trail.length = 0;
}

function setBallSpeed(s) {
  ball.speed = s;
  const m = Math.hypot(ball.dx, ball.dy);
  if (m > 0.0001) { ball.dx = ball.dx / m * s; ball.dy = ball.dy / m * s; }
}

function launchBall() {
  if (state !== 'serve') return;
  ball.stuck = false;
  state = 'playing';
  const a = Math.random() * 0.5 - 0.25;
  ball.dx = ball.speed * Math.sin(a);
  ball.dy = -ball.speed * Math.cos(a);
  sfx.launch();
}

/* ================= Flow ================= */
const overlays = ['startScreen', 'gameoverScreen', 'victoryScreen'];
function show(id) { overlays.forEach(o => document.getElementById(o).classList.toggle('visible', o === id)); }
function hideOverlays() { show(null); }

function updateBestLabel() { document.getElementById('bestScore').textContent = best; }
function saveBest() {
  if (score > best) {
    best = score;
    try { localStorage.setItem('neonBreakerBest', String(best)); } catch (e) {}
  }
  updateBestLabel();
}

function startGame() {
  ensureAudio();
  if (document.activeElement) document.activeElement.blur();
  score = 0; lives = 3; level = 1;
  particles.length = 0; floatTexts.length = 0;
  paddle.w = 110; paddle.x = W / 2; paddle.targetX = null;
  buildLevel(level);
  resetBall();
  hideOverlays();
  state = 'serve';
}

function gameOver() {
  state = 'gameover';
  saveBest();
  document.getElementById('finalScore').textContent = score;
  document.getElementById('finalLevel').textContent = level;
  show('gameoverScreen');
  sfx.gameover();
}

function victory() {
  state = 'victory';
  saveBest();
  document.getElementById('winScore').textContent = score;
  show('victoryScreen');
  sfx.victory();
}

function nextLevel() {
  level++;
  if (level > MAX_LEVEL) { victory(); return; }
  paddle.w = Math.max(110 - (level - 1) * 9, 68);
  buildLevel(level);
  resetBall();
  state = 'serve';
}

/* ================= Effects ================= */
function spawnParticles(x, y, color, n = 16, power = 1) {
  for (let i = 0; i < n; i++) {
    if (particles.length > 450) particles.shift();
    const a = Math.random() * Math.PI * 2;
    const sp = (1 + Math.random() * 3.5) * power;
    particles.push({
      x, y,
      dx: Math.cos(a) * sp,
      dy: Math.sin(a) * sp - 1.2,
      size: 1.5 + Math.random() * 3,
      life: 1,
      decay: 0.014 + Math.random() * 0.022,
      color
    });
  }
}
function addFloatText(x, y, text, color) { floatTexts.push({ x, y, text, color, life: 1 }); }

function hitBrick(b) {
  b.hits--;
  if (b.hits <= 0) {
    b.alive = false;
    score += b.points;
    spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color, 18);
    addFloatText(b.x + b.w / 2, b.y + b.h / 2, '+' + b.points, b.color);
    sfx.brick();
    setBallSpeed(Math.min(ball.speed + 0.04, 11));   // gradual speed-up
    if (bricks.every(br => !br.alive)) {
      levelBonus = 100 * level + lives * 25;
      score += levelBonus;
      levelTimer = 110;
      state = 'levelclear';
      sfx.level();
    }
  } else {
    spawnParticles(ball.x, ball.y, '#ffffff', 5, 0.6);
    sfx.brickHit();
  }
}

/* ================= Update ================= */
function update(dt) {
  // particles & floating texts always animate
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.dx * dt; p.y += p.dy * dt;
    p.dy += 0.12 * dt;
    p.life -= p.decay * dt;
    if (p.life <= 0) particles.splice(i, 1);
  }
  for (let i = floatTexts.length - 1; i >= 0; i--) {
    const t = floatTexts[i];
    t.y -= 0.7 * dt; t.life -= 0.02 * dt;
    if (t.life <= 0) floatTexts.splice(i, 1);
  }

  if (state === 'levelclear') {
    levelTimer -= dt;
    if (levelTimer <= 0) nextLevel();
    return;
  }
  if (state !== 'playing' && state !== 'serve') return;

  /* --- paddle: keyboard + pointer --- */
  let kb = false;
  if (keys['ArrowLeft']  || keys['KeyA']) { paddle.x -= paddle.speed * dt; kb = true; }
  if (keys['ArrowRight'] || keys['KeyD']) { paddle.x += paddle.speed * dt; kb = true; }
  if (kb) paddle.targetX = null;
  else if (paddle.targetX != null)
    paddle.x += (paddle.targetX - paddle.x) * Math.min(1, 0.45 * dt);
  paddle.x = Math.max(WALL_L + paddle.w / 2, Math.min(WALL_R - paddle.w / 2, paddle.x));

  if (state === 'serve') {
    ball.x = paddle.x;
    ball.y = paddle.y - ball.r - 2;
    return;
  }

  /* --- ball with sub-stepping (no tunneling) --- */
  trail.push({ x: ball.x, y: ball.y });
  if (trail.length > 14) trail.shift();

  const moveX = ball.dx * dt, moveY = ball.dy * dt;
  const steps = Math.max(1, Math.ceil(Math.max(Math.abs(moveX), Math.abs(moveY)) / (ball.r * 0.75)));
  const sx = moveX / steps, sy = moveY / steps;

  for (let s = 0; s < steps; s++) {
    ball.x += sx; ball.y += sy;

    // walls
    if (ball.x - ball.r < WALL_L)      { ball.x = WALL_L + ball.r; ball.dx =  Math.abs(ball.dx); sfx.wall(); }
    else if (ball.x + ball.r > WALL_R) { ball.x = WALL_R - ball.r; ball.dx = -Math.abs(ball.dx); sfx.wall(); }
    if (ball.y - ball.r < WALL_T)      { ball.y = WALL_T + ball.r; ball.dy =  Math.abs(ball.dy); sfx.wall(); }

    // paddle — angle reflection based on hit position
    if (ball.dy > 0 &&
        ball.y + ball.r >= paddle.y &&
        ball.y - ball.r <= paddle.y + paddle.h &&
        ball.x >= paddle.x - paddle.w / 2 - ball.r * 0.5 &&
        ball.x <= paddle.x + paddle.w / 2 + ball.r * 0.5) {
      const hitPos = Math.max(-1, Math.min(1, (ball.x - paddle.x) / (paddle.w / 2)));
      const ang = hitPos * Math.PI * 0.36;           // up to ~65° from vertical
      ball.dx = ball.speed * Math.sin(ang);
      ball.dy = -Math.abs(ball.speed * Math.cos(ang));
      ball.y = paddle.y - ball.r - 0.5;
      sfx.paddle();
      spawnParticles(ball.x, paddle.y, '#00e5ff', 6, 0.5);
    }

    // bricks — side-aware reflection using previous sub-step position
    for (const b of bricks) {
      if (!b.alive) continue;
      if (ball.x + ball.r < b.x || ball.x - ball.r > b.x + b.w ||
          ball.y + ball.r < b.y || ball.y - ball.r > b.y + b.h) continue;
      const prevX = ball.x - sx, prevY = ball.y - sy;
      if (prevX + ball.r <= b.x)           { ball.dx = -Math.abs(ball.dx); ball.x = b.x - ball.r - 0.1; }
      else if (prevX - ball.r >= b.x + b.w){ ball.dx =  Math.abs(ball.dx); ball.x = b.x + b.w + ball.r + 0.1; }
      else if (prevY + ball.r <= b.y)      { ball.dy = -Math.abs(ball.dy); ball.y = b.y - ball.r - 0.1; }
      else                                 { ball.dy =  Math.abs(ball.dy); ball.y = b.y + b.h + ball.r + 0.1; }
      hitBrick(b);
      break;
    }
    if (state !== 'playing') break;   // level cleared mid-step
  }

  // lost ball
  if (ball.y - ball.r > H + 20) {
    lives--;
    sfx.lose();
    spawnParticles(Math.max(WALL_L, Math.min(WALL_R, ball.x)), H - 12, '#ff2d75', 24, 1.4);
    if (lives <= 0) gameOver();
    else { resetBall(); state = 'serve'; }
  }
}

/* ================= Draw ================= */
function rr(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawCenterText(text, y, size, color, alpha = 1) {
  ctx.save();
  ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
  ctx.font = "bold " + size + "px 'Courier New', monospace";
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = color;
  ctx.shadowBlur = 18;
  ctx.fillStyle = color;
  ctx.fillText(text, W / 2, y);
  ctx.restore();
}

function drawWalls() {
  ctx.save();
  ctx.strokeStyle = '#00e5ff';
  ctx.shadowColor = '#00e5ff';
  ctx.shadowBlur = 14;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(WALL_L, H);
  ctx.lineTo(WALL_L, WALL_T);
  ctx.lineTo(WALL_R, WALL_T);
  ctx.lineTo(WALL_R, H);
  ctx.stroke();
  ctx.restore();
}

function drawHUD() {
  ctx.save();
  ctx.font = "bold 20px 'Courier New', monospace";
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  ctx.shadowColor = '#00e5ff'; ctx.shadowBlur = 8; ctx.fillStyle = '#00e5ff';
  ctx.fillText('SCORE ' + score, WALL_L + 8, 32);
  ctx.textAlign = 'center';
  ctx.shadowColor = '#ff2d95'; ctx.fillStyle = '#ff2d95';
  ctx.fillText('LEVEL ' + level, W / 2, 32);
  // lives as glowing balls
  ctx.shadowColor = '#39ff6a'; ctx.fillStyle = '#39ff6a';
  const startX = WALL_R - 16;
  for (let i = 0; i < lives; i++) {
    ctx.beginPath();
    ctx.arc(startX - i * 22, 32, 6, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.textAlign = 'right';
  ctx.fillText('LIVES', startX - lives * 22 - 4, 32);
  // small secondary row
  ctx.shadowBlur = 0;
  ctx.globalAlpha = 0.45;
  ctx.font = "12px 'Courier New', monospace";
  ctx.fillStyle = '#8ad';
  ctx.textAlign = 'left';
  ctx.fillText('BEST ' + Math.max(best, score), WALL_L + 8, 50);
  ctx.textAlign = 'right';
  ctx.fillText((muted ? 'MUTED' : 'SOUND') + ' [M]  PAUSE [P]', WALL_R - 8, 50);
  ctx.restore();
}

function drawBrick(b) {
  ctx.save();
  const ratio = b.hits / b.maxHits;
  ctx.shadowColor = b.color;
  ctx.shadowBlur = 12;
  ctx.globalAlpha = 0.5 + 0.5 * ratio;      // damaged bricks look dimmer
  ctx.fillStyle = b.color;
  rr(b.x, b.y, b.w, b.h, 5);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
  ctx.fillStyle = 'rgba(255,255,255,0.28)'; // gloss
  rr(b.x + 3, b.y + 3, b.w - 6, b.h * 0.38, 3);
  ctx.fill();
  if (b.maxHits > 1) {                       // durability pips
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    for (let i = 0; i < b.hits; i++) {
      ctx.beginPath();
      ctx.arc(b.x + b.w / 2 + (i - (b.hits - 1) / 2) * 10, b.y + b.h - 6, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawPaddle() {
  ctx.save();
  const px = paddle.x - paddle.w / 2;
  const g = ctx.createLinearGradient(px, 0, px + paddle.w, 0);
  g.addColorStop(0, '#0077ff');
  g.addColorStop(0.5, '#00e5ff');
  g.addColorStop(1, '#0077ff');
  ctx.shadowColor = '#00e5ff';
  ctx.shadowBlur = 18;
  ctx.fillStyle = g;
  rr(px, paddle.y, paddle.w, paddle.h, 7);
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  rr(px + 4, paddle.y + 2, paddle.w - 8, 4, 2);
  ctx.fill();
  ctx.restore();
}

function drawBall() {
  ctx.save();
  for (let i = 0; i < trail.length; i++) {   // motion trail
    const t = trail[i];
    ctx.globalAlpha = (i / trail.length) * 0.35;
    ctx.fillStyle = '#00e5ff';
    ctx.beginPath();
    ctx.arc(t.x, t.y, ball.r * (0.4 + 0.6 * i / trail.length), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 20;
  const g = ctx.createRadialGradient(ball.x - 2, ball.y - 2, 1, ball.x, ball.y, ball.r);
  g.addColorStop(0, '#ffffff');
  g.addColorStop(0.6, '#aef7ff');
  g.addColorStop(1, '#00b7d4');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawParticles() {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';  // additive glow
  for (const p of particles) {
    ctx.globalAlpha = Math.max(0, p.life);
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
  }
  ctx.restore();
}

function drawFloatTexts() {
  ctx.save();
  ctx.font = "bold 15px 'Courier New', monospace";
  ctx.textAlign = 'center';
  for (const t of floatTexts) {
    ctx.globalAlpha = Math.max(0, t.life);
    ctx.shadowColor = t.color;
    ctx.shadowBlur = 8;
    ctx.fillStyle = '#fff';
    ctx.fillText(t.text, t.x, t.y);
  }
  ctx.restore();
}

function draw() {
  const now = performance.now();
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#070714');
  bg.addColorStop(1, '#0d0518');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  for (const st of stars) {                  // twinkling starfield
    ctx.globalAlpha = Math.max(0.05, 0.25 + 0.3 * Math.sin(now * 0.001 * st.s + st.p));
    ctx.fillStyle = '#9df';
    ctx.fillRect(st.x, st.y, st.r, st.r);
  }
  ctx.globalAlpha = 1;

  ctx.strokeStyle = 'rgba(0,229,255,0.05)';  // faint grid
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = WALL_L; x <= WALL_R; x += 44) { ctx.moveTo(x, WALL_T); ctx.lineTo(x, H); }
  for (let y = WALL_T; y <= H; y += 44)      { ctx.moveTo(WALL_L, y); ctx.lineTo(WALL_R, y); }
  ctx.stroke();

  drawWalls();
  drawHUD();
  for (const b of bricks) if (b.alive) drawBrick(b);
  drawParticles();
  drawPaddle();
  if (state !== 'levelclear') drawBall();
  drawFloatTexts();

  if (state === 'serve')
    drawCenterText('CLICK / TAP / SPACE TO LAUNCH', H * 0.62, 18, '#8ff', 0.5 + 0.5 * Math.sin(now * 0.005));
  if (state === 'levelclear') {
    drawCenterText('LEVEL ' + level + ' CLEARED!', H * 0.45, 44, '#ffe600');
    drawCenterText('BONUS +' + levelBonus, H * 0.45 + 46, 22, '#39ff6a');
  }
  if (state === 'paused') {
    ctx.fillStyle = 'rgba(0,0,10,0.6)';
    ctx.fillRect(0, 0, W, H);
    drawCenterText('PAUSED', H * 0.5, 48, '#00e5ff');
    drawCenterText('Press P to resume', H * 0.5 + 48, 18, '#8ff');
  }
}

/* ================= Main loop (frame-rate independent) ================= */
let last = performance.now();
function loop(t) {
  requestAnimationFrame(loop);
  let dt = (t - last) / 16.667;
  last = t;
  if (dt > 4) dt = 4;
  if (state !== 'paused') update(dt);
  draw();
}

/* ================= Input ================= */
function screenToGameX(clientX) {
  const rect = canvas.getBoundingClientRect();
  return (clientX - rect.left) / rect.width * W;
}

canvas.addEventListener('mousemove', e => { paddle.targetX = screenToGameX(e.clientX); });
canvas.addEventListener('mousedown', e => {
  ensureAudio();
  paddle.targetX = screenToGameX(e.clientX);
  if (state === 'serve') launchBall();
});
canvas.addEventListener('touchstart', e => {
  e.preventDefault();
  ensureAudio();
  if (e.touches.length) paddle.targetX = screenToGameX(e.touches[0].clientX);
  if (state === 'serve') launchBall();
}, { passive: false });
canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  if (e.touches.length) paddle.targetX = screenToGameX(e.touches[0].clientX);
}, { passive: false });

window.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (['ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
  if (e.code === 'Space') { ensureAudio(); if (state === 'serve') launchBall(); }
  if (e.code === 'KeyM') muted = !muted;
  if (e.code === 'KeyP' || e.code === 'Escape') {
    if (state === 'playing' || state === 'serve') { prevState = state; state = 'paused'; }
    else if (state === 'paused') state = prevState;
  }
  if (e.code === 'Enter' && (state === 'start' || state === 'gameover' || state === 'victory')) startGame();
});
window.addEventListener('keyup', e => { keys[e.code] = false; });
window.addEventListener('blur', () => { if (state === 'playing') { prevState = state; state = 'paused'; } });

document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('retryBtn').addEventListener('click', startGame);
document.getElementById('winBtn').addEventListener('click', startGame);

/* ================= Boot ================= */
updateBestLabel();
buildLevel(1);
resetBall();
requestAnimationFrame(loop);

})();
</script>
</body>
</html>
```

**What's inside:**

1. **Physics** — angle-based paddle reflection (hit position maps to bounce angle up to ~65°), side-aware brick reflection using previous sub-step position, and movement sub-stepping so the ball never tunnels through bricks at high speed.
2. **Controls** — mouse (smooth easing follow), touch (drag + tap to launch), and keyboard (←/→ or A/D, Space to launch, P pause, M mute, Enter to restart).
3. **Progression** — 5 hand-designed level patterns with multi-hit bricks (durability pips shown), shrinking paddle, and gradually increasing ball speed; score, lives, level, and persistent best score (localStorage) in the HUD.
4. **Screens** — animated neon start, game-over, and victory overlays, plus an in-canvas "level cleared" bonus interstitial.
5. **Effects** — additive-blend particle bursts on brick break, floating score popups, ball motion trail, twinkling starfield, CRT scanlines, and glow everywhere via shadowBlur.
6. **Audio** — fully synthesized with the Web Audio API (no assets): filtered noise bursts for breaks, pitch-swept blips for paddle/walls, arpeggios for level-clear and victory, and a descending saw for game over.
7. **Responsive** — fixed 800×600 logical space scaled to any window with devicePixelRatio-aware rendering for crisp lines on retina/mobile.

