<script>
(() => {
  "use strict";
  const REDUCED = matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------------- Data ---------------- */
  // Last 7 days of focus scores; last entry = today.
  const scores = [52, 64, 58, 71, 66, 74, 82];

  const dayFmt  = new Intl.DateTimeFormat("en-US", { weekday: "short" });
  const dateFmt = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "short", day: "numeric" });
  const labels = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i));
    return i === 6 ? "Today" : dayFmt.format(d);
  });

  /* ---------------- Header ---------------- */
  document.getElementById("dateLine").textContent = dateFmt.format(new Date());

  const chip = document.getElementById("deltaChip");
  function renderChip() {
    const diff = scores[6] - scores[5];
    chip.className = "chip " + (diff > 0 ? "up" : diff < 0 ? "down" : "flat");
    chip.textContent = diff > 0 ? `▲ +${diff} vs yesterday`
                     : diff < 0 ? `▼ ${diff} vs yesterday`
                     : "— level with yesterday";
  }

  /* ---------------- Stats ---------------- */
  function tierFor(s) {
    return s >= 90 ? "Peak" : s >= 75 ? "Strong" : s >= 60 ? "Steady" : s >= 40 ? "Building" : "Warming up";
  }
  function renderStats() {
    let streak = 0;
    for (let i = scores.length - 1; i >= 0 && scores[i] >= 60; i--) streak++;
    const avg  = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    const maxI = scores.indexOf(Math.max(...scores));
    document.getElementById("statStreak").textContent = streak + "d";
    document.getElementById("statAvg").textContent = avg;
    document.getElementById("statBest").textContent = `${scores[maxI]} · ${labels[maxI]}`;
    document.getElementById("sparkAvg").textContent = `avg ${avg}`;
    document.getElementById("tier").textContent = tierFor(scores[6]);
  }

  /* ---------------- Score ring ---------------- */
  const ringFill = document.getElementById("ringFill");
  const scoreNum = document.getElementById("scoreNum");
  const C = 2 * Math.PI * 52;
  ringFill.style.strokeDasharray = C;
  ringFill.style.strokeDashoffset = C;

  let shownScore = 0;
  function animateScore(from, to, dur = 1200) {
    if (REDUCED) { setScore(to); return; }
    const t0 = performance.now();
    (function frame(now) {
      const t = Math.min(1, (now - t0) / dur);
      const e = 1 - Math.pow(1 - t, 3); // easeOutCubic
      setScore(from + (to - from) * e);
      if (t < 1) requestAnimationFrame(frame);
    })(t0);
  }
  function setScore(v) {
    shownScore = v;
    scoreNum.textContent = Math.round(v);
    ringFill.style.strokeDashoffset = C * (1 - v / 100);
  }

  /* ---------------- Sparkline ---------------- */
  const canvas = document.getElementById("sparkline");
  const ctx = canvas.getContext("2d");
  const tip = document.getElementById("tip");
  let pts = [], hoverI = -1;

  function smoothPath(c, p) {
    c.moveTo(p[0].x, p[0].y);
    for (let i = 1; i < p.length - 2; i++) {
      const xc = (p[i].x + p[i + 1].x) / 2, yc = (p[i].y + p[i + 1].y) / 2;
      c.quadraticCurveTo(p[i].x, p[i].y, xc, yc);
    }
    c.quadraticCurveTo(p[p.length - 2].x, p[p.length - 2].y, p[p.length - 1].x, p[p.length - 1].y);
  }

  function drawSpark(reveal = 1) {
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth, h = canvas.clientHeight;
    canvas.width = w * dpr; canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    const padX = 8, padT = 10, padB = 8;
    const lo = Math.min(...scores) - 8, hi = Math.max(...scores) + 8;
    const X = i => padX + (i / (scores.length - 1)) * (w - padX * 2);
    const Y = v => padT + (1 - (v - lo) / (hi - lo)) * (h - padT - padB);
    pts = scores.map((v, i) => ({ x: X(i), y: Y(v), v }));

    // Weekly average guide
    const avg = scores.reduce((a, b) => a + b, 0) / scores.length;
    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,.10)";
    ctx.setLineDash([4, 5]);
    ctx.beginPath();
    ctx.moveTo(0, Y(avg)); ctx.lineTo(w, Y(avg));
    ctx.stroke();
    ctx.restore();

    // Left-to-right reveal wipe
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, w * reveal + 2, h);
    ctx.clip();

    // Area fill
    const fillG = ctx.createLinearGradient(0, 0, 0, h);
    fillG.addColorStop(0, "rgba(139,92,246,.32)");
    fillG.addColorStop(1, "rgba(139,92,246,0)");
    ctx.beginPath();
    smoothPath(ctx, pts);
    ctx.lineTo(pts[pts.length - 1].x, h);
    ctx.lineTo(pts[0].x, h);
    ctx.closePath();
    ctx.fillStyle = fillG;
    ctx.fill();

    // Line
    const lineG = ctx.createLinearGradient(0, 0, w, 0);
    lineG.addColorStop(0, "#8b5cf6");
    lineG.addColorStop(1, "#22d3ee");
    ctx.beginPath();
    smoothPath(ctx, pts);
    ctx.strokeStyle = lineG;
    ctx.lineWidth = 2.5;
    ctx.lineJoin = "round";
    ctx.shadowColor = "rgba(139,92,246,.6)";
    ctx.shadowBlur = 8;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Dots
    pts.forEach((p, i) => {
      const today = i === pts.length - 1;
      const hov = i === hoverI;
      if (today || hov) {
        ctx.beginPath();
        ctx.arc(p.x, p.y, hov ? 8 : 6, 0, Math.PI * 2);
        ctx.fillStyle = hov ? "rgba(34,211,238,.18)" : "rgba(34,211,238,.15)";
        ctx.fill();
      }
      ctx.beginPath();
      ctx.arc(p.x, p.y, today ? 4 : hov ? 4 : 2.5, 0, Math.PI * 2);
      ctx.fillStyle = today || hov ? "#22d3ee" : "rgba(233,237,245,.75)";
      ctx.fill();
    });
    ctx.restore();
  }

  function animateSpark() {
    if (REDUCED) { drawSpark(1); return; }
    const t0 = performance.now(), dur = 900;
    (function frame(now) {
      const t = Math.min(1, (now - t0) / dur);
      drawSpark(1 - Math.pow(1 - t, 3));
      if (t < 1) requestAnimationFrame(frame);
    })(t0);
  }

  // Hover tooltip
  canvas.addEventListener("pointermove", e => {
    const r = canvas.getBoundingClientRect();
    const x = e.clientX - r.left;
    let best = -1, bd = Infinity;
    pts.forEach((p, i) => { const d = Math.abs(p.x - x); if (d < bd) { bd = d; best = i; } });
    if (best !== hoverI) { hoverI = best; drawSpark(1); }
    const p = pts[hoverI];
    tip.innerHTML = `${labels[hoverI]} · <b>${scores[hoverI]}</b>`;
    tip.style.left = p.x + "px";
    tip.style.top = p.y + "px";
    tip.style.opacity = 1;
  });
  canvas.addEventListener("pointerleave", () => { hoverI = -1; tip.style.opacity = 0; drawSpark(1); });
  window.addEventListener("resize", () => drawSpark(1));

  // Day labels
  const dayRow = document.getElementById("dayLabels");
  labels.forEach((l, i) => {
    const s = document.createElement("span");
    s.textContent = l;
    if (i === 6) s.classList.add("today");
    dayRow.appendChild(s);
  });

  /* ---------------- Focus session timer ---------------- */
  const SESSION = 25 * 60; // 25 minutes
  const btn = document.getElementById("focusBtn");
  const endBtn = document.getElementById("endBtn");
  const baseTitle = document.title;
  let state = "idle", endAt = 0, remaining = SESSION, tickId = null;

  const fmt = s => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(Math.ceil(s % 60)).padStart(2, "0")}`;

  function paintButton() {
    btn.classList.toggle("done", state === "done");
    endBtn.style.visibility = (state === "running" || state === "paused") ? "visible" : "hidden";
    if (state === "idle")    btn.innerHTML = "Start Focus";
    if (state === "running") btn.innerHTML = `<span class="time">${fmt(remaining)}</span> &nbsp;·&nbsp; Stay with it<div class="progress"></div>`;
    if (state === "paused")  btn.innerHTML = `<span class="time">${fmt(remaining)}</span> &nbsp;·&nbsp; Paused — tap to resume<div class="progress"></div>`;
    if (state === "done")    btn.innerHTML = "✓ Session complete — go again";
  }

  function tick() {
    remaining = Math.max(0, (endAt - Date.now()) / 1000);
    const bar = btn.querySelector(".progress");
    if (bar) bar.style.width = ((1 - remaining / SESSION) * 100) + "%";
    btn.querySelector(".time").textContent = fmt(remaining);
    document.title = `${fmt(remaining)} • Focus`;
    if (remaining <= 0) complete();
  }

  function start() {
    endAt = Date.now() + (state === "paused" ? remaining : SESSION) * 1000;
    if (state !== "paused") remaining = SESSION;
    state = "running";
    clearInterval(tickId);
    tickId = setInterval(tick, 200);
    paintButton(); tick();
  }
  function pause() {
    state = "paused";
    remaining = Math.max(0, (endAt - Date.now()) / 1000);
    clearInterval(tickId);
    document.title = baseTitle;
    paintButton();
  }
  function end() {
    state = "idle";
    clearInterval(tickId);
    remaining = SESSION;
    document.title = baseTitle;
    paintButton();
  }
  function complete() {
    clearInterval(tickId);
    state = "done";
    document.title = baseTitle;
    // Reward: boost today's score and refresh everything
    const before = scores[6];
    scores[6] = Math.min(100, scores[6] + 10);
    renderChip(); renderStats(); drawSpark(1);
    animateScore(before, scores[6], 800);
    paintButton();
  }

  btn.addEventListener("click", () => {
    if (state === "idle" || state === "done") start();
    else if (state === "running") pause();
    else if (state === "paused") start();
  });
  endBtn.addEventListener("click", end);

  /* ---------------- Init ---------------- */
  renderChip();
  renderStats();
  animateSpark();
  animateScore(0, scores[6]);
})();
</script>
</body>
</html>
```

**What's inside:**
1. **Focus score ring** — SVG circle with a gradient stroke that animates on load while the number counts up (easeOutCubic), plus a tier label ("Strong", "Steady", etc.).
2. **Weekly sparkline** — drawn on `<canvas>` with a smoothed curve, gradient area fill, dashed weekly-average guide, a left-to-right reveal animation, and hover tooltips showing each day's score. Day labels are generated from the real current date.
3. **Start Focus button** — runs an actual 25-minute session: click to start, click again to pause/resume, with a live countdown, progress bar inside the button, and the tab title updating. Completing a session awards +10 to today's score and re-animates the ring, chip, and stats.
4. **Extras** — computed streak/avg/best stats, delta chip vs. yesterday, `devicePixelRatio`-sharp canvas, resize handling, and `prefers-reduced-motion` support.

Just save it as an `.html` file and open it in any browser — zero dependencies, zero network requests.

I’m answering strictly under **ICH E6(R2) GCP**. If this is being used in a regulatory submission or inspection response, verify the exact subsection numbering against the official ICH text and applicable local regulations, because some ICH formatting/implementation documents present subsections slightly differently.

---

## 1. Centralized-only monitoring without on-site visits under ICH E6(R2)

### Requirement

**ICH E6(R2) does not impose a universal requirement for routine on-site monitoring at every investigative site.** It permits monitoring to be performed using **on-site visits, centralized monitoring, or a combination**, provided the sponsor ensures that monitoring is **adequate and appropriately targeted**.

However, **centralized-only monitoring is not automatically acceptable**. It is acceptable only if the sponsor can demonstrate that centralized monitoring alone will still satisfy the core GCP monitoring objectives:

1. Protection of subjects’ rights, safety, and well-being.
2. Accuracy, completeness, and verifiability of the reported trial data from source documents.
3. Compliance of trial conduct with the approved protocol, GCP, and applicable regulatory requirements.

So, for your Phase III oncology trial, a sponsor may propose a centralized monitoring model, but it must justify how it will verify critical site-level data and processes without physical site visits. If critical source data, investigational product accountability, consent documentation, safety reporting, or endpoint assessments cannot be adequately verified remotely, then **on-site or targeted site visits would still be needed**.

### Relevant ICH E6(R2) citations

- **ICH E6(R2) Section 5.18.1 — Monitoring objectives**  
  Monitoring must verify that:
  - subjects’ rights and well-being are protected;
  - reported trial data are accurate, complete, and verifiable from source documents;
  - trial conduct complies with the approved protocol, GCP, and applicable regulatory requirements.

- **ICH E6(R2) Section 5.18.2 — Selection of monitoring methods**  
  This is the key provision for risk-based and centralized monitoring. It requires adequate and appropriately targeted monitoring and recognizes that monitoring may be performed by on-site visits, centralized monitoring, or a combination.  
  *Note: The exact placement of the “centralized monitoring” language is commonly cited to Section 5.18.2, but verify against the official ICH text if quoting precisely.*

- **ICH E6(R2) Section 5.18.3 — Extent and nature of monitoring**  
  The extent and nature of monitoring should be determined based on factors such as the trial’s objectives, complexity, importance, size, endpoints, and risks. Monitoring should be performed in accordance with the sponsor’s SOPs and monitoring plan.

- **ICH E6(R2) Section 5.18.4 — Monitor’s responsibilities**  
  The monitor should verify site-related matters such as investigator qualifications, resources, investigational product handling/accountability, trial records, subject safety, protocol compliance, and other site-level obligations.

- **ICH E6(R2) Section 5.18.5 — Monitoring procedures**  
  The monitor should verify the accuracy and completeness of case report forms, source documents, and other trial-related records. This is where source data verification responsibilities are most directly addressed.

- **ICH E6(R2) Section 5.0 — Sponsor responsibilities, including delegation to a CRO**  
  Even if the CRO designs or performs the monitoring, the sponsor retains ultimate responsibility for trial conduct and data integrity. Any delegation to a CRO should be documented, and the sponsor should maintain appropriate oversight.

- **ICH E6(R2) Section 4.9 — Investigator obligations related to monitoring**  
  The investigator should permit monitoring by the sponsor and provide access to source documents and other trial-related records.

### What ICH E6(R2) says about verifying data at investigative sites

The guideline requires the monitor to verify that the reported trial data are:

> **accurate, complete, and verifiable from source documents.**

In practical terms, this means the monitor must be able to compare the data reported in the CRF/eCRF with the underlying source records, such as:

- medical records;
- hospital charts;
- laboratory reports;
- pathology reports;
- imaging reports;
- oncology treatment records;
- adverse event documentation;
- concomitant medication records;
- informed consent forms;
- eligibility criteria documentation;
- investigational product administration and accountability records;
- protocol deviation records.

If monitoring is centralized, this verification may be done remotely, for example through:

- remote access to electronic source records;
- scanned source documents;
- EHR-integrated eSource;
- central review of imaging, labs, or ECGs;
- statistical/data-driven monitoring;
- remote review of consent forms and essential documents;
- telephone or videoconference follow-up with site staff.

But the method does not remove the obligation. If the monitor cannot verify critical data remotely, the monitoring plan should include escalation to an on-site visit.

### Exceptions, conditions, and practical limitations

A centralized-only monitoring plan may be defensible under ICH E6(R2) only if the sponsor can show that:

1. The trial’s risks have been assessed and are adequately controlled.
2. Critical data are available remotely in a verifiable form.
3. Subject rights and safety can be protected without physical site presence.
4. Investigational product accountability can be verified remotely.
5. Informed consent documentation can be reviewed remotely.
6. There are predefined triggers for on-site visits if issues arise.
7. The monitoring plan is documented, approved, and maintained.
8. Local regulations, IRB/IEC expectations, and institutional policies do not require on-site visits.

For a **Phase III randomized oncology trial**, centralized-only monitoring with absolutely no on-site visits would be difficult to justify unless the sponsor has a very robust remote verification strategy. Oncology trials often involve:

- complex eligibility criteria;
- serious adverse events;
- dose modifications;
- tumor response assessments;
- imaging endpoints;
- pathology confirmation;
- biomarker or genetic testing;
- high-risk investigational products;
- vulnerable patients;
- complex investigational product handling;
- critical endpoint adjudication.

If those elements cannot be verified remotely, the sponsor should include at least **risk-triggered on-site visits**, and possibly site initiation, for-cause, or close-out visits.

A safer regulatory position is usually not “centralized monitoring with no on-site visits under any circumstances,” but rather:

> **Centralized monitoring as the primary strategy, with predefined risk-based escalation to on-site visits when source data cannot be verified remotely or when quality/safety signals arise.**

---

## 2. Investigator responsibilities for obtaining informed consent under ICH E6(R2)

### Requirement

Under ICH E6(R2), the investigator is responsible for ensuring that each subject gives **freely given informed consent before participating in the trial**. The investigator must ensure that the subject receives adequate information, has the opportunity to ask questions, is not coerced or unduly influenced, and that consent is properly documented.

The investigator may delegate the consent discussion to appropriately qualified and trained study staff, but the investigator remains responsible for ensuring that informed consent is properly obtained.

### Relevant ICH E6(R2) citations

The primary provision is:

- **ICH E6(R2) Section 4.8 — Informed Consent of Trial Subjects**

Key principles in Section 4.8 include:

- consent must be freely given;
- consent must be obtained before trial participation;
- the subject must receive adequate information about the trial;
- the subject must have adequate opportunity to ask questions;
- the subject may withdraw at any time without penalty;
- consent should be documented in writing;
- the signed consent form should be provided to the subject;
- special rules apply for subjects unable to consent, subjects unable to read/write, and emergency situations;
- subjects must be informed of new information that may affect their willingness to continue;
- consent materials must be updated when important new information becomes available.

Additional relevant principles:

- **ICH E6(R2) Section 2.5**  
  The rights, safety, and well-being of trial subjects are the overriding considerations.

- **ICH E6(R2) Section 3 — IRB/IEC responsibilities**  
  The informed consent form and other written subject information should be reviewed and approved by the IRB/IEC before use.  
  *The precise subsection should be verified if quoting formally, but the principle is in the IRB/IEC review provisions of Section 3.*

### Core investigator obligations

The investigator should ensure that:

1. **Consent is obtained before any trial-specific procedure.**  
   The subject should not undergo trial-specific screening procedures unless consent has been obtained, unless those procedures are part of standard clinical care and not performed solely for the trial.

2. **The subject receives adequate information.**  
   The information should be understandable and should include, as applicable:
   - the nature and purpose of the trial;
   - trial procedures;
   - expected duration of participation;
   - randomization and treatment assignment probabilities;
   - foreseeable risks and discomforts;
   - expected benefits;
   - alternative treatments available;
   - confidentiality of records;
   - compensation and medical treatment for trial-related injury, if applicable;
   - anticipated payments or expenses, if applicable;
   - voluntary nature of participation;
   - right to withdraw at any time without penalty or loss of benefits to which the subject is otherwise entitled.

3. **The subject has adequate opportunity to ask questions.**  
   The consent process should not be rushed. The subject should be allowed time to consider participation and consult family or others if desired.

4. **Consent is voluntary.**  
   There should be no coercion or undue influence. This is especially important in oncology, where patients may be seriously ill and may perceive trial participation as their only treatment option.

5. **Consent is documented in writing.**  
   The informed consent form should be signed and dated by:
   - the subject, or the subject’s legally acceptable representative; and
   - the person obtaining consent.

6. **The subject receives a copy of the signed consent form.**  
   The subject should also receive any other written information provided to subjects.

7. **Reconsent is obtained when necessary.**  
   If important new information becomes available that may affect the subject’s willingness to continue, the investigator should inform the subject and obtain reconsent where appropriate.

8. **The consent process is documented.**  
   The investigator should retain signed consent forms and related documentation as essential trial records.

### Exceptions and special conditions

ICH E6(R2) recognizes several special situations:

1. **Subject unable to give consent**  
   If a subject is incapable of giving informed consent, consent may be obtained from a legally acceptable representative, where permitted by law. The subject should still be informed about the trial to the extent possible, and assent should be sought where appropriate. A subject’s dissent should be respected.

2. **Subject unable to read or write**  
   If the subject cannot read or write, an impartial witness should be present during the entire informed consent discussion. The witness should attest that the information was accurately explained and that consent was given voluntarily.

3. **Emergency situations**  
   If prior consent cannot be obtained because of the subject’s medical condition, enrollment may proceed only if the protocol and IRB/IEC have approved appropriate procedures and local regulations permit it. Consent should be obtained from a legally acceptable representative if available, and the subject should be informed as soon as possible.

4. **New safety information or protocol amendments**  
   If new information arises that may affect the subject’s willingness to continue, the investigator should ensure the subject is informed and reconsent is obtained when appropriate.

5. **Local legal and ethical requirements**  
   ICH E6(R2) sets minimum GCP standards. Local law, IRB/IEC requirements, or institutional policy may impose additional consent requirements, especially for:
   - minors;
   - pregnant or nursing subjects;
   - genetically vulnerable populations;
   - tissue/biobank sampling;
   - data privacy;
   - compensation for injury;
   - use of placebo or withdrawal of standard therapy.

---

## Bottom line for the CRO monitoring plan

For the Phase III oncology trial, the CRO should not simply state that monitoring will be “centralized only with no on-site visits” unless the sponsor can fully justify that model under ICH E6(R2). The monitoring plan should instead describe:

- how subject rights and safety will be protected;
- how critical data will be verified from source documents;
- whether source documents are available remotely;
- which data will undergo centralized source data verification;
- how investigational product accountability will be verified;
- how informed consent documentation will be verified;
- how protocol deviations and safety events will be monitored;
- what metrics or signals will trigger an on-site visit;
- how the sponsor will maintain oversight of the CRO.

Under ICH E6(R2), centralized monitoring is permitted, but it must still achieve the same fundamental GCP assurance as any other monitoring strategy: **subject protection and data integrity must be verifiable.**

Here's a complete, self-contained dark-mode focus dashboard card. Everything — the animated score ring, the sparkline, and the live session timer — is generated with inline SVG, CSS, and vanilla JS:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Focus Dashboard</title>
<style>
  :root {
    --bg: #0a0c12;
    --card: #12161f;
    --card-2: #171c28;
    --border: rgba(255, 255, 255, 0.07);
    --text: #e8ecf3;
    --muted: #8a93a6;
    --accent-1: #7c5cff;
    --accent-2: #22d3ee;
    --danger: #ff5c7a;
    --radius: 20px;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: radial-gradient(1200px 600px at 50% -10%, #1a1f35 0%, var(--bg) 60%);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--text);
    padding: 24px;
  }

  .card {
    width: 100%;
    max-width: 420px;
    background: linear-gradient(160deg, var(--card-2) 0%, var(--card) 55%);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 28px;
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.5),
                inset 0 1px 0 rgba(255, 255, 255, 0.04);
  }

  /* ---------- Header ---------- */
  .card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 24px;
  }
  .card-header h1 { font-size: 18px; font-weight: 650; letter-spacing: -0.01em; }
  .card-header .date { font-size: 13px; color: var(--muted); margin-top: 3px; }

  .badge {
    font-size: 12px;
    font-weight: 600;
    color: #4ade80;
    background: rgba(74, 222, 128, 0.1);
    border: 1px solid rgba(74, 222, 128, 0.2);
    padding: 4px 10px;
    border-radius: 999px;
    white-space: nowrap;
  }

  /* ---------- Score section ---------- */
  .score-section {
    display: flex;
    align-items: center;
    gap: 24px;
    margin-bottom: 26px;
  }

  .ring-wrap { position: relative; width: 132px; height: 132px; flex-shrink: 0; }
  .ring-wrap svg { transform: rotate(-90deg); }

  .ring-track { stroke: rgba(255, 255, 255, 0.07); }
  .ring-progress {
    stroke-dasharray: 339.292;
    stroke-dashoffset: 339.292;
    transition: stroke-dashoffset 1.4s cubic-bezier(0.22, 1, 0.36, 1);
    filter: drop-shadow(0 0 6px rgba(124, 92, 255, 0.45));
  }

  .ring-label {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
  }
  .ring-label .value { font-size: 34px; font-weight: 700; letter-spacing: -0.02em; line-height: 1; }
  .ring-label .value small { font-size: 14px; font-weight: 500; color: var(--muted); }
  .ring-label .caption { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; margin-top: 5px; }

  .stats { display: flex; flex-direction: column; gap: 14px; flex: 1; }
  .stat { display: flex; flex-direction: column; gap: 2px; }
  .stat .stat-value { font-size: 16px; font-weight: 650; }
  .stat .stat-label { font-size: 12px; color: var(--muted); }

  /* ---------- Sparkline ---------- */
  .spark-section { margin-bottom: 24px; }
  .spark-section h2 {
    font-size: 12px;
    font-weight: 600;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 12px;
  }

  .spark-wrap { position: relative; }
  .spark-wrap svg { width: 100%; height: auto; display: block; }

  .spark-dot-hit { cursor: pointer; }

  .tooltip {
    position: absolute;
    transform: translate(-50%, -130%);
    background: #1e2433;
    border: 1px solid var(--border);
    color: var(--text);
    font-size: 12px;
    font-weight: 600;
    padding: 5px 9px;
    border-radius: 8px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.15s ease;
    white-space: nowrap;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
  }
  .tooltip.visible { opacity: 1; }
  .tooltip span { color: var(--muted); font-weight: 500; }

  .day-labels {
    display: flex;
    justify-content: space-between;
    margin-top: 8px;
    font-size: 11px;
    color: var(--muted);
  }

  @keyframes pulse {
    0%   { r: 4; opacity: 0.8; }
    100% { r: 11; opacity: 0; }
  }
  .pulse-dot { animation: pulse 1.8s ease-out infinite; }

  /* ---------- Button ---------- */
  .focus-btn {
    width: 100%;
    padding: 15px;
    font-size: 15px;
    font-weight: 650;
    font-family: inherit;
    color: #fff;
    background: linear-gradient(135deg, var(--accent-1), var(--accent-2));
    border: none;
    border-radius: 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s ease;
    box-shadow: 0 8px 24px rgba(124, 92, 255, 0.35);
  }
  .focus-btn:hover { transform: translateY(-2px); filter: brightness(1.08); }
  .focus-btn:active { transform: translateY(0); }

  .focus-btn.running {
    background: rgba(255, 92, 122, 0.12);
    border: 1px solid rgba(255, 92, 122, 0.35);
    color: var(--danger);
    box-shadow: none;
  }
  .focus-btn.done {
    background: rgba(74, 222, 128, 0.12);
    border: 1px solid rgba(74, 222, 128, 0.35);
    color: #4ade80;
    box-shadow: none;
  }

  .live-dot {
    width: 9px; height: 9px;
    border-radius: 50%;
    background: var(--danger);
    animation: blink 1.1s ease-in-out infinite;
  }
  @keyframes blink { 50% { opacity: 0.25; } }

  @media (prefers-reduced-motion: reduce) {
    * { animation: none !important; transition: none !important; }
  }
</style>
</head>
<body>

<div class="card">
  <div class="card-header">
    <div>
      <h1>Daily Focus</h1>
      <p class="date" id="today-date"></p>
    </div>
    <span class="badge" id="trend-badge"></span>
  </div>

  <div class="score-section">
    <div class="ring-wrap">
      <svg width="132" height="132" viewBox="0 0 132 132">
        <defs>
          <linearGradient id="ringGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stop-color="#7c5cff"/>
            <stop offset="100%" stop-color="#22d3ee"/>
          </linearGradient>
        </defs>
        <circle class="ring-track" cx="66" cy="66" r="54" fill="none" stroke-width="10"/>
        <circle class="ring-progress" id="ring" cx="66" cy="66" r="54"
                fill="none" stroke="url(#ringGrad)" stroke-width="10" stroke-linecap="round"/>
      </svg>
      <div class="ring-label">
        <div class="value"><span id="score-num">0</span><small>/100</small></div>
        <div class="caption">Focus score</div>
      </div>
    </div>

    <div class="stats">
      <div class="stat">
        <span class="stat-value" id="deep-work">3h 24m</span>
        <span class="stat-label">Deep work</span>
      </div>
      <div class="stat">
        <span class="stat-value">5</span>
        <span class="stat-label">Sessions</span>
      </div>
      <div class="stat">
        <span class="stat-value">6 days</span>
        <span class="stat-label">Streak</span>
      </div>
    </div>
  </div>

  <div class="spark-section">
    <h2>Weekly trend</h2>
    <div class="spark-wrap" id="spark-wrap">
      <svg id="sparkline" viewBox="0 0 320 90" preserveAspectRatio="none"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
    <div class="day-labels" id="day-labels"></div>
  </div>

  <button class="focus-btn" id="focus-btn"></button>
</div>

<script>
(function () {
  // ---------- Data ----------
  const SCORE = 82;
  const WEEK_DATA = [58, 64, 61, 72, 68, 75, 82]; // Mon -> today
  let deepWorkSeconds = 3 * 3600 + 24 * 60;

  // ---------- Date header & labels ----------
  const now = new Date();
  document.getElementById('today-date').textContent =
    now.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' });

  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const labels = WEEK_DATA.map((_, i) => {
    const d = new Date(now);
    d.setDate(d.getDate() - (WEEK_DATA.length - 1 - i));
    return dayNames[d.getDay()];
  });
  document.getElementById('day-labels').innerHTML =
    labels.map(l => `<span>${l}</span>`).join('');

  // ---------- Trend badge ----------
  const prev = WEEK_DATA[WEEK_DATA.length - 2];
  const delta = Math.round(((SCORE - prev) / prev) * 100);
  document.getElementById('trend-badge').textContent =
    (delta >= 0 ? '▲ +' : '▼ ') + delta + '% vs yesterday';

  // ---------- Animated ring + count-up ----------
  const CIRC = 2 * Math.PI * 54; // 339.292
  requestAnimationFrame(() => {
    document.getElementById('ring').style.strokeDashoffset =
      CIRC * (1 - SCORE / 100);
  });

  const scoreEl = document.getElementById('score-num');
  const DURATION = 1400;
  let start = null;
  function countUp(ts) {
    if (!start) start = ts;
    const p = Math.min((ts - start) / DURATION, 1);
    const eased = 1 - Math.pow(1 - p, 3);
    scoreEl.textContent = Math.round(eased * SCORE);
    if (p < 1) requestAnimationFrame(countUp);
  }
  requestAnimationFrame(countUp);

  // ---------- Sparkline ----------
  const svg = document.getElementById('sparkline');
  const W = 320, H = 90, PAD = 8;
  const min = Math.min(...WEEK_DATA), max = Math.max(...WEEK_DATA);

  const pts = WEEK_DATA.map((v, i) => ({
    x: PAD + (i * (W - PAD * 2)) / (WEEK_DATA.length - 1),
    y: H - PAD - ((v - min) / (max - min)) * (H - PAD * 2),
    v
  }));

  // Catmull-Rom -> cubic Bezier for a smooth curve
  function smoothPath(p) {
    let d = `M ${p[0].x} ${p[0].y}`;
    for (let i = 0; i < p.length - 1; i++) {
      const p0 = p[Math.max(0, i - 1)], p1 = p[i],
            p2 = p[i + 1], p3 = p[Math.min(p.length - 1, i + 2)];
      const c1x = p1.x + (p2.x - p0.x) / 6, c1y = p1.y + (p2.y - p0.y) / 6;
      const c2x = p2.x - (p3.x - p1.x) / 6, c2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2.x} ${p2.y}`;
    }
    return d;
  }

  const lineD = smoothPath(pts);
  const areaD = lineD + ` L ${pts[pts.length - 1].x} ${H} L ${pts[0].x} ${H} Z`;
  const last = pts[pts.length - 1];

  svg.innerHTML = `
    <defs>
      <linearGradient id="lineGrad" x1="0%" y1="0%" x2="100%" y2="0%">
        <stop offset="0%" stop-color="#7c5cff"/>
        <stop offset="100%" stop-color="#22d3ee"/>
      </linearGradient>
      <linearGradient id="areaGrad" x1="0%" y1="0%" x2="0%" y2="100%">
        <stop offset="0%" stop-color="#7c5cff" stop-opacity="0.3"/>
        <stop offset="100%" stop-color="#7c5cff" stop-opacity="0"/>
      </linearGradient>
    </defs>
    <path d="${areaD}" fill="url(#areaGrad)"/>
    <path d="${lineD}" fill="none" stroke="url(#lineGrad)" stroke-width="2.5"
          stroke-linecap="round"/>
    <circle class="pulse-dot" cx="${last.x}" cy="${last.y}" r="4"
            fill="none" stroke="#22d3ee" stroke-width="1.5"/>
    <circle cx="${last.x}" cy="${last.y}" r="4" fill="#22d3ee"/>
    ${pts.map((p, i) => `
      <circle class="spark-dot-hit" data-i="${i}" cx="${p.x}" cy="${p.y}" r="12"
              fill="transparent"/>
      <circle class="spark-dot-vis" data-i="${i}" cx="${p.x}" cy="${p.y}" r="3"
              fill="#12161f" stroke="#8a93a6" stroke-width="1.5"
              pointer-events="none"/>
    `).join('')}
  `;

  // ---------- Sparkline tooltips ----------
  const wrap = document.getElementById('spark-wrap');
  const tooltip = document.getElementById('tooltip');

  svg.querySelectorAll('.spark-dot-hit').forEach(hit => {
    hit.addEventListener('mouseenter', () => {
      const i = +hit.dataset.i;
      const p = pts[i];
      const rect = svg.getBoundingClientRect();
      tooltip.innerHTML = `${labels[i]} <span>·</span> ${p.v}`;
      tooltip.style.left = (p.x / W) * rect.width + 'px';
      tooltip.style.top = (p.y / H) * rect.height + 'px';
      tooltip.classList.add('visible');
      const vis = svg.querySelector(`.spark-dot-vis[data-i="${i}"]`);
      vis.setAttribute('stroke', '#22d3ee');
      vis.setAttribute('r', '4');
    });
    hit.addEventListener('mouseleave', () => {
      tooltip.classList.remove('visible');
      const i = +hit.dataset.i;
      const vis = svg.querySelector(`.spark-dot-vis[data-i="${i}"]`);
      vis.setAttribute('stroke', '#8a93a6');
      vis.setAttribute('r', '3');
    });
  });

  // ---------- Start Focus button ----------
  const btn = document.getElementById('focus-btn');
  let running = false, seconds = 0, timerId = null;

  function fmt(s) {
    const m = String(Math.floor(s / 60)).padStart(2, '0');
    const sec = String(s % 60).padStart(2, '0');
    return `${m}:${sec}`;
  }

  function renderDeepWork() {
    const h = Math.floor(deepWorkSeconds / 3600);
    const m = Math.round((deepWorkSeconds % 3600) / 60);
    document.getElementById('deep-work').textContent = `${h}h ${m}m`;
  }

  function setIdle() {
    btn.className = 'focus-btn';
    btn.innerHTML = '▶&nbsp; Start Focus';
  }

  btn.addEventListener('click', () => {
    if (!running) {
      running = true;
      seconds = 0;
      btn.className = 'focus-btn running';
      btn.innerHTML = `<span class="live-dot"></span> Focusing — ${fmt(0)} &nbsp;·&nbsp; End`;
      timerId = setInterval(() => {
        seconds++;
        btn.innerHTML = `<span class="live-dot"></span> Focusing — ${fmt(seconds)} &nbsp;·&nbsp; End`;
      }, 1000);
    } else {
      running = false;
      clearInterval(timerId);
      deepWorkSeconds += seconds;
      renderDeepWork();
      btn.className = 'focus-btn done';
      btn.innerHTML = `✓&nbsp; Session logged (${fmt(seconds)})`;
      setTimeout(setIdle, 2200);
    }
  });

  setIdle();
  renderDeepWork();
})();
</script>

</body>
</html>
```

**What's included:**

1. **Focus score ring** — an SVG circle with a gradient stroke that animates on load, plus an eased count-up from 0 to 82.
2. **Weekly sparkline** — generated entirely in JS from a data array, using a Catmull-Rom-to-Bezier smooth curve, gradient area fill, a pulsing "today" dot, and hover tooltips showing each day's score. Day labels are computed from the actual current date.
3. **Start Focus button** — fully functional: click to start a live session timer (pulsing indicator, elapsed time), click again to end. The logged time gets added to the "Deep work" stat, and the button briefly shows a confirmation state.
4. **Extras** — trend badge computed from the data, `prefers-reduced-motion` support, and no external assets of any kind.

Just save it as an `.html` file and open it in any browser. To wire it to real data, replace `SCORE` and `WEEK_DATA` at the top of the script.

