<body>

<div class="card">
  <div class="header">
    <h2>Daily Focus</h2>
    <span class="date" id="dateLabel"></span>
  </div>

  <div class="score-section">
    <div class="ring-wrap">
      <svg width="110" height="110" viewBox="0 0 110 110">
        <circle class="ring-track" cx="55" cy="55" r="46"></circle>
        <circle class="ring-progress" id="ringProgress" cx="55" cy="55" r="46"></circle>
      </svg>
      <div class="ring-label">
        <div class="num" id="scoreNum">0</div>
        <div class="unit">/ 100</div>
      </div>
    </div>
    <div class="score-meta">
      <div class="title">Focus Score</div>
      <div class="desc">Based on deep work time, break consistency, and task completion today.</div>
      <div class="badge" id="scoreBadge">Loading…</div>
    </div>
  </div>

  <div class="trend-section">
    <div class="trend-header">
      <span>Weekly Trend</span>
      <span class="delta" id="trendDelta">+0%</span>
    </div>
    <div class="sparkline-wrap">
      <svg id="sparkline" width="100%" height="50" viewBox="0 0 260 50" preserveAspectRatio="none"></svg>
    </div>
    <div class="day-labels">
      <span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span>
    </div>
  </div>

  <button id="focusBtn">Start Focus</button>
</div>

<script>
  // ---------- Date ----------
  document.getElementById('dateLabel').textContent = new Date().toLocaleDateString(undefined, {
    month: 'short', day: 'numeric'
  });

  // ---------- Focus score ring ----------
  const score = 82; // 0-100
  const scoreNumEl = document.getElementById('scoreNum');
  const ring = document.getElementById('ringProgress');
  const r = 46;
  const circumference = 2 * Math.PI * r;
  ring.style.strokeDasharray = circumference;
  ring.style.strokeDashoffset = circumference;

  function setBadge(s) {
    const badge = document.getElementById('scoreBadge');
    if (s >= 80) { badge.textContent = 'Great focus'; badge.style.color = '#34d399'; badge.style.background = 'rgba(52,211,153,0.12)'; badge.style.borderColor = 'rgba(52,211,153,0.25)'; }
    else if (s >= 50) { badge.textContent = 'Steady progress'; badge.style.color = '#fbbf24'; badge.style.background = 'rgba(251,191,36,0.12)'; badge.style.borderColor = 'rgba(251,191,36,0.25)'; }
    else { badge.textContent = 'Needs attention'; badge.style.color = '#f87171'; badge.style.background = 'rgba(248,113,113,0.12)'; badge.style.borderColor = 'rgba(248,113,113,0.25)'; }
  }

  function animateScore(target) {
    const offset = circumference - (target / 100) * circumference;
    requestAnimationFrame(() => { ring.style.strokeDashoffset = offset; });

    let current = 0;
    const duration = 1200;
    const start = performance.now();
    function step(now) {
      const progress = Math.min((now - start) / duration, 1);
      current = Math.floor(progress * target);
      scoreNumEl.textContent = current;
      if (progress < 1) requestAnimationFrame(step);
      else scoreNumEl.textContent = target;
    }
    requestAnimationFrame(step);
    setBadge(target);
  }

  animateScore(score);

  // ---------- Sparkline (weekly trend) ----------
  const weekData = [58, 64, 60, 72, 69, 78, 82]; // Mon..Sun
  const svgNS = "http://www.w3.org/2000/svg";
  const spark = document.getElementById('sparkline');
  const w = 260, h = 50, pad = 6;
  const min = Math.min(...weekData), max = Math.max(...weekData);
  const range = (max - min) || 1;

  function toPoint(i, v) {
    const x = pad + (i / (weekData.length - 1)) * (w - pad * 2);
    const y = h - pad - ((v - min) / range) * (h - pad * 2);
    return [x, y];
  }

  const pts = weekData.map((v, i) => toPoint(i, v));

  // Area fill
  const areaPath = document.createElementNS(svgNS, 'path');
  let d = `M ${pts[0][0]} ${h}`;
  pts.forEach(p => d += ` L ${p[0]} ${p[1]}`);
  d += ` L ${pts[pts.length - 1][0]} ${h} Z`;
  areaPath.setAttribute('d', d);
  areaPath.setAttribute('fill', 'rgba(52,211,153,0.15)');
  areaPath.setAttribute('stroke', 'none');
  spark.appendChild(areaPath);

  // Line
  const linePath = document.createElementNS(svgNS, 'polyline');
  linePath.setAttribute('points', pts.map(p => p.join(',')).join(' '));
  linePath.setAttribute('fill', 'none');
  linePath.setAttribute('stroke', '#34d399');
  linePath.setAttribute('stroke-width', '2.5');
  linePath.setAttribute('stroke-linecap', 'round');
  linePath.setAttribute('stroke-linejoin', 'round');
  spark.appendChild(linePath);

  // Dots
  pts.forEach((p, i) => {
    const c = document.createElementNS(svgNS, 'circle');
    c.setAttribute('cx', p[0]);
    c.setAttribute('cy', p[1]);
    c.setAttribute('r', i === pts.length - 1 ? 4 : 2.5);
    c.setAttribute('fill', i === pts.length - 1 ? '#ffffff' : '#34d399');
    c.setAttribute('stroke', i === pts.length - 1 ? '#34d399' : 'none');
    c.setAttribute('stroke-width', '2');
    spark.appendChild(c);
  });

  // Delta label
  const deltaPct = Math.round(((weekData[6] - weekData[0]) / weekData[0]) * 100);
  const deltaEl = document.getElementById('trendDelta');
  deltaEl.textContent = (deltaPct >= 0 ? '+' : '') + deltaPct + '%';
  if (deltaPct < 0) deltaEl.style.color = '#f87171';

  // ---------- Start Focus button ----------
  const btn = document.getElementById('focusBtn');
  let active = false;
  let timerInterval = null;
  let remaining = 25 * 60; // 25 minutes in seconds

  function formatTime(s) {
    const m = Math.floor(s / 60).toString().padStart(2, '0');
    const sec = (s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  }

  function startTimer() {
    active = true;
    btn.classList.add('active');
    btn.innerHTML = `Focusing… <span class="timer-text">${formatTime(remaining)}</span>`;

    timerInterval = setInterval(() => {
      remaining--;
      if (remaining <= 0) {
        clearInterval(timerInterval);
        btn.textContent = 'Session Complete!';
        setTimeout(resetButton, 2000);
        return;
      }
      btn.innerHTML = `Focusing… <span class="timer-text">${formatTime(remaining)}</span>`;
    }, 1000);
  }

  function resetButton() {
    active = false;
    clearInterval(timerInterval);
    remaining = 25 * 60;
    btn.classList.remove('active');
    btn.textContent = 'Start Focus';
  }

  btn.addEventListener('click', () => {
    if (!active) {
      startTimer();
    } else {
      resetButton();
    }
  });
</script>

</body>
</html>
```

Notes on how it works:

- **Score ring**: an SVG circle with `stroke-dasharray`/`stroke-dashoffset` animated on load to represent the score out of 100, plus a counting-up number animation.
- **Sparkline**: built entirely with JS by mapping a 7-value array to SVG coordinates, drawing a filled area, a line, and dots (last dot highlighted).
- **Start Focus button**: clicking starts a 25-minute countdown displayed inline on the button, switches to a pulsing red "stop" state, and auto-resets after showing "Session Complete!". Clicking again while active cancels the session.

You can swap `score`, `weekData`, or the timer duration to fit your real data source.

