        <div class="action-section">
            <button id="focus-btn" class="btn-focus">
                <svg id="btn-icon" width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                    <polygon points="5 3 19 12 5 21 5 3"></polygon>
                </svg>
                <span id="btn-text">Start Focus</span>
            </button>
            <div id="timer-display" class="timer-display">Session running — <span id="timer-clock">25:00</span> remaining</div>
        </div>
    </div>

    <script>
        // Data & Variables
        const targetScore = 88;
        const weeklyScores = [62, 75, 70, 84, 68, 91, 88]; // Mon - Sun
        const radius = 45;
        const circumference = 2 * Math.PI * radius;

        // Elements
        const scoreCircle = document.getElementById('score-circle');
        const scoreVal = document.getElementById('score-val');
        const sparklineLine = document.getElementById('sparkline-line');
        const sparklineArea = document.getElementById('sparkline-area');
        const sparklineDotsGroup = document.getElementById('sparkline-dots');
        const tooltip = document.getElementById('tooltip');
        const focusBtn = document.getElementById('focus-btn');
        const btnText = document.getElementById('btn-text');
        const btnIcon = document.getElementById('btn-icon');
        const timerDisplay = document.getElementById('timer-display');
        const timerClock = document.getElementById('timer-clock');

        // Initialize Score Animation
        function animateScore(target) {
            scoreCircle.style.strokeDasharray = `${circumference} ${circumference}`;
            const offset = circumference - (target / 100) * circumference;

            setTimeout(() => {
                scoreCircle.style.strokeDashoffset = offset;
            }, 100);

            let current = 0;
            const duration = 1200; // ms
            const stepTime = 20;
            const totalSteps = duration / stepTime;
            const increment = target / totalSteps;

            const timer = setInterval(() => {
                current += increment;
                if (current >= target) {
                    current = target;
                    clearInterval(timer);
                }
                scoreVal.textContent = Math.round(current);
            }, stepTime);
        }

        // Render Sparkline Curve and Points
        function renderSparkline(data) {
            const width = 332;
            const height = 50;
            const padding = 6;

            const min = Math.min(...data) - 10;
            const max = Math.max(...data) + 5;

            const points = data.map((val, idx) => {
                const x = (idx / (data.length - 1)) * width;
                const y = height - ((val - min) / (max - min)) * (height - padding * 2) - padding;
                return { x, y, val };
            });

            // Smooth Bezier path calculation
            let pathD = `M ${points[0].x} ${points[0].y}`;
            for (let i = 0; i < points.length - 1; i++) {
                const current = points[i];
                const next = points[i + 1];
                const controlX = (current.x + next.x) / 2;
                pathD += ` C ${controlX} ${current.y}, ${controlX} ${next.y}, ${next.x} ${next.y}`;
            }

            sparklineLine.setAttribute('d', pathD);

            // Area path (close to bottom)
            const areaD = `${pathD} L ${points[points.length - 1].x} ${height + 10} L ${points[0].x} ${height + 10} Z`;
            sparklineArea.setAttribute('d', areaD);

            // Create interactive dots
            points.forEach((pt, index) => {
                const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                circle.setAttribute('cx', pt.x);
                circle.setAttribute('cy', pt.y);
                circle.setAttribute('r', index === points.length - 1 ? '4.5' : '3');
                circle.classList.add('sparkline-dot');

                if (index === points.length - 1) {
                    circle.style.fill = 'var(--primary)';
                }

                // Hover effects for tooltips
                circle.addEventListener('mouseenter', (e) => {
                    tooltip.textContent = `Score: ${pt.val}`;
                    tooltip.style.left = `${pt.x}px`;
                    tooltip.style.top = `${pt.y}px`;
                    tooltip.style.opacity = '1';
                });

                circle.addEventListener('mouseleave', () => {
                    tooltip.style.opacity = '0';
                });

                sparklineDotsGroup.appendChild(circle);
            });
        }

        // Focus Session Timer Toggle logic
        let isFocusing = false;
        let timerInterval = null;
        let secondsLeft = 25 * 60;

        function updateTimerUI() {
            const mins = Math.floor(secondsLeft / 60).toString().padStart(2, '0');
            const secs = (secondsLeft % 60).toString().padStart(2, '0');
            timerClock.textContent = `${mins}:${secs}`;
        }

        function toggleFocusSession() {
            isFocusing = !isFocusing;

            if (isFocusing) {
                focusBtn.classList.add('active');
                btnText.textContent = 'Pause Session';
                // Stop/Pause Icon
                btnIcon.innerHTML = '<rect x="6" y="4" width="4" height="16" rx="1"></rect><rect x="14" y="4" width="4" height="16" rx="1"></rect>';
                timerDisplay.classList.add('visible');

                timerInterval = setInterval(() => {
                    if (secondsLeft > 0) {
                        secondsLeft--;
                        updateTimerUI();
                    } else {
                        clearInterval(timerInterval);
                        toggleFocusSession();
                        alert('Focus session completed! Great job.');
                        secondsLeft = 25 * 60;
                        updateTimerUI();
                    }
                }, 1000);
            } else {
                focusBtn.classList.remove('active');
                btnText.textContent = 'Resume Focus';
                // Play Icon
                btnIcon.innerHTML = '<polygon points="5 3 19 12 5 21 5 3"></polygon>';
                clearInterval(timerInterval);
            }
        }

        // Event Listeners
        focusBtn.addEventListener('click', toggleFocusSession);

        // Run Animations on Load
        window.addEventListener('DOMContentLoaded', () => {
            animateScore(targetScore);
            renderSparkline(weeklyScores);
        });
    </script>
</body>
</html>
