  <script>
    const SCORE = 87;
    const WEEK = [62, 71, 54, 78, 91, 74, 87];
    const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

    const today = new Date();
    document.getElementById("todayLabel").textContent = today.toLocaleDateString(undefined, {
      weekday: "long", month: "short", day: "numeric"
    });

    const circumference = 2 * Math.PI * 70;
    const ring = document.getElementById("ringFg");
    ring.style.strokeDasharray = circumference;
    ring.style.strokeDashoffset = circumference;

    requestAnimationFrame(() => {
      ring.style.strokeDashoffset = circumference - (SCORE / 100) * circumference;
    });

    const scoreEl = document.getElementById("scoreNum");
    const start = performance.now();
    const duration = 1100;
    function tick(now) {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      scoreEl.textContent = Math.round(SCORE * eased);
      if (t < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);

    const w = 330, h = 72, pad = 8;
    const min = Math.min(...WEEK) - 8;
    const max = Math.max(...WEEK) + 6;
    const xAt = (i) => pad + (i * (w - pad * 2)) / (WEEK.length - 1);
    const yAt = (v) => h - pad - ((v - min) / (max - min)) * (h - pad * 2);
    const points = WEEK.map((v, i) => `${xAt(i)},${yAt(v)}`).join(" ");
    const area = `M${xAt(0)},${h} L${points.replace(/ /g, " L")} L${xAt(WEEK.length - 1)},${h} Z`;

    document.getElementById("spark").innerHTML = `
      <defs>
        <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#7c6cff" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#7c6cff" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path d="${area}" fill="url(#areaGrad)"></path>
      <polyline points="${points}" fill="none" stroke="#9b90ff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"></polyline>
      ${WEEK.map((v, i) => `<circle cx="${xAt(i)}" cy="${yAt(v)}" r="${i === WEEK.length - 1 ? 4.2 : 2.6}" fill="${i === WEEK.length - 1 ? "#3ee0c5" : "#c9c3ff"}"></circle>`).join("")}
    `;

    document.getElementById("days").innerHTML = DAYS.map((d, i) =>
      `<span class="${i === DAYS.length - 1 ? "today" : ""}">${d}</span>`
    ).join("");

    const lastAvg = 68;
    const thisAvg = Math.round(WEEK.reduce((a, b) => a + b, 0) / WEEK.length);
    const diff = thisAvg - lastAvg;
    document.getElementById("deltaLabel").textContent = `${diff >= 0 ? "+" : ""}${diff} vs last week`;

    const btn = document.getElementById("startBtn");
    let running = false;
    let remaining = 25 * 60;
    let timer = null;

    function fmt(s) {
      const m = String(Math.floor(s / 60)).padStart(2, "0");
      const sec = String(s % 60).padStart(2, "0");
      return `${m}:${sec}`;
    }

    btn.addEventListener("click", () => {
      running = !running;
      btn.classList.toggle("running", running);
      if (running) {
        btn.textContent = `Focusing · ${fmt(remaining)}`;
        timer = setInterval(() => {
          remaining = Math.max(0, remaining - 1);
          btn.textContent = remaining === 0 ? "Session complete" : `Focusing · ${fmt(remaining)}`;
          if (remaining === 0) {
            clearInterval(timer);
            running = false;
            btn.classList.remove("running");
          }
        }, 1000);
      } else {
        clearInterval(timer);
        btn.textContent = remaining === 0 ? "Start Focus" : "Resume Focus";
        if (remaining === 0) remaining = 25 * 60;
      }
    });
  </script>
