    <script>
        (function() {
            'use strict';

            // ----- state -----
            const scoreEl = document.getElementById('scoreValue');
            const changeEl = document.getElementById('changePercent');
            const trendLabel = document.getElementById('trendLabel');
            const canvas = document.getElementById('sparklineCanvas');
            const btn = document.getElementById('startBtn');
            const sessionEl = document.getElementById('sessionCount');

            // Weekly data: index 0 = Monday … index 6 = Sunday (today)
            const weeklyData = [62, 68, 71, 65, 74, 79, 84];
            const dayLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

            // current "today" value (matches last data point)
            let currentScore = weeklyData[weeklyData.length - 1]; // 84

            // ----- draw sparkline
            function drawSparkline(data) {
                const ctx = canvas.getContext('2d');
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.getBoundingClientRect();
                const w = rect.width;
                const h = rect.height;

                // set canvas buffer size to CSS size × dpr
                canvas.width = w * dpr;
                canvas.height = h * dpr;
                ctx.scale(dpr, dpr);

                // clear
                ctx.clearRect(0, 0, w, h);

                if (!data || data.length < 2) return;

                const len = data.length;
                const padX = 4;
                const padY = 6;
                const drawW = w - padX * 2;
                const drawH = h - padY * 2;

                // find min/max with some breathing room
                const minVal = Math.min(...data) - 2;
                const maxVal = Math.max(...data) + 3;
                const range = maxVal - minVal || 1;

                const xStep = drawW / (len - 1);

                // ----- gradient fill under line
                const gradient = ctx.createLinearGradient(0, padY, 0, h - padY);
                gradient.addColorStop(0, 'rgba(108, 212, 164, 0.22)');
                gradient.addColorStop(0.5, 'rgba(108, 212, 164, 0.08)');
                gradient.addColorStop(1, 'rgba(108, 212, 164, 0.01)');

                ctx.beginPath();
                const firstX = padX;
                const firstY = padY + drawH - ((data[0] - minVal) / range) * drawH;
                ctx.moveTo(firstX, h - padY);
                ctx.lineTo(firstX, firstY);

                for (let i = 0; i < len; i++) {
                    const x = padX + i * xStep;
                    const y = padY + drawH - ((data[i] - minVal) / range) * drawH;
                    ctx.lineTo(x, y);
                }

                const lastX = padX + (len - 1) * xStep;
                const lastY = padY + drawH - ((data[len - 1] - minVal) / range) * drawH;
                ctx.lineTo(lastX, h - padY);
                ctx.closePath();
                ctx.fillStyle = gradient;
                ctx.fill();

                // ----- line
                ctx.beginPath();
                for (let i = 0; i < len; i++) {
                    const x = padX + i * xStep;
                    const y = padY + drawH - ((data[i] - minVal) / range) * drawH;
                    if (i === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                }
                ctx.strokeStyle = '#6cd4a4';
                ctx.lineWidth = 2.4;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                ctx.stroke();

                // ----- glowing dot on last value
                const dotX = padX + (len - 1) * xStep;
                const dotY = padY + drawH - ((data[len - 1] - minVal) / range) * drawH;

                ctx.shadowColor = '#6cd4a4';
                ctx.shadowBlur = 12;
                ctx.beginPath();
                ctx.arc(dotX, dotY, 3.8, 0, Math.PI * 2);
                ctx.fillStyle = '#d4fae5';
                ctx.fill();

                ctx.shadowBlur = 0;
                ctx.beginPath();
                ctx.arc(dotX, dotY, 2, 0, Math.PI * 2);
                ctx.fillStyle = '#6cd4a4';
                ctx.fill();

                // tiny subtle labels for min/max? skip for cleanliness
            }

            // ----- resize observer for canvas
            function resizeAndRedraw() {
                // force reflow to get accurate rect
                canvas.getBoundingClientRect();
                drawSparkline(weeklyData);
            }

            // ----- update score + meta
            function updateDashboard(newScore) {
                const clamped = Math.min(100, Math.max(0, newScore));
                currentScore = clamped;
                dataEl.textContent = clamped;

                // percent change (comparing to first data point of week)
                const first = weeklyData[0];
                const last = clamped;
                const diff = last - first;
                const pct = first !== 0 ? Math.round((diff / first) * 100) : 0;
                const sign = pct > 0 ? '+' : '';
                changeEl.textContent = `${sign}${pct}%`;

                // trend label (direction)
                if (pct > 0) {
                    trendLabel.textContent = `↑${pct}% this week`;
                    trendLabel.style.color = '#6cd4a4';
                } else if (pct < 0) {
                    trendLabel.textContent = `↓${Math.abs(pct)}% this week`;
                    trendLabel.style.color = '#f77b7b';
                } else {
                    trendLabel.textContent = '→ stable';
                    trendLabel.style.color = '#9aa3b5';
                }

                // replace last data point and redraw
                weeklyData[weeklyData.length - 1] = clamped;
                drawSparkline(weeklyData);

                // increment session count if they click (only by button)
            }

            // ----- button interaction
            let sessionCount = 4;
            let focusActive = false;

            btn.addEventListener('click', function(e) {
                if (totalActive) return;

                // toggle active visual + increment session
                btn.classList.add('active');
                btn.innerHTML = `
                    <span style="display:inline-block;width:10px;height:10px;background:#6cd4a4;border-radius:2px;animation:pulse-dot 1.2s infinite;" aria-hidden="true"></span>
                    Focusing…
                `;
                btn.style.pointerEvents = 'none';

                sessionCount++;
                sessionEl.textContent = sessionCount + ' sessions';

                // simulate small score bump after "focus" then restore button after 2 sec
                setTimeout(() => {
                    // bump score + update
                    const bump = Math.min(100, currentScore + 2);
                    currentScore = bump;
                    weeklyData[weeklyData.length - 1] = bump;
                    updateScore(bump);

                    // also add a tiny bump to the trend (for fun)
                    // just redraw chart with updated score
                    drawSparkline(weeklyData);

                    // reset button
                    btn.classList.remove('active');
                    btn.style.pointerEvents = 'auto';
                    btn.innerHTML = `
                        <span class="icon-play" aria-hidden="true"></span>
                        Start Focus
                    `;
                }, 2200);
            });

            // helper pulse animation (injected style for the dot)
            const styleSheet = document.createElement('style');
            styleSheet.textContent = `
                @keyframes pulse-dot {
                    0% { opacity: 1; transform: scale(1); }
                    50% { opacity: 0.4; transform: scale(0.7); }
                    100% { opacity: 1; transform: scale(1); }
                }
            `;
            document.head.appendChild(styleSheet);

            // grab references for the internal updater
            const dataEl = document.getElementById('scoreValue');

            // ----- initial render
            function initialRender() {
                // set canvas size
                const rect = canvas.getBoundingClientRect();
                // already has width/height attributes, but use them
                drawSparkline(weeklyData);

                // set score number
                dataEl.textContent = currentScore;

                // compute initial change
                const first = weeklyData[0];
                const last = weeklyData[weeklyData.length - 1];
                const chg = last - first;
                const pct = first !== 0 ? Math.round((chg / first) * 100) : 0;
                const sign = pct > 0 ? '+' : '';
                changeEl.textContent = `${sign}${pct}%`;
                trendLabel.textContent = pct > 0 ? `↑${pct}% this week` : (pct < 0 ? `↓${Math.abs(pct)}% this week` : '→ flat');
                if (pct > 0) trendLabel.style.color = '#6cd4a4';
                else if (pct < 0) trendLabel.style.color = '#f77b7b';
                else trendLabel.style.color = '#9aa3b5';

                sessionEl.textContent = '4 sessions';
            }

            // resize observer
            let resizeTimer;
            window.addEventListener('resize', function() {
                clearTimeout(resizeTimer);
                resizeTimer = setTimeout(function() {
                    resizeAndRedraw();
                }, 120);
            });

            // separate function for resize w/o score update
            function resizeAndRedraw() {
                const rect = canvas.getBoundingClientRect();
                drawSparkline(weeklyData);
            }

            // init
            initialRender();

            // additional re-draw after fonts / layout settles
            requestAnimationFrame(() => {
                resizeAndRedraw();
            });

            // also handle element available after paint
            setTimeout(() => {
                resizeAndRedraw();
            }, 80);

            // manually expose a little easter egg: click the score to see random change?
            // (optional, but makes it interactive for demo)
            dataEl.addEventListener('dblclick', function() {
                const newVal = Math.floor(Math.random() * 45) + 55;
                currentScore = newVal;
                weeklyData[weeklyData.length - 1] = newVal;
                updateScore(newVal);
                // also reset button state if active
                if (btn.classList.contains('active')) {
                    btn.classList.remove('active');
                    btn.style.pointerEvents = 'auto';
                    btn.innerHTML = `
                        <span class="icon-play" aria-hidden="true"></span>
                        Start Focus
                    `;
                }
            });

        })();
    </script>

