                </defs>
                <!-- will be drawn by JS -->
            </svg>
        </div>

        <!-- button -->
        <button class="btn-start" id="startFocusBtn" aria-label="Start a focus session">
            <span class="btn-icon">▶</span> Start Focus
            <span class="btn-sub">25 min · deep work</span>
        </button>

    </div>

    <script>
        (function() {
            'use strict';

            // ── data ────────────────────────────────────────────────
            // 7 days: Mon – Sun (most recent = Sunday, index 6)
            const rawData = [62, 71, 68, 84, 79, 91, 87];
            const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

            // ── DOM refs ────────────────────────────────────────────
            const scoreDisplay = document.getElementById('scoreDisplay');
            const changeBadge = document.getElementById('changeBadge');
            const avgLabel = document.getElementById('avgLabel');
            const svg = document.getElementById('sparklineSvg');

            // ── helpers ─────────────────────────────────────────────
            const todayScore = rawData[rawData.length - 1];
            const yesterdayScore = rawData[rawData.length - 2];
            const diff = todayScore - yesterdayScore;
            const diffPercent = ((diff / yesterdayScore) * 100);
            const avg = Math.round(rawData.reduce((a, b) => a + b, 0) / rawData.length);

            // update score & badge
            scoreDisplay.innerHTML = todayScore + '<small>/100</small>';

            if (diff >= 0) {
                changeBadge.textContent = '+' + diff.toFixed(0) + '%';
                changeBadge.classList.remove('negative');
            } else {
                changeBadge.textContent = diff.toFixed(0) + '%';
                changeBadge.classList.add('negative');
            }
            avgLabel.textContent = avg;

            // ── draw sparkline ─────────────────────────────────────
            const w = 260;
            const h = 60;
            const padX = 6;
            const padY = 6;
            const innerW = w - padX * 2;
            const innerH = h - padY * 2;

            // scale
            const minVal = Math.min(...rawData) - 4;
            const maxVal = Math.max(...rawData) + 6;
            const range = maxVal - minVal || 1;

            const points = rawData.map((d, i) => {
                const x = padX + (i / (rawData.length - 1)) * innerW;
                const y = padY + innerH - ((d - minVal) / range) * innerH;
                return { x, y, val: d };
            });

            // build path (smooth cubic)
            function linePath(pts) {
                if (pts.length === 0) return '';
                let d = 'M' + pts[0].x + ',' + pts[0].y;
                for (let i = 0; i < pts.length - 1; i++) {
                    const p0 = pts[i];
                    const p1 = pts[i + 1];
                    const cp1x = p0.x + (p1.x - p0.x) / 2;
                    const cp1y = p0.y;
                    const cp2x = p0.x + (p1.x - p0.x) / 2;
                    const cp2y = p1.y;
                    d += ' C' + cp1x + ',' + cp1y + ' ' + cp2x + ',' + cp2y + ' ' + p1.x + ',' + p1.y;
                }
                return d;
            }

            const lineD = linePath(points);

            // area path (same line but closed to bottom)
            const areaD = lineD +
                ' L' + points[points.length - 1].x + ',' + (padY + innerH) +
                ' L' + points[0].x + ',' + (padY + innerH) + ' Z';

            // grid lines (horizontal)
            let gridHtml = '';
            const gridCount = 3;
            for (let i = 0; i <= gridCount; i++) {
                const y = padY + (i / gridCount) * innerH;
                gridHtml +=
                    `<line class="grid-line" x1="${padX}" y1="${y}" x2="${padX + innerW}" y2="${y}" />`;
            }

            // dots
            let dotsHtml = '';
            points.forEach((p, idx) => {
                const isLast = idx === points.length - 1;
                const cls = isLast ? 'dot dot-last' : 'dot';
                const r = isLast ? 4.5 : 3;
                dotsHtml +=
                    `<circle class="${cls}" cx="${p.x}" cy="${p.y}" r="${r}" />`;
            });

            // labels under x-axis (simplified – just first, middle, last)
            const labelPositions = [0, Math.floor(points.length / 2), points.length - 1];
            let labelsHtml = '';
            labelPositions.forEach(idx => {
                const p = points[idx];
                const label = days[idx] || '';
                labelsHtml +=
                    `<text x="${p.x}" y="${h - 1}" text-anchor="middle" font-size="6" fill="#4d5b72" font-weight="400">${label}</text>`;
            });

            // assemble
            svg.innerHTML = `
                    ${gridHtml}
                    <path class="area" d="${areaD}" />
                    <path class="line" d="${lineD}" />
                    ${dotsHtml}
                    ${labelsHtml}
                `;

            // ── button interaction ─────────────────────────────────
            const btn = document.getElementById('startFocusBtn');
            let sessionActive = false;
            let intervalId = null;
            const originalText = btn.innerHTML;

            btn.addEventListener('click', function() {
                if (sessionActive) {
                    // stop
                    sessionActive = false;
                    clearInterval(intervalId);
                    intervalId = null;
                    btn.innerHTML = originalText;
                    btn.style.background = 'linear-gradient(135deg, #6c8cff 0%, #8a6cff 100%)';
                    btn.querySelector('.btn-sub').textContent = '25 min · deep work';
                    return;
                }

                // start
                sessionActive = true;
                let remaining = 25 * 60; // 25 min in seconds
                btn.innerHTML = '⏸  Focusing… <span class="btn-sub" id="timerSub">25:00</span>';
                btn.style.background = 'linear-gradient(135deg, #f59e0b 0%, #f97316 100%)';
                btn.style.boxShadow = '0 6px 20px -6px #f59e0b50';

                const timerSub = btn.querySelector('#timerSub');

                function updateTimer() {
                    const mins = Math.floor(remaining / 60);
                    const secs = remaining % 60;
                    timerSub.textContent =
                        String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
                    if (remaining <= 0) {
                        clearInterval(intervalId);
                        intervalId = null;
                        sessionActive = false;
                        btn.innerHTML = '✅ Session Complete!';
                        btn.style.background = 'linear-gradient(135deg, #22c55e 0%, #16a34a 100%)';
                        btn.style.boxShadow = '0 6px 20px -6px #22c55e50';
                        btn.querySelector('.btn-sub') &&
                            (btn.querySelector('.btn-sub').textContent = 'great work');
                        // reset after 4s
                        setTimeout(() => {
                            if (!sessionActive) {
                                btn.innerHTML = originalText;
                                btn.style.background = 'linear-gradient(135deg, #6c8cff 0%, #8a6cff 100%)';
                                btn.style.boxShadow = '0 6px 20px -6px #6c8cff50';
                            }
                        }, 4000);
                        return;
                    }
                    remaining--;
                }
                updateTimer();
                intervalId = setInterval(updateTimer, 1000);
            });

        })();
    </script>

</body>
</html>
