    <script>
        // Sample data
        const focusScore = 85;
        const focusHours = 4;
        const focusMinutes = 32;
        const sessionCount = 6;
        const weeklyData = [65, 72, 68, 78, 82, 75, 85];
        const trendPercentage = 12;

        // Animate score circle
        function animateScore() {
            const circle = document.querySelector('.score-circle-progress');
            const circumference = 2 * Math.PI * 52;
            const offset = circumference - (focusScore / 100) * circumference;

            setTimeout(() => {
                circle.style.strokeDashoffset = offset;
            }, 100);

            // Animate number
            const scoreElement = document.getElementById('scoreNumber');
            let current = 0;
            const increment = focusScore / 30;
            const timer = setInterval(() => {
                current += increment;
                if (current >= focusScore) {
                    current = focusScore;
                    clearInterval(timer);
                }
                scoreElement.textContent = Math.round(current);
            }, 20);
        }

        // Update stats
        function updateStats() {
            document.getElementById('focusTime').textContent = `${focusHours}h ${focusMinutes}m`;
            document.getElementById('sessions').textContent = sessionCount;
            document.getElementById('trendChange').textContent = `+${trendPercentage}%`;
        }

        // Draw sparkline
        function drawSparkline() {
            const svg = document.getElementById('sparkline');
            const width = svg.clientWidth;
            const height = svg.clientHeight;
            const padding = 4;

            const max = Math.max(...weeklyData);
            const min = Math.min(...weeklyData);
            const range = max - min || 1;

            const points = weeklyData.map((value, index) => {
                const x = padding + (index / (weeklyData.length - 1)) * (width - padding * 2);
                const y = height - padding - ((value - min) / range) * (height - padding * 2);
                return `${x},${y}`;
            });

            // Create gradient
            const gradientId = 'sparklineGradient';
            const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
            const gradient = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
            gradient.setAttribute('id', gradientId);
            gradient.setAttribute('x1', '0%');
            gradient.setAttribute('y1', '0%');
            gradient.setAttribute('x2', '0%');
            gradient.setAttribute('y2', '100%');

            const stop1 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
            stop1.setAttribute('offset', '0%');
            stop1.setAttribute('style', 'stop-color:#4ade80;stop-opacity:0.3');

            const stop2 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
            stop2.setAttribute('offset', '100%');
            stop2.setAttribute('style', 'stop-color:#4ade80;stop-opacity:0');

            gradient.appendChild(stop1);
            gradient.appendChild(stop2);
            defs.appendChild(gradient);
            svg.appendChild(defs);

            // Create area fill
            const area = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
            const areaPoints = [
                `${padding},${height - padding}`,
                ...points,
                `${width - padding},${height - padding}`
            ].join(' ');
            area.setAttribute('points', areaPoints);
            area.setAttribute('fill', `url(#${gradientId})`);
            svg.appendChild(area);

            // Create line
            const polyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
            polyline.setAttribute('points', points.join(' '));
            polyline.setAttribute('fill', 'none');
            polyline.setAttribute('stroke', '#4ade80');
            polyline.setAttribute('stroke-width', '2');
            polyline.setAttribute('stroke-linecap', 'round');
            polyline.setAttribute('stroke-linejoin', 'round');
            svg.appendChild(polyline);

            // Add dots
            weeklyData.forEach((value, index) => {
                const x = padding + (index / (weeklyData.length - 1)) * (width - padding * 2);
                const y = height - padding - ((value - min) / range) * (height - padding * 2);

                const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                circle.setAttribute('cx', x);
                circle.setAttribute('cy', y);
                circle.setAttribute('r', '3');
                circle.setAttribute('fill', '#4ade80');
                svg.appendChild(circle);
            });
        }

        // Button functionality
        let isFocusing = false;
        const button = document.getElementById('startButton');

        button.addEventListener('click', () => {
            isFocusing = !isFocusing;
            if (isFocusing) {
                button.textContent = 'Stop Focus';
                button.classList.add('active');
            } else {
                button.textContent = 'Start Focus';
                button.classList.remove('active');
            }
        });

        // Initialize
        window.addEventListener('load', () => {
            animateScore();
            updateStats();
            drawSparkline();
        });

        // Redraw sparkline on resize
        window.addEventListener('resize', () => {
            const svg = document.getElementById('sparkline');
            svg.innerHTML = '';
            drawSparkline();
        });
    </script>
</body>
</html>
