            let areaD = `M 0 ${height} `;
            const points = [];

            data.forEach((val, i) => {
                const x = (i / (data.length - 1)) * width;
                const y = height - padding - ((val - min) / range) * (height - padding * 2);
                points.push({ x, y });

                if (i === 0) {
                    pathD += `M ${x} ${y} `;
                    areaD += `L ${x} ${y} `;
                } else {
                    // Simple smoothing using quadratic bezier
                    const prev = points[i - 1];
                    const cpX = (prev.x + x) / 2;
                    pathD += `Q ${cpX} ${prev.y} ${(cpX + x) / 2} ${(prev.y + y) / 2} T ${x} ${y} `;
                    areaD += `Q ${cpX} ${prev.y} ${(cpX + x) / 2} ${(prev.y + y) / 2} T ${x} ${y} `;
                }
            });

            areaD += `L ${width} ${height} Z`;

            // Gradient definition
            const defs = document.createElementNS("http://www.w3.org/2000/svg", "defs");
            defs.innerHTML = `
                <linearGradient id="lineGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stop-color="#8b5cf6" />
                    <stop offset="100%" stop-color="#3b82f6" />
                </linearGradient>
                <linearGradient id="areaGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                    <stop offset="0%" stop-color="#8b5cf6" stop-opacity="0.3" />
                    <stop offset="100%" stop-color="#8b5cf6" stop-opacity="0.0" />
                </linearGradient>
            `;
            svg.appendChild(defs);

            // Area path
            const areaPath = document.createElementNS("http://www.w3.org/2000/svg", "path");
            areaPath.setAttribute("d", areaD);
            areaPath.setAttribute("fill", "url(#areaGradient)");
            svg.appendChild(areaPath);

            // Line path
            const linePath = document.createElementNS("http://www.w3.org/2000/svg", "path");
            linePath.setAttribute("d", pathD);
            linePath.setAttribute("fill", "none");
            linePath.setAttribute("stroke", "url(#lineGradient)");
            linePath.setAttribute("stroke-width", "2.5");
            linePath.setAttribute("stroke-linecap", "round");
            linePath.setAttribute("stroke-linejoin", "round");
            svg.appendChild(linePath);

            // End dot
            const lastPoint = points[points.length - 1];
            const dot = document.createElementNS("http://www.w3.org/2000/svg", "circle");
            dot.setAttribute("cx", lastPoint.x);
            dot.setAttribute("cy", lastPoint.y);
            dot.setAttribute("r", "4");
            dot.setAttribute("fill", "#3b82f6");
            dot.setAttribute("stroke", "#1a1a24");
            dot.setAttribute("stroke-width", "2");
            svg.appendChild(dot);
        })();

        // Button Interaction
        const btn = document.getElementById('btnFocus');
        btn.addEventListener('click', function() {
            if (this.classList.contains('focusing')) return;

            this.classList.add('focusing');
            this.textContent = 'Focusing...';

            // Simulate a session end after 5 seconds for demo purposes
            setTimeout(() => {
                this.classList.remove('focusing');
                this.textContent = 'Start Focus';
            }, 5000);
        });
    </script>
</body>
</html>
