        let weeklyScores = [64, 79, 71, 88, 93, 82, 87];
        let days = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
        let timerInterval = null;
        let timeLeft = 25 * 60; // 25 minutes in seconds
        let isPaused = false;

        // Update score display
        function updateScoreDisplay() {
            const scoreEl = document.getElementById("score-value");
            scoreEl.textContent = currentScore;

            // Update progress ring
            const circumference = 553;
            const offset = circumference * (1 - currentScore / 100);
            const progressCircle = document.getElementById("progress-circle");
            progressCircle.setAttribute("stroke-dashoffset", offset);

            // Update label
            const label = document.getElementById("score-label");
            if (currentScore >= 85) {
                label.innerHTML = `<span class="text-base leading-none">↑</span> EXCELLENT`;
                label.className = "mt-3 px-5 py-1 bg-zinc-800 text-emerald-400 text-xs font-semibold rounded-3xl inline-flex items-center gap-x-1.5";
            } else if (currentScore >= 70) {
                label.innerHTML = `<span class="text-base leading-none">→</span> GOOD`;
                label.className = "mt-3 px-5 py-1 bg-zinc-800 text-amber-400 text-xs font-semibold rounded-3xl inline-flex items-center gap-x-1.5";
            } else {
                label.innerHTML = `<span class="text-base leading-none">↓</span> FOCUS`;
                label.className = "mt-3 px-5 py-1 bg-zinc-800 text-orange-400 text-xs font-semibold rounded-3xl inline-flex items-center gap-x-1.5";
            }
        }

        // Render sparkline
        function renderSparkline() {
            const svg = document.getElementById("sparkline");
            svg.innerHTML = '';

            const width = 320;
            const height = 95;
            const paddingLeft = 15;
            const paddingRight = 15;
            const graphWidth = width - paddingLeft - paddingRight;

            // Find min and max
            const minScore = Math.min(...weeklyScores);
            const maxScore = Math.max(...weeklyScores);
            const range = maxScore - minScore || 1;

            // Generate points
            let points = [];
            let pathPoints = [];

            for (let i = 0; i < weeklyScores.length; i++) {
                const x = paddingLeft + (i * (graphWidth / (weeklyScores.length - 1)));
                const normalized = (weeklyScores[i] - minScore) / range;
                const y = height - (normalized * (height - 30));
                points.push(`${x},${y}`);
                pathPoints.push({x: x, y: y});
            }

            // Line
            const polyline = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
            polyline.setAttribute("points", points.join(" "));
            polyline.setAttribute("fill", "none");
            polyline.setAttribute("stroke", "#67e8f9");
            polyline.setAttribute("stroke-width", "5");
            polyline.setAttribute("stroke-linecap", "round");
            polyline.setAttribute("stroke-linejoin", "round");
            svg.appendChild(polyline);

            // Gradient area under line
            const areaPath = document.createElementNS("http://www.w3.org/2000/svg", "path");
            let areaD = `M ${paddingLeft} ${height} `;
            areaD += points.join(" ");
            areaD += ` L ${width - paddingRight} ${height} Z`;

            areaPath.setAttribute("d", areaD);
            areaPath.setAttribute("fill", "url(#areaGradient)");
            svg.appendChild(areaPath);

            // Gradient definition
            const defs = document.createElementNS("http://www.w3.org/2000/svg", "defs");
            const linearGradient = document.createElementNS("http://www.w3.org/2000/svg", "linearGradient");
            linearGradient.setAttribute("id", "areaGradient");
            linearGradient.setAttribute("x1", "0%");
            linearGradient.setAttribute("y1", "0%");
            linearGradient.setAttribute("x2", "0%");
            linearGradient.setAttribute("y2", "100%");

            const stop1 = document.createElementNS("http://www.w3.org/2000/svg", "stop");
            stop1.setAttribute("offset", "10%");
            stop1.setAttribute("stop-color", "#67e8f9");
            stop1.setAttribute("stop-opacity", "0.25");
            linearGradient.appendChild(stop1);

            const stop2 = document.createElementNS("http://www.w3.org/2000/svg", "stop");
            stop2.setAttribute("offset", "95%");
            stop2.setAttribute("stop-color", "#67e8f9");
            stop2.setAttribute("stop-opacity", "0");
            linearGradient.appendChild(stop2);

            defs.appendChild(linearGradient);
            svg.appendChild(defs);

            // Dots
            for (let i = 0; i < pathPoints.length; i++) {
                const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                circle.setAttribute("cx", pathPoints[i].x);
                circle.setAttribute("cy", pathPoints[i].y);
                circle.setAttribute("r", i === weeklyScores.length - 1 ? "6" : "3.5");
                circle.setAttribute("fill", i === weeklyScores.length - 1 ? "#22d3ee" : "#a5f3fc");
                svg.appendChild(circle);

                // Extra ring on last point
                if (i === weeklyScores.length - 1) {
                    const ring = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                    ring.setAttribute("cx", pathPoints[i].x);
                    ring.setAttribute("cy", pathPoints[i].y);
                    ring.setAttribute("r", "9");
                    ring.setAttribute("fill", "none");
                    ring.setAttribute("stroke", "#67e8f9");
                    ring.setAttribute("stroke-width", "2");
                    ring.setAttribute("opacity", "0.3");
                    svg.appendChild(ring);
                }
            }

            // Day labels
            const labelsContainer = document.getElementById("day-labels");
            labelsContainer.innerHTML = '';

            days.forEach((day, index) => {
                const div = document.createElement("div");
                div.className = "text-center";
                div.textContent = day;
                if (index === weeklyScores.length - 1) {
                    div.classList.add("text-cyan-400", "font-semibold");
                }
                labelsContainer.appendChild(div);
            });
        }

        function randomizeData() {
            weeklyScores = weeklyScores.map(() => {
                return Math.floor(Math.random() * 35) + 65;
            });
            // Ensure last value is close to current score
            weeklyScores[weeklyScores.length - 1] = currentScore;
            renderSparkline();
        }

        // Timer functions
        function startFocusSession() {
            document.getElementById("main-card").classList.add("opacity-30", "pointer-events-none");
            const overlay = document.getElementById("timer-overlay");
            overlay.classList.remove("hidden");
            overlay.classList.add("flex");

            // Reset timer
            timeLeft = 25 * 60;
            isPaused = false;
            updateTimerDisplay();

            if (timerInterval) clearInterval(timerInterval);

            timerInterval = setInterval(() => {
                if (!isPaused) {
                    timeLeft--;
                    updateTimerDisplay();

                    if (timeLeft <= 0) {
                        clearInterval(timerInterval);
                        finishSession();
                    }
                }
            }, 1000);
        }

        function updateTimerDisplay() {
            const minutes = Math.floor(timeLeft / 60);
            const seconds = timeLeft % 60;
            const display = `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
            document.getElementById("timer-display").textContent = display;

            // Progress
            const totalTime = 25 * 60;
            const progressPercent = ((totalTime - timeLeft) / totalTime) * 100;
            document.getElementById("timer-progress").style.width = `${progressPercent}%`;
        }

        function pauseTimer() {
            isPaused = !isPaused;
            const pauseBtn = document.getElementById("pause-btn");
            if (isPaused) {
                pauseBtn.textContent = "RESUME";
                pauseBtn.classList.add("!border-amber-400", "!text-amber-400");
            } else {
                pauseBtn.textContent = "PAUSE";
                pauseBtn.classList.remove("!border-amber-400", "!text-amber-400");
            }
        }

        function finishSession() {
            const overlay = document.getElementById("timer-overlay");
            overlay.classList.add("hidden");
            overlay.classList.remove("flex");

            // Increase score
            currentScore = Math.min(100, currentScore + 13);
            updateScoreDisplay();

            // Show success
            document.getElementById("success-screen").classList.remove("hidden");

            // Update streak
            const streakEl = document.getElementById("streak-count");
            let streak = parseInt(streakEl.textContent);
            streakEl.textContent = streak + 1;
        }

        function endFocusSession() {
            if (timerInterval) {
                clearInterval(timerInterval);
            }
            const overlay = document.getElementById("timer-overlay");
            overlay.classList.add("hidden");
            overlay.classList.remove("flex");
            document.getElementById("main-card").classList.remove("opacity-30", "pointer-events-none");
        }

        function hideSuccessAndReset() {
            document.getElementById("success-screen").classList.add("hidden");
            document.getElementById("main-card").classList.remove("opacity-30", "pointer-events-none");

            // Occasionally increase weekly average too
            if (Math.random() > 0.6) {
                const avgEl = document.getElementById("weekly-avg");
                let avg = parseInt(avgEl.textContent);
                avgEl.textContent = Math.min(98, avg + 2);
            }
        }

        // Keyboard shortcuts
        function handleKeys(e) {
            if (e.metaKey && e.key === "k") {
                e.preventDefault();
                const overlay = document.getElementById("timer-overlay");
                if (!overlay.classList.contains("hidden")) {
                    endFocusSession();
                } else {
                    startFocusSession();
                }
            }
        }

        // Initialize everything
        function initializeDashboard() {
            // Tailwind ready
            initializeTailwind();

            // Initial score render
            updateScoreDisplay();

            // Render sparkline
            renderSparkline();

            // Set initial weekly average
            const total = weeklyScores.reduce((a, b) => a + b, 0);
            const avg = Math.round(total / weeklyScores.length);
            document.getElementById("weekly-avg").textContent = avg;

            // Keyboard listener
            document.addEventListener("keydown", handleKeys);

            // Demo: randomly update score every 12 seconds
            setInterval(() => {
                if (Math.random() > 0.7 && document.getElementById("timer-overlay").classList.contains("hidden")) {
                    currentScore = Math.max(65, Math.min(99, currentScore + (Math.random() > 0.5 ? 3 : -2)));
                    updateScoreDisplay();
                }
            }, 12000);

            // Make the card slightly interactive on mousemove
            const card = document.getElementById("main-card");
            card.addEventListener("mousemove", (e) => {
                const rect = card.getBoundingClientRect();
                const x = ((e.clientX - rect.left) / rect.width) * 100;
                const y = ((e.clientY - rect.top) / rect.height) * 100;

                card.style.setProperty("--mouse-x", `${x}%`);
                card.style.setProperty("--mouse-y", `${y}%`);
            });

            console.log('%c✅ Focus Pulse dashboard ready. Press CMD+K to toggle timer.', 'color:#67e8f9; font-family:monospace');
        }

        // Boot app
        window.onload = initializeDashboard;
    </script>
</body>
</html>
```

