<script>
(() => {
  /* ---------------- data ---------------- */
  const week   = [61, 68, 57, 79, 72, 84, 82];      // Mon..Sun
  const labels = ['M','T','W','T','F','S','S'];
  const score  = week[week.length - 1];
  const avg    = Math.round(week.reduce((a,b)=>a+b,0) / week.length);

  /* ---------------- ring ---------------- */
  const R = 57, C = 2 * Math.PI * R;
  const bar = document.getElementById('bar');
  bar.style.strokeDasharray  = C;
  bar.style.strokeDashoffset = C;
  requestAnimationFrame(() => {
    setTimeout(() => { bar.style.strokeDashoffset = C * (1 - score / 100); }, 120);
  });

  // count-up number
  const numEl = document.getElementById('scoreNum');
  const t0 = performance.now(), DUR = 1400;
  (function tick(t){
    const p = Math.min((t - t0) / DUR, 1);
    const eased = 1 - Math.pow(1 - p, 3);
    numEl.textContent = Math.round(score * eased);
    if (p < 1) requestAnimationFrame(tick);
  })(t0);

  document.getElementById('avg').textContent = 'avg ' + avg;

  /* ---------------- sparkline ---------------- */
  const svg = document.getElementById('spark');
  const W = 300, H = 64, PAD = 6;
  const min = Math.min(...week) - 6, max = Math.max(...week) + 6;
  const x = i => PAD + i * ((W - PAD * 2) / (week.length - 1));
  const y = v => H - PAD - ((v - min) / (max - min)) * (H - PAD * 2);

  const pts = week.map((v,i) => [x(i), y(v)]);

  // smooth cubic path
  let d = `M ${pts[0][0]} ${pts[0][1]}`;
  for (let i = 0; i < pts.length - 1; i++){
    const [x1,y1] = pts[i], [x2,y2] = pts[i+1];
    const cx = (x1 + x2) / 2;
    d += ` C ${cx} ${y1}, ${cx} ${y2}, ${x2} ${y2}`;
  }

  const ns = 'http://www.w3.org/2000/svg';
  const mk = (tag, attrs) => {
    const el = document.createElementNS(ns, tag);
    for (const k in attrs) el.setAttribute(k, attrs[k]);
    return el;
  };

  svg.appendChild(mk('path', { d: `${d} L ${W-PAD} ${H} L ${PAD} ${H} Z`, fill: 'url(#fillGrad)' }));

  const line = mk('path', { d, class: 'line' });
  svg.appendChild(line);

  // draw-in animation
  const len = line.getTotalLength();
  line.style.strokeDasharray  = len;
  line.style.strokeDashoffset = len;
  line.style.transition = 'stroke-dashoffset 1.5s cubic-bezier(.16,1,.3,1)';
  requestAnimationFrame(() => { line.style.strokeDashoffset = 0; });

  // last-point dot
  const last = pts[pts.length - 1];
  svg.appendChild(mk('circle', { class:'dot', cx:last[0], cy:last[1], r:4 }));

  // hover targets + tooltip
  const tip  = document.getElementById('tip');
  const card = document.getElementById('card');
  const full = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];

  pts.forEach(([px,py], i) => {
    const hit = mk('rect', { class:'hit', x: px - 20, y: 0, width: 40, height: H });
    hit.addEventListener('mouseenter', e => {
      tip.textContent = `${full[i]} · ${week[i]}`;
      tip.classList.add('on');
      const r = svg.getBoundingClientRect(), cr = card.getBoundingClientRect();
      tip.style.left = (r.left - cr.left + (px / W) * r.width) + 'px';
      tip.style.top  = (r.top  - cr.top  + (py / H) * r.height) + 'px';
    });
    hit.addEventListener('mouseleave', () => tip.classList.remove('on'));
    svg.appendChild(hit);
  });

  // day labels
  const days = document.getElementById('days');
  labels.forEach((l,i) => {
    const b = document.createElement('b');
    b.textContent = l;
    if (i === labels.length - 1) b.className = 'today';
    days.appendChild(b);
  });

  /* ---------------- focus timer ---------------- */
  const TOTAL = 25 * 60;
  let left = TOTAL, id = null, running = false;

  const btn    = document.getElementById('startBtn');
  const reset  = document.getElementById('resetBtn');
  const disp   = document.getElementById('timer');

  const fmt = s => `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;

  function render(){
    if (!running && left === TOTAL){
      disp.textContent = 'Ready for a 25-minute block';
      btn.textContent = 'Start Focus';
      btn.classList.remove('running');
      return;
    }
    disp.innerHTML = running
      ? `In session · <b>${fmt(left)}</b> remaining`
      : `Paused · <b>${fmt(left)}</b> remaining`;
    btn.textContent = running ? 'Pause' : 'Resume';
    btn.classList.toggle('running', running);
  }

  function beep(){
    try{
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine'; o.frequency.value = 660;
      g.gain.setValueAtTime(.0001, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(.25, ctx.currentTime + .03);
      g.gain.exponentialRampToValueAtTime(.0001, ctx.currentTime + .9);
      o.connect(g).connect(ctx.destination);
      o.start(); o.stop(ctx.currentTime + 1);
    }catch(e){}
  }

  btn.addEventListener('click', () => {
    if (running){
      clearInterval(id); running = false;
    } else {
      running = true;
      id = setInterval(() => {
        left--;
        if (left <= 0){
          clearInterval(id); running = false; left = TOTAL;
          disp.innerHTML = '<b>Session complete.</b> Nice work. ✦';
          btn.textContent = 'Start Focus';
          btn.classList.remove('running');
          beep();
          return;
        }
        render();
      }, 1000);
    }
    render();
  });

  reset.addEventListener('click', () => {
    clearInterval(id); running = false; left = TOTAL; render();
  });

  render();
})();
</script>
</body>
</html>
```

**What's in it:**
- **Animated ring gauge** — SVG `stroke-dashoffset` sweep plus a cubic-eased count-up on the number.
- **Sparkline** — smooth Bézier path built from the `week` array, gradient fill under the curve, draw-in animation, hover tooltips per day, and a highlighted end dot.
- **Timer** — real 25:00 countdown with Start → Pause → Resume states, a ghost reset button, and a Web Audio chime on completion (no audio file).
- Fully responsive, respects `prefers-reduced-motion`, keyboard-focusable buttons.

To rewire it with your own data, just change the `week` array at the top of the script — the ring, average, tooltips, and labels all derive from it. Want me to add a second view (e.g. monthly bars) or make it accept data from an API endpoint?

