      <div class="trend-head">
        <span>Weekly Trend</span>
        <b id="avg">avg 71</b>
      </div>
      <svg class="spark" id="spark" viewBox="0 0 280 56" preserveAspectRatio="none"></svg>
      <div class="spark-days">
        <span>M</span><span>T</span><span>W</span><span>T</span>
        <span>F</span><span>S</span><span>S</span>
      </div>
    </div>

    <button class="btn" id="focusBtn">
      <span class="dot"></span>
      <span id="btnText">Start Focus</span>
    </button>
  </div>

<script>
  // --- Data ---
  const score = 84;
  const weekly = [62, 70, 58, 75, 80, 68, 84]; // Mon..Sun

  // --- Date ---
  document.getElementById('date').textContent =
    new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' });

  // --- Score status label ---
  const status = document.getElementById('status');
  if (score >= 80) { status.textContent = 'Excellent'; status.style.color = 'var(--good)'; }
  else if (score >= 60) { status.textContent = 'Good'; status.style.color = '#f1c40f'; }
  else { status.textContent = 'Needs Focus'; status.style.color = '#e74c3c'; }

  // --- Animate ring + number ---
  const R = 48, CIRC = 2 * Math.PI * R;
  const ring = document.getElementById('ringFill');
  const numEl = document.getElementById('scoreNum');
  ring.style.strokeDasharray = CIRC;

  requestAnimationFrame(() => {
    ring.style.strokeDashoffset = CIRC * (1 - score / 100);
  });

  let cur = 0;
  const step = () => {
    cur += Math.ceil((score - cur) / 8) || 1;
    if (cur >= score) cur = score;
    numEl.textContent = cur;
    if (cur < score) requestAnimationFrame(step);
  };
  setTimeout(step, 200);

  // --- Sparkline ---
  (function drawSpark() {
    const W = 280, H = 56, pad = 4;
    const max = Math.max(...weekly), min = Math.min(...weekly);
    const range = max - min || 1;
    const xStep = (W - pad * 2) / (weekly.length - 1);

    const pts = weekly.map((v, i) => {
      const x = pad + i * xStep;
      const y = pad + (H - pad * 2) * (1 - (v - min) / range);
      return [x, y];
    });

    const line = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
    const area = line + ` L${W - pad} ${H} L${pad} ${H} Z`;

    const svg = document.getElementById('spark');
    svg.innerHTML = `
      <defs>
        <linearGradient id="sparkGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#6c5ce7" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#6c5ce7" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path d="${area}" fill="url(#sparkGrad)"/>
      <path d="${line}" fill="none" stroke="#6c5ce7" stroke-width="2.5"
            stroke-linecap="round" stroke-linejoin="round"/>
      <circle cx="${pts[pts.length-1][0]}" cy="${pts[pts.length-1][1]}" r="4"
              fill="#6c5ce7" stroke="#171a23" stroke-width="2"/>
    `;

    const avg = Math.round(weekly.reduce((a, b) => a + b, 0) / weekly.length);
    document.getElementById('avg').textContent = 'avg ' + avg;
  })();

  // --- Focus button + timer ---
  const btn = document.getElementById('focusBtn');
  const btnText = document.getElementById('btnText');
  let running = false, seconds = 0, timer = null;

  btn.addEventListener('click', () => {
    running = !running;
    if (running) {
      btn.classList.add('running');
      seconds = 0;
      tick();
      timer = setInterval(() => { seconds++; tick(); }, 1000);
    } else {
      btn.classList.remove('running');
      clearInterval(timer);
      btnText.textContent = 'Start Focus';
    }
  });

  function tick() {
    const m = String(Math.floor(seconds / 60)).padStart(2, '0');
    const s = String(seconds % 60).padStart(2, '0');
    btnText.textContent = `Focusing  ${m}:${s}`;
  }
</script>
</body>
</html>
```

What you get:

1. **Animated score ring** – an SVG progress ring that fills to the daily score with a counting number and a color-coded status (Excellent / Good / Needs Focus).
2. **Weekly sparkline** – a smooth SVG line + gradient area chart drawn from the `weekly` array, with a highlighted end point, day labels, and computed average.
3. **Start Focus button** – toggles into a live timer with a pulsing indicator dot; click again to stop.

