<script>
  // --- Focus Score ---
  const targetScore = 82;
  const circumference = 2 * Math.PI * 50;
  const progressCircle = document.getElementById('progressCircle');
  const scoreNumber = document.getElementById('scoreNumber');

  setTimeout(() => {
    progressCircle.style.strokeDashoffset = circumference - (circumference * targetScore / 100);
    animateNumber(scoreNumber, 0, targetScore, 1500);
  }, 100);

  function animateNumber(el, start, end, duration) {
    const startTime = performance.now();
    function update(now) {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.round(start + (end - start) * eased);
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  // --- Sparkline ---
  const weeklyData = [65, 72, 58, 80, 74, 90, 82];
  const svgWidth = 320;
  const svgHeight = 60;
  const padding = 10;
  const stepX = (svgWidth - padding * 2) / (weeklyData.length - 1);

  const points = weeklyData.map((val, i) => {
    const x = padding + i * stepX;
    const y = svgHeight - padding - ((val - 50) / 50) * (svgHeight - padding * 2);
    return { x, y };
  });

  // Build smooth path using Catmull-Rom -> Bezier
  function buildSmoothPath(pts) {
    if (pts.length < 2) return '';
    let d = `M ${pts[0].x} ${pts[0].y}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i - 1] || pts[i];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[i + 2] || p2;
      const cp1x = p1.x + (p2.x - p0.x) / 6;
      const cp1y = p1.y + (p2.y - p0.y) / 6;
      const cp2x = p2.x - (p3.x - p1.x) / 6;
      const cp2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
    }
    return d;
  }

  const pathD = buildSmoothPath(points);
  document.getElementById('sparkPath').setAttribute('d', pathD);

  // Area fill
  const areaD = pathD + ` L ${points[points.length - 1].x} ${svgHeight} L ${points[0].x} ${svgHeight} Z`;
  document.getElementById('sparkArea').setAttribute('d', areaD);

  // End dot
  const lastPoint = points[points.length - 1];
  const sparkDot = document.getElementById('sparkDot');
  sparkDot.setAttribute('cx', lastPoint.x);
  sparkDot.setAttribute('cy', lastPoint.y);

  // --- Start Focus Button / Timer ---
  const startBtn = document.getElementById('startBtn');
  const btnText = document.getElementById('btnText');
  const timer = document.getElementById('timer');
  const timerDisplay = document.getElementById('timerDisplay');

  let timerInterval = null;
  let isRunning = false;
  let secondsLeft = 25 * 60;

  function formatTime(sec) {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  }

  startBtn.addEventListener('click', () => {
    if (!isRunning) {
      isRunning = true;
      startBtn.classList.add('active');
      btnText.textContent = 'Stop Session';
      timer.classList.add('active');
      timerInterval = setInterval(() => {
        secondsLeft--;
        timerDisplay.textContent = formatTime(secondsLeft);
        if (secondsLeft <= 0) {
          clearInterval(timerInterval);
          isRunning = false;
          startBtn.classList.remove('active');
          btnText.textContent = 'Start Focus';
          timer.classList.remove('active');
          secondsLeft = 25 * 60;
          timerDisplay.textContent = formatTime(secondsLeft);
        }
      }, 1000);
    } else {
      clearInterval(timerInterval);
      isRunning = false;
      startBtn.classList.remove('active');
      btnText.textContent = 'Start Focus';
      timer.classList.remove('active');
      secondsLeft = 25 * 60;
      timerDisplay.textContent = formatTime(secondsLeft);
    }
  });
</script>

