<body>

    <div class="card">
        <!-- SVG Defs -->
        <svg style="position:absolute;width:0;height:0;">
            <defs>
                <linearGradient id="scoreGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stop-color="#06b6d4" />
                    <stop offset="100%" stop-color="#3b82f6" />
                </linearGradient>
                <linearGradient id="sparkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stop-color="#06b6d4" stop-opacity="0.6" />
                    <stop offset="100%" stop-color="#3b82f6" stop-opacity="1" />
                </linearGradient>
                <linearGradient id="areaGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                    <stop offset="0%" stop-color="#06b6d4" stop-opacity="0.25" />
                    <stop offset="100%" stop-color="#06b6d4" stop-opacity="0" />
                </linearGradient>
            </defs>
        </svg>

        <!-- Header -->
        <div class="card-header">
            <h2>Daily Focus Score</h2>
            <span class="status">
                <span class="status-dot" id="statusDot"></span>
                <span id="statusText">Ready</span>
            </span>
        </div>

        <!-- Score Section -->
        <div class="score-section">
            <div class="score-ring">
                <svg viewBox="0 0 120 120">
                    <circle class="bg-circle" cx="60" cy="60" r="54" />
                    <circle class="progress-circle" id="progressCircle" cx="60" cy="60" r="54" />
                </svg>
            </div>
            <div class="score-text">
                <span class="score-value" id="scoreValue">85</span>
                <span class="score-total">/ 100</span>
            </div>
        </div>

        <!-- Trend Section -->
        <div class="trend-section">
            <h3>Weekly Trend</h3>
            <div class="sparkline-container">
                <svg viewBox="0 0 280 60" id="sparklineSvg">
                    <!-- Area and line will be drawn by JS -->
                </svg>
            </div>
        </div>

        <!-- Button -->
        <button class="start-focus-btn" id="focusBtn">Start Focus</button>
    </div>

    <script>
        (function() {
            // --- Configuration ---
            const R = 54;
            const circumference = 2 * Math.PI * R; // ~339.292

            // --- DOM refs ---
            const progressCircle = document.getElementById('progressCircle');
            const scoreValueEl = document.getElementById('scoreValue');
            const focusBtn = document.getElementById('focusBtn');
            const statusDot = document.getElementById('statusDot');
            const statusText = document.getElementById('statusText');
            const sparklineSvg = document.getElementById('sparklineSvg');

            // --- State ---
            let isFocusing = false;
            let focusInterval = null;
            let currentScore = 85;

            // --- Sparkline data (last 7 days) ---
            const weekData = [62, 68, 74, 79, 83, 81, 85];

            // --- Draw Sparkline ---
            function drawSparkline(data) {
                const width = 280;
                const height = 60;
                const padding = 8;
                const chartW = width - padding * 2;
                const chartH = height - padding * 2;

                const minVal = Math.min(...data);
                const maxVal = Math.max(...data);
                const range = maxVal - minVal || 1;

                const points = data.map((val, i) => {
                    const x = padding + (i / (data.length - 1)) * chartW;
                    const y = padding + chartH - ((val - minVal) / range) * chartH;
                    return { x, y, val };
                });

                // Build polyline points string
                const linePoints = points.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');

                // Build area points (add bottom corners)
                const first = points[0];
                const last = points[points.length - 1];
                const areaPoints = [
                    `${first.x.toFixed(1)},${height}`,
                    ...points.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`),
                    `${last.x.toFixed(1)},${height}`
                ].join(' ');

                // Clear and redraw
                sparklineSvg.innerHTML = `
                    <defs>
                        <linearGradient id="sparkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                            <stop offset="0%" stop-color="#06b6d4" stop-opacity="0.6" />
                            <stop offset="100%" stop-color="#3b82f6" stop-opacity="1" />
                        </linearGradient>
                        <linearGradient id="areaGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                            <stop offset="0%" stop-color="#06b6d4" stop-opacity="0.25" />
                            <stop offset="100%" stop-color="#06b6d4" stop-opacity="0" />
                        </linearGradient>
                    </defs>
                    <polygon class="area" points="${areaPoints}" />
                    <polyline class="line" points="${linePoints}" />
                    ${points.map(p => `<circle class="dot" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" />`).join('')}
                `;
            }

            // --- Update score display ---
            function updateScore(score) {
                currentScore = Math.min(100, Math.max(0, score));
                scoreValueEl.textContent = Math.round(currentScore);

                const offset = circumference - (currentScore / 100) * circumference;
                progressCircle.style.strokeDashoffset = offset;
            }

            // --- Animate score ring on load ---
            function animateScoreRing(targetScore) {
                // Start from 0
                progressCircle.style.strokeDashoffset = circumference;
                // Force reflow
                void progressCircle.offsetWidth;
                // Animate to target
                const targetOffset = circumference - (targetScore / 100) * circumference;
                progressCircle.style.strokeDashoffset = targetOffset;
            }

            // --- Toggle focus ---
            function toggleFocus() {
                isFocusing = !isFocusing;

                if (isFocusing) {
                    focusBtn.textContent = 'Stop Focus';
                    focusBtn.classList.add('focusing');
                    statusDot.className = 'status-dot';
                    statusText.textContent = 'Focusing';

                    // Simulate score increase over time
                    let increment = 0;
                    focusInterval = setInterval(() => {
                        increment += 0.5;
                        const newScore = Math.min(100, currentScore + 0.5);
                        updateScore(newScore);
                        if (newScore >= 100) {
                            clearInterval(focusInterval);
                            focusInterval = null;
                        }
                    }, 2000);
                } else {
                    focusBtn.textContent = 'Start Focus';
                    focusBtn.classList.remove('focusing');
                    statusDot.className = 'status-dot inactive';
                    statusText.textContent = 'Paused';

                    if (focusInterval) {
                        clearInterval(focusInterval);
                        focusInterval = null;
                    }
                }
            }

            // --- Init ---
            function init() {
                // Set initial score
                updateScore(currentScore);

                // Animate ring on next frame
                requestAnimationFrame(() => {
                    animateScoreRing(currentScore);
                });

                // Draw sparkline
                drawSparkline(weekData);

                // Button click
                focusBtn.addEventListener('click', toggleFocus);

                // Reset status dot initially
                statusDot.className = 'status-dot inactive';
            }

            // Run
            init();
        })();
    </script>
</body>
</html>
```

Here is a single‑file HTML dashboard card. It uses only inline HTML, CSS, and JavaScript (no external images or libraries). The card is dark‑mode styled, shows a daily focus score, a weekly trend sparkline drawn with SVG, and a “Start Focus” button that logs a click to the console (you can replace the handler with any action you need).

