</style>
</head>
<body>

<div class="card" id="focusCard">
  <div class="label">Daily Focus Score</div>
  <div class="score" id="focusScore">87</div>
  <svg class="sparkline" id="sparkline" viewBox="0 0 200 60" preserveAspectRatio="none"></svg>
  <button class="button" id="startBtn">Start Focus</button>
</div>

<script>
  // ----- Data (you can replace with real values) -----
  const dailyScore = 87; // 0‑100
  const weeklyData = [62, 68, 70, 75, 80, 78, 87]; // last 7 days

  // ----- Set score -----
  document.getElementById('focusScore').textContent = dailyScore;

  // ----- Draw sparkline -----
  function drawSparkline(data, svg) {
    const width = svg.viewBox.baseVal.width;
    const height = svg.viewBox.baseVal.height;
    const padding = 4; // inner padding
    const usableW = width - 2 * padding;
    const usableH = height - 2 * padding;

    const minVal = Math.min(...data);
    const maxVal = Math.max(...data);
    const range = maxVal - minVal || 1; // avoid division by zero

    // Scale data to points
    const points = data.map((v, i) => {
      const x = padding + (i / (data.length - 1)) * usableW;
      const y = height - (padding + ((v - minVal) / range) * usableH);
      return `${x},${y}`;
    }).join(' ');

    // Create path element
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', `M ${points}`);
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke', 'var(--accent)');
    path.setAttribute('stroke-width', '2');
    path.setAttribute('stroke-linecap', 'round');
    path.setAttribute('stroke-linejoin', 'round');

    // Optional area fill (gradient)
    const areaPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    const areaD = `M ${points} L ${width - padding},${height - padding} L ${padding},${height - padding} Z`;
    areaPath.setAttribute('d', areaD);
    areaPath.setAttribute('fill', 'url(#grad)');
    areaPath.setAttribute('opacity', '0.15');

    // Define gradient (once)
    if (!svg.querySelector('#grad')) {
      const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
      const grad = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
      grad.setAttribute('id', 'grad');
      grad.setAttribute('x1', '0%');
      grad.setAttribute('y1', '0%');
      grad.setAttribute('x2', '0%');
      grad.setAttribute('y2', '100%');
      const stop1 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
      stop1.setAttribute('offset', '0%');
      stop1.setAttribute('stop-color', 'var(--accent)');
      const stop2 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
      stop2.setAttribute('offset', '100%');
      stop2.setAttribute('stop-color', 'var(--accent)');
      stop2.setAttribute('stop-opacity', '0');
      grad.appendChild(stop1);
      grad.appendChild(stop2);
      defs.appendChild(grad);
      svg.appendChild(defs);
    }

    // Clear and redraw
    svg.innerHTML = '';
    svg.appendChild(areaPath);
    svg.appendChild(path);
  }

  // Run after DOM ready
  window.addEventListener('DOMContentLoaded', () => {
    const svg = document.getElementById('sparkline');
    drawSparkline(weeklyData, svg);
  });

  // ----- Button action -----
  document.getElementById('startBtn').addEventListener('click', () => {
    console.log('Focus session started!');
    // Example: you could start a timer, show a modal, etc.
    alert('Focus session started! (Replace this with your actual logic)');
  });
</script>

</body>
</html>
