<script>
  // --- Config ---
  const weeklyData = [62, 78, 55, 89, 71, 94, 86];
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const todayIndex = 6; // Sunday as "today"

  // --- Date ---
  const dateEl = document.getElementById('currentDate');
  const now = new Date();
  dateEl.textContent = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });

  // --- Animate Score ---
  const targetScore = 86;
  const scoreEl = document.getElementById('scoreNumber');
  const ringEl = document.getElementById('scoreRing');
  const glowEl = document.querySelector('.score-ring-glow');
  const circumference = 2 * Math.PI * 54; // 339.292

  let scoreAnimated = false;

  function animateScore() {
    if (scoreAnimated) return;
    scoreAnimated = true;

    let start = null;
    const duration = 1400;

    function step(timestamp) {
      if (!start) start = timestamp;
      const progress = Math.min((timestamp - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.round(eased * targetScore);

      scoreEl.textContent = current;

      const offset = circumference - (eased * targetScore / 100) * circumference;
      ringEl.style.strokeDashoffset = offset;
      glowEl.style.strokeDashoffset = offset;

      if (progress < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  // --- Sparkline ---
  const canvas = document.getElementById('sparklineCanvas');
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;

  function drawSparkline() {
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;
    const pad = 8;
    const maxVal = Math.max(...weeklyData) + 10;
    const minVal = Math.min(...weeklyData) - 10;
    const range = maxVal - minVal;

    const points = weeklyData.map((v, i) => ({
      x: pad + (i / (weeklyData.length - 1)) * (w - pad * 2),
      y: pad + (1 - (v - minVal) / range) * (h - pad * 2)
    }));

    // Gradient fill
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, 'rgba(99, 102, 241, 0.25)');
    grad.addColorStop(1, 'rgba(99, 102, 241, 0)');

    ctx.beginPath();
    ctx.moveTo(points[0].x, h);
    points.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.lineTo(points[points.length - 1].x, h);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // Line
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length; i++) {
      const cpX = (points[i - 1].x + points[i].x) / 2;
      ctx.bezierCurveTo(cpX, points[i - 1].y, cpX, points[i].y, points[i].x, points[i].y);
    }
    ctx.strokeStyle = '#6366f1';
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();

    // Area glow
    ctx.shadowColor = 'rgba(99, 102, 241, 0.4)';
    ctx.shadowBlur = 8;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Dots
    points.forEach((p, i) => {
      const isToday = i === todayIndex;
      const isActive = i <= todayIndex;

      if (isToday) {
        // Outer glow
        ctx.beginPath();
        ctx.arc(p.x, p.y, 10, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(99, 102, 241, 0.15)';
        ctx.fill();

        // Middle
        ctx.beginPath();
        ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(99, 102, 241, 0.3)';
        ctx.fill();

        // Core
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#a78bfa';
        ctx.fill();

        // Inner dot
        ctx.beginPath();
        ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.fill();
      } else if (isActive) {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(99, 102, 241, 0.5)';
        ctx.fill();
        ctx.beginPath();
        ctx.arc(p.x, p.y, 1.5, 0, Math.PI * 2);
        ctx.fillStyle = '#6366f1';
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.15)';
        ctx.fill();
      }
    });
  }

  // --- Day Labels ---
  const daysEl = document.getElementById('sparklineDays');
  days.forEach((day, i) => {
    const span = document.createElement('span');
    span.className = 'day-label';
    if (i < todayIndex) span.classList.add('active');
    if (i === todayIndex) span.classList.add('today');
    span.textContent = day;
    daysEl.appendChild(span);
  });

  // --- Focus Timer ---
  let timerInterval = null;
  let remaining = 25 * 60;
  let isActive = false;

  function toggleFocus() {
    const btn = document.getElementById('focusBtn');
    const timerText = document.getElementById('timerText');

    if (!isActive) {
      isActive = true;
      btn.classList.add('active');
      btn.querySelector('.btn-text:not(.timer-display .btn-text)').textContent = 'End Session';

      timerInterval = setInterval(() => {
        remaining--;
        const m = Math.floor(remaining / 60);
        const s = remaining % 60;
        timerText.textContent = `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;

        if (remaining <= 0) {
          clearInterval(timerInterval);
          btn.classList.remove('active');
          timerText.textContent = '25:00';
          remaining = 25 * 60;
          isActive = false;
          btn.querySelector('.btn-text:not(.timer-display .btn-text)').textContent = 'Start Focus Session';
        }
      }, 1000);
    } else {
      clearInterval(timerInterval);
      btn.classList.remove('active');
      timerText.textContent = '25:00';
      remaining = 25 * 60;
      isActive = false;
      btn.querySelector('.btn-text:not(.timer-display .btn-text)').textContent = 'Start Focus Session';
    }
  }

  // --- Init ---
  const obs = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        animateScore();
        drawSparkline();
        obs.disconnect();
      }
    });
  }, { threshold: 0.3 });

  obs.observe(document.querySelector('.card'));

  window.addEventListener('resize', () => {
    if (scoreAnimated) drawSparkline();
  });
</script>

</body>
</html>
