            <path d="M 0,38 L 46.6,30 L 93.3,34 L 140,20 L 186.6,24 L 233.3,14 L 280,8" fill="none" stroke="#06b6d4" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" />
            <!-- Today's indicator point -->
            <circle cx="280" cy="8" r="4" fill="#06b6d4" stroke="#12161f" stroke-width="2" />
          </svg>
        </div>
        <div class="sparkline-labels">
          <span>Mon</span>
          <span>Tue</span>
          <span>Wed</span>
          <span>Thu</span>
          <span>Fri</span>
          <span>Sat</span>
          <span class="active">Sun</span>
        </div>
      </section>

      <!-- Action Button -->
      <button class="btn-focus" id="focus-btn">
        <div class="pulse-ring"></div>
        <svg class="btn-icon" id="btn-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <polygon points="5 3 19 12 5 21 5 3"></polygon>
        </svg>
        <span id="btn-label">Start Focus Session</span>
      </button>

    </div>
  </div>

  <script>
    const focusBtn = document.getElementById('focus-btn');
    const btnLabel = document.getElementById('btn-label');
    const btnIcon = document.getElementById('btn-icon');
    let isFocusing = false;
    let timerSeconds = 25 * 60; // 25 min pomodoro
    let timerInterval = null;

    function formatTime(totalSeconds) {
      const mins = Math.floor(totalSeconds / 60);
      const secs = totalSeconds % 60;
      return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    }

    focusBtn.addEventListener('click', () => {
      isFocusing = !isFocusing;

      if (isFocusing) {
        // Start Focus Session
        focusBtn.classList.add('active');
        btnIcon.innerHTML = `
          <rect x="6" y="4" width="4" height="16"></rect>
          <rect x="14" y="4" width="4" height="16"></rect>
        `;
        btnLabel.textContent = `Focusing • ${formatTime(timerSeconds)}`;

        timerInterval = setInterval(() => {
          if (timerSeconds > 0) {
            timerSeconds--;
            btnLabel.textContent = `Focusing • ${formatTime(timerSeconds)}`;
          } else {
            clearInterval(timerInterval);
            resetFocusButton();
          }
        }, 1000);

      } else {
        // Stop / Reset Focus Session
        clearInterval(timerInterval);
        resetFocusButton();
      }
    });

    function resetFocusButton() {
      isFocusing = false;
      timerSeconds = 25 * 60;
      focusBtn.classList.remove('active');
      btnIcon.innerHTML = `<polygon points="5 3 19 12 5 21 5 3"></polygon>`;
      btnLabel.textContent = 'Start Focus Session';
    }
  </script>
</body>
</html>
