</head>
<body>

  <div class="card" role="group" aria-label="Daily focus score">
    <div class="card-head">
      <div>
        <div class="label">Daily Focus Score</div>
        <div class="date" id="date"></div>
      </div>
      <div class="chip" id="delta" title="Change vs yesterday"></div>
    </div>

    <div class="score-row">
      <div class="ring-wrap">
        <svg class="ring" viewBox="0 0 120 120" aria-hidden="true">
          <defs>
            <linearGradient id="ringGrad" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%"  stop-color="#7c9cff"/>
              <stop offset="100%" stop-color="#4fd1c5"/>
            </linearGradient>
          </defs>
          <circle class="ring-bg" cx="60" cy="60" r="52"/>
          <circle class="ring-fg" id="ringFg" cx="60" cy="60" r="52"/>
        </svg>
        <div class="ring-center">
          <span class="score" id="score">0</span>
          <span class="score-max">/ 100</span>
        </div>
      </div>

      <div class="spark-wrap">
        <div class="spark-label">This week</div>
        <svg id="spark" viewBox="0 0 220 70" role="img" aria-label="Weekly focus trend"></svg>
        <div class="days">
          <span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span>
          <span>Fri</span><span>Sat</span><span>Sun</span>
        </div>
      </div>
    </div>

    <button class="start" id="startBtn">
      <span class="dot" aria-hidden="true"></span>
      <span class="btn-label">Start Focus</span>
    </button>
  </div>

<script>
  // ---------- data ----------
  const weekData = [62, 71, 58, 76, 84, 79, 87]; // Mon..Sun
  const todayScore = weekData[weekData.length - 1];
  const yesterdayScore = weekData[weekData.length - 2];

  // ---------- date ----------
  document.getElementById('date').textContent =
    new Date().toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });

  // ---------- delta chip ----------
  const delta = todayScore - yesterdayScore;
  const chip = document.getElementById('delta');
  chip.textContent = (delta >= 0 ? '▲ ' : '▼ ') + Math.abs(delta) + ' vs yesterday';
  if (delta < 0) {
    chip.style.color = '#f87171';
    chip.style.background = 'rgba(248,113,113,.1)';
    chip.style.borderColor = 'rgba(248,113,113,.25)';
  }

  // ---------- score count-up + ring fill ----------
  const scoreEl = document.getElementById('score');
  const ringFg = document.getElementById('ringFg');
  const C = 2 * Math.PI * 52;
  ringFg.style.strokeDasharray = C;
  ringFg.style.strokeDashoffset = C;

  (function animateScore() {
    const dur = 900, t0 = performance.now();
    function tick(t) {
      const p = Math.min(1, (t - t0) / dur);
      const eased = 1 - Math.pow(1 - p, 3); // ease-out cubic
      const val = todayScore * eased;
      scoreEl.textContent = Math.round(val);
      ringFg.style.strokeDashoffset = C * (1 - val / 100);
      if (p < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  })();

  // ---------- sparkline (smooth catmull-rom curve) ----------
  (function buildSpark() {
    const svg = document.getElementById('spark');
    const W = 220, H = 70, pad = 8;
    const min = Math.min(...weekData), max = Math.max(...weekData);
    const range = (max - min) || 1;

    const pts = weekData.map((v, i) => [
      pad + i * (W - 2 * pad) / (weekData.length - 1),
      H - pad - (v - min) / range * (H - 2 * pad)
    ]);

    let d = `M ${pts[0][0]} ${pts[0][1]}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i - 1] || pts[i];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[i + 2] || p2;
      const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
      const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
      d += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2[0].toFixed(2)} ${p2[1].toFixed(2)}`;
    }
    const last = pts[pts.length - 1];
    const area = d + ` L ${last[0]} ${H} L ${pts[0][0]} ${H} Z`;

    svg.innerHTML = `
      <defs>
        <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%"  stop-color="#7c9cff"/>
          <stop offset="100%" stop-color="#4fd1c5"/>
        </linearGradient>
        <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%"  stop-color="#7c9cff" stop-opacity=".30"/>
          <stop offset="100%" stop-color="#7c9cff" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path d="${area}" fill="url(#areaGrad)"/>
      <path d="${d}" fill="none" stroke="url(#lineGrad)" stroke-width="2.5" stroke-linecap="round"/>
      <circle cx="${last[0]}" cy="${last[1]}" r="4.5" fill="#4fd1c5" stroke="#141821" stroke-width="2.5"/>
    `;
  })();

  // ---------- Start Focus button ----------
  const btn = document.getElementById('startBtn');
  const btnLabel = btn.querySelector('.btn-label');
  let focusing = false;

  btn.addEventListener('click', () => {
    focusing = !focusing;
    btn.classList.toggle('active', focusing);
    btnLabel.textContent = focusing ? 'Focusing…' : 'Start Focus';
    btn.setAttribute('aria-pressed', String(focusing));
  });
</script>
</body>
</html>
```

What you get in this single file:

- **Dark-mode card** — layered dark gradients, subtle border, and deep shadow, centered on the page.
- **Daily focus score** — large animated number (counts up on load) inside a gradient progress ring that fills to the score, plus a "▲ 8 vs yesterday" chip computed from the data.
- **Weekly sparkline** — pure inline SVG, no images: a smooth catmull-rom curve with a gradient stroke, gradient area fill, and a highlighted dot on today's point, with day labels underneath.
- **Start Focus button** — gradient CTA with hover/active states; clicking toggles it into a "Focusing…" state with a pulsing green dot.

Everything is driven by the `weekData` array at the top of the script — change those numbers and the score, ring, delta chip, and sparkline all update automatically.

