              <stop offset="1" stop-color="#22d3ee"/>
            </linearGradient>
          </defs>
          <circle cx="60" cy="60" r="52" fill="none" stroke="rgba(255,255,255,0.07)" stroke-width="10"/>
          <circle id="ringProg" class="ring-progress" cx="60" cy="60" r="52" fill="none"
                  stroke="url(#ringGrad)" stroke-width="10" stroke-linecap="round"
                  stroke-dasharray="326.73" stroke-dashoffset="326.73"
                  transform="rotate(-90 60 60)"/>
        </svg>
        <div class="ring-center">
          <span class="score-num" id="scoreNum">0</span>
          <span class="score-sub">of 100</span>
        </div>
      </div>
      <div class="score-info">
        <div class="label">Focus Score</div>
        <div class="delta up" id="delta"></div>
        <div class="deep" id="deepWork"></div>
      </div>
    </section>

    <section>
      <div class="chart-head">
        <h2>Weekly Trend</h2>
        <span class="goal-note">goal 70+</span>
      </div>
      <div class="chart-wrap" id="chartWrap">
        <svg id="spark" viewBox="0 0 320 84" role="img" aria-label="Focus score over the last 7 days">
          <defs>
            <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0" stop-color="#22d3ee"/>
              <stop offset="1" stop-color="#34d399"/>
            </linearGradient>
            <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stop-color="#34d399" stop-opacity="0.22"/>
              <stop offset="1" stop-color="#34d399" stop-opacity="0"/>
            </linearGradient>
          </defs>
          <line id="goalLine" x1="10" x2="310" y1="45" y2="45" stroke="rgba(251,191,36,0.3)" stroke-dasharray="4 5"/>
          <path id="areaPath" fill="url(#areaGrad)"/>
          <path id="linePath" fill="none" stroke="url(#lineGrad)" stroke-width="2.5" stroke-linecap="round"/>
          <line id="guide" x1="0" x2="0" y1="6" y2="80" stroke="rgba(255,255,255,0.16)" stroke-dasharray="2 3" style="opacity:0"/>
          <g id="dots"></g>
        </svg>
        <div class="tip" id="tip"><b id="tipVal"></b><span id="tipDay"></span></div>
      </div>
      <div class="day-labels" id="dayLabels"></div>
    </section>

    <div class="stats">
      <div class="stat"><span class="stat-val" id="avgVal">–</span><span class="stat-label">Avg</span></div>
      <div class="stat"><span class="stat-val" id="bestVal">–</span><span class="stat-label">Best</span></div>
      <div class="stat"><span class="stat-val" id="streakVal">–</span><span class="stat-label">Streak</span></div>
    </div>

    <button class="focus-btn" id="focusBtn">
      <svg class="icon-play" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.2v13.6c0 .8.9 1.3 1.6.9l10.8-6.8c.6-.4.6-1.4 0-1.8L9.6 4.3c-.7-.4-1.6.1-1.6.9z"/></svg>
      <span class="pulse-dot" aria-hidden="true"></span>
      <span id="btnLabel">Start Focus</span>
      <span class="btn-timer" id="btnTimer">00:00</span>
    </button>

    <div class="toast" id="toast" role="status"></div>
  </main>

<script>
  (() => {
    "use strict";
    const DATA = [60, 72, 65, 71, 76, 73, 84]; // Mon..Sun, last item = today
    const GOAL = 70;
    const CW = 320, CH = 84, PX = 10, PY = 10;

    const $ = id => document.getElementById(id);
    const ringProg = $("ringProg"), scoreNum = $("scoreNum"), deltaEl = $("delta"),
          deepEl = $("deepWork"), spark = $("spark"), linePath = $("linePath"),
          areaPath = $("areaPath"), goalLine = $("goalLine"), guide = $("guide"),
          dotsG = $("dots"), tip = $("tip"), tipVal = $("tipVal"), tipDay = $("tipDay"),
          chartWrap = $("chartWrap"), avgVal = $("avgVal"), bestVal = $("bestVal"),
          streakVal = $("streakVal"), streakPill = $("streakPill"),
          btn = $("focusBtn"), btnLabel = $("btnLabel"), btnTimer = $("btnTimer"),
          toast = $("toast"), card = $("card");

    /* ---------- dates ---------- */
    const now = new Date();
    const dayNames = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(d.getDate() - i);
      dayNames.push(d.toLocaleDateString("en-US", { weekday: "short" }));
    }
    $("dateStr").textContent = now.toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric" });

    const labelEls = dayNames.map((n, i) => {
      const s = document.createElement("span");
      s.textContent = n;
      if (i === 6) s.classList.add("today");
      $("dayLabels").appendChild(s);
      return s;
    });

    /* ---------- helpers ---------- */
    let chartPts = [];
    let deepMin = Math.round(DATA[6] * 2.4);
    const fmtDeep = m => `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, "0")}m`;
    const fmtClock = s => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

    function animateNumber(el, from, to, dur = 1000) {
      const t0 = performance.now();
      (function tick(t) {
        const p = Math.min(1, (t - t0) / dur);
        const e = 1 - Math.pow(1 - p, 3);
        el.textContent = Math.round(from + (to - from) * e);
        if (p < 1) requestAnimationFrame(tick);
      })(t0);
    }

    /* ---------- score ring ---------- */
    const C = 2 * Math.PI * 52;
    function setRing(score, fromZero) {
      ringProg.style.strokeDasharray = C;
      if (fromZero) {
        ringProg.style.transition = "none";
        ringProg.style.strokeDashoffset = C;
        void ringProg.getBoundingClientRect();
      }
      ringProg.style.transition = "stroke-dashoffset 1s cubic-bezier(.22,1,.36,1)";
      requestAnimationFrame(() => {
        ringProg.style.strokeDashoffset = C * (1 - score / 100);
      });
    }

    /* ---------- sparkline ---------- */
    function smoothPath(p) {
      let d = `M ${p[0][0].toFixed(2)} ${p[0][1].toFixed(2)}`;
      for (let i = 0; i < p.length - 1; i++) {
        const p0 = p[i - 1] || p[i], p1 = p[i], p2 = p[i + 1], p3 = p[i + 2] || p2;
        d += ` C ${(p1[0] + (p2[0] - p0[0]) / 6).toFixed(2)} ${(p1[1] + (p2[1] - p0[1]) / 6).toFixed(2)},` +
             ` ${(p2[0] - (p3[0] - p1[0]) / 6).toFixed(2)} ${(p2[1] - (p3[1] - p1[1]) / 6).toFixed(2)},` +
             ` ${p2[0].toFixed(2)} ${p2[1].toFixed(2)}`;
      }
      return d;
    }

    let dashTimer = null;
    function renderChart(animate) {
      const lo = Math.min(...DATA) - 8, hi = Math.max(...DATA) + 8;
      const xs = DATA.map((_, i) => PX + i * (CW - 2 * PX) / (DATA.length - 1));
      const ys = DATA.map(v => PY + (1 - (v - lo) / (hi - lo)) * (CH - 2 * PY));
      chartPts = xs.map((x, i) => [x, ys[i]]);

      const line = smoothPath(chartPts);
      linePath.setAttribute("d", line);
      areaPath.setAttribute("d", `${line} L ${xs[6].toFixed(2)} ${CH - 2} L ${xs[0].toFixed(2)} ${CH - 2} Z`);

      const gy = (PY + (1 - (GOAL - lo) / (hi - lo)) * (CH - 2 * PY)).toFixed(2);
      goalLine.setAttribute("y1", gy);
      goalLine.setAttribute("y2", gy);

      const NS = "http://www.w3.org/2000/svg";
      dotsG.innerHTML = "";
      chartPts.forEach((pt, i) => {
        const c = document.createElementNS(NS, "circle");
        c.setAttribute("cx", pt[0].toFixed(2));
        c.setAttribute("cy", pt[1].toFixed(2));
        c.setAttribute("r", i === 6 ? 4 : 3);
        c.setAttribute("class", i === 6 ? "dot today" : "dot");
        dotsG.appendChild(c);
      });

      if (animate) {
        const len = linePath.getTotalLength();
        linePath.style.transition = "none";
        linePath.style.strokeDasharray = len;
        linePath.style.strokeDashoffset = len;
        void linePath.getBoundingClientRect();
        linePath.style.transition = "stroke-dashoffset 1.2s cubic-bezier(.4,0,.2,1)";
        linePath.style.strokeDashoffset = 0;

        areaPath.style.transition = "none";
        areaPath.style.opacity = 0;
        void areaPath.getBoundingClientRect();
        areaPath.style.transition = "opacity .8s ease .45s";
        areaPath.style.opacity = 1;

        clearTimeout(dashTimer);
        dashTimer = setTimeout(() => {
          linePath.style.strokeDasharray = "none";
          linePath.style.strokeDashoffset = "0";
        }, 1600);
      }
      positionLabels();
    }

    function positionLabels() {
      const rect = spark.getBoundingClientRect();
      if (!rect.width) return;
      labelEls.forEach((el, i) => {
        el.style.left = (chartPts[i][0] / CW * rect.width) + "px";
      });
    }
    window.addEventListener("resize", positionLabels);

    /* ---------- tooltip ---------- */
    let hotIdx = -1;
    function hideTip() {
      if (hotIdx > -1 && dotsG.children[hotIdx]) dotsG.children[hotIdx].classList.remove("hot");
      hotIdx = -1;
      tip.classList.remove("show");
      guide.style.opacity = 0;
    }
    function showTip(idx) {
      if (hotIdx === idx) return;
      hideTip();
      hotIdx = idx;
      const rect = spark.getBoundingClientRect();
      const [x, y] = chartPts[idx];
      tip.style.left = (x / CW * rect.width) + "px";
      tip.style.top = (y / CH * rect.height) + "px";
      tipVal.textContent = DATA[idx];
      tipDay.textContent = dayNames[idx] + (idx === 6 ? " · today" : "");
      tip.classList.add("show");
      guide.setAttribute("x1", x);
      guide.setAttribute("x2", x);
      guide.style.opacity = 1;
      if (dotsG.children[idx]) dotsG.children[idx].classList.add("hot");
    }
    chartWrap.addEventListener("pointermove", e => {
      const rect = spark.getBoundingClientRect();
      const x = (e.clientX - rect.left) * CW / rect.width;
      let idx = 0, best = Infinity;
      chartPts.forEach((p, i) => {
        const d = Math.abs(p[0] - x);
        if (d < best) { best = d; idx = i; }
      });
      showTip(idx);
    });
    chartWrap.addEventListener("pointerleave", hideTip);

    /* ---------- stats ---------- */
    function updateStats() {
      const delta = DATA[6] - DATA[5];
      deltaEl.textContent = (delta >= 0 ? "▲ +" : "▼ ") + delta + " vs yesterday";
      deltaEl.classList.toggle("up", delta >= 0);
      deltaEl.classList.toggle("down", delta < 0);
      avgVal.textContent = Math.round(DATA.reduce((a, b) => a + b, 0) / DATA.length);
      bestVal.textContent = Math.max(...DATA);
      let s = 0;
      for (let i = DATA.length - 1; i >= 0 && DATA[i] >= GOAL; i--) s++;
      streakVal.textContent = s + "d";
      streakPill.textContent = s;
      deepEl.innerHTML = `Deep work · <b>${fmtDeep(deepMin)}</b>`;
    }

    /* ---------- focus session ---------- */
    let focusing = false, sessionStart = 0, timerInt = null, toastT = null;

    function showToast(msg) {
      toast.textContent = msg;
      toast.classList.add("show");
      clearTimeout(toastT);
      toastT = setTimeout(() => toast.classList.remove("show"), 2600);
    }

    function startSession() {
      focusing = true;
      sessionStart = Date.now();
      card.classList.add("live");
      btn.classList.add("focusing");
      btnLabel.textContent = "End Focus";
      btnTimer.textContent = "00:00";
      timerInt = setInterval(() => {
        btnTimer.textContent = fmtClock(Math.floor((Date.now() - sessionStart) / 1000));
      }, 500);
    }

    function endSession() {
      clearInterval(timerInt);
      const mins = Math.max(1, Math.round((Date.now() - sessionStart) / 60000));
      const old = DATA[6];
      DATA[6] = Math.min(100, old + Math.min(6, mins));
      deepMin += mins;
      const gain = DATA[6] - old;

      focusing = false;
      card.classList.remove("live");
      btn.classList.remove("focusing");
      btnLabel.textContent = "Start Focus";

      animateNumber(scoreNum, old, DATA[6], 900);
      setRing(DATA[6]);
      updateStats();
      renderChart(true);
      hideTip();
      showToast(gain > 0 ? `Session logged · +${gain} pts` : "Session logged");
    }

    btn.addEventListener("click", () => (focusing ? endSession() : startSession()));

    /* ---------- init ---------- */
    setRing(DATA[6], true);
    animateNumber(scoreNum, 0, DATA[6], 1200);
    renderChart(true);
    updateStats();
  })();
</script>
</body>
</html>
```

**What's included:**

- **Focus score** — animated SVG progress ring with count-up number, delta vs. yesterday, and a deep-work total
- **Weekly trend sparkline** — smooth Catmull-Rom curve with gradient area fill, dashed goal line, draw-in animation, and a hover tooltip with guide line showing each day's value
- **Start Focus button** — click to begin a session (button switches to a pulsing "End Focus" state with a live timer, and the ring glows); ending a session logs points, bumps today's score, and re-animates the ring, stats, and sparkline
- **Extras** — real current date and weekday labels computed from `Date`, streak/avg/best stats, toast notifications, keyboard focus styles, and `prefers-reduced-motion` support

All graphics are inline SVG and CSS — zero network requests. Want a pomodoro countdown instead of a count-up timer, or the data wired to `localStorage` so it persists between visits? Happy to add either.

