        <!-- Score Section -->
        <div class="score-section">
            <div class="ring-container">
                <svg viewBox="0 0 130 130" aria-hidden="true">
                    <circle class="ring-bg" cx="65" cy="65" r="56" />
                    <circle class="ring-progress" id="ringProgress" cx="65" cy="65" r="56"
                    stroke-dasharray="351.86" stroke-dashoffset="351.86" />
                </svg>
                <div class="ring-center">
                    <div class="ring-score" id="ringScore">0</div>
                    <div class="ring-label">Focus Score</div>
                </div>
            </div>
            <div class="score-details">
                <div class="stat-row">
                    <span class="stat-label">Sessions</span>
                    <span class="stat-value" id="sessionCount">0</span>
                </div>
                <div class="stat-row">
                    <span class="stat-label">Total Minutes</span>
                    <span class="stat-value" id="totalMinutes">0</span>
                </div>
                <div class="stat-row">
                    <span class="stat-label">Best Streak</span>
                    <span class="stat-value highlight" id="bestStreak">0 days</span>
                </div>
            </div>
        </div>

        <div class="divider"></div>

        <!-- Trend Section -->
        <div class="trend-section">
            <div class="trend-header">
                <span class="trend-title">Weekly Trend</span>
                <span class="trend-change up" id="trendChange">▲ 12%</span>
            </div>
            <div class="sparkline-wrapper">
                <svg viewBox="0 0 360 72" preserveAspectRatio="none" aria-hidden="true">
                    <defs>
                        <linearGradient id="sparkGradient" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stop-color="#6c8cff" stop-opacity="0.45" />
                            <stop offset="100%" stop-color="#6c8cff" stop-opacity="0.02" />
                        </linearGradient>
                    </defs>
                    <path class="sparkline-area" id="sparkArea" d="" />
                    <path class="sparkline-line" id="sparkLine" d="" />
                    <circle class="sparkline-dot" id="sparkDot" cx="0" cy="0" r="4.5" />
                </svg>
            </div>
            <div class="day-labels" id="dayLabels">
                <span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span>
            </div>
        </div>

        <!-- Focus Button -->
        <button class="focus-btn idle" id="focusBtn">
            <span class="btn-icon" id="btnIcon">▶</span>
            <span id="btnText">Start Focus</span>
            <span class="timer-text" id="timerText" style="display:none;"></span>
            <span class="pulse-dot" id="pulseDot" style="display:none;"></span>
        </button>
    </div>

    <script>
        (function() {
            // ─── State ────────────────────────────────────────────────
            const state = {
                focusScore: 72,
                sessions: 4,
                totalMinutes: 168,
                bestStreak: 6,
                weeklyData: [58, 64, 71, 68, 75, 82, 72],
                isFocusing: false,
                focusSeconds: 0,
                timerInterval: null,
                sessionStartTime: null,
            };

            // ─── DOM refs ────────────────────────────────────────────
            const ringProgress = document.getElementById('ringProgress');
            const ringScore = document.getElementById('ringScore');
            const sessionCount = document.getElementById('sessionCount');
            const totalMinutes = document.getElementById('totalMinutes');
            const bestStreak = document.getElementById('bestStreak');
            const trendChange = document.getElementById('trendChange');
            const sparkArea = document.getElementById('sparkArea');
            const sparkLine = document.getElementById('sparkLine');
            const sparkDot = document.getElementById('sparkDot');
            const focusBtn = document.getElementById('focusBtn');
            const btnIcon = document.getElementById('btnIcon');
            const btnText = document.getElementById('btnText');
            const timerText = document.getElementById('timerText');
            const pulseDot = document.getElementById('pulseDot');
            const dateBadge = document.getElementById('dateBadge');
            const dashboardCard = document.getElementById('dashboardCard');

            const CIRCUMFERENCE = 2 * Math.PI * 56; // ≈ 351.86

            // ─── Date badge ──────────────────────────────────────────
            function updateDateBadge() {
                const now = new Date();
                const options = { weekday: 'short', month: 'short', day: 'numeric' };
                dateBadge.textContent = now.toLocaleDateString('en-US', options);
            }

            // ─── Ring rendering ─────────────────────────────────────
            function renderRing(animate = true) {
                const score = Math.min(100, Math.max(0, state.focusScore));
                const offset = CIRCUMFERENCE - (score / 100) * CIRCUMFERENCE;
                ringProgress.style.strokeDashoffset = offset;
                ringScore.textContent = Math.round(score);

                if (animate) {
                    ringScore.classList.remove('score-updated');
                    void ringScore.offsetWidth; // reflow
                    ringScore.classList.add('score-updated');
                }
            }

            // ─── Stats rendering ────────────────────────────────────
            function renderStats() {
                sessionCount.textContent = state.sessions;
                totalMinutes.textContent = state.totalMinutes;
                bestStreak.textContent = state.bestStreak + ' days';
            }

            // ─── Sparkline rendering ────────────────────────────────
            function renderSparkline() {
                const data = state.weeklyData;
                const width = 360;
                const height = 72;
                const padding = 8;
                const chartWidth = width - padding * 2;
                const chartHeight = height - padding * 2;
                const maxVal = Math.max(...data);
                const minVal = Math.min(...data);
                const range = maxVal - minVal || 1;

                const points = data.map((val, i) => {
                    const x = padding + (i / (data.length - 1)) * chartWidth;
                    const y = padding + chartHeight - ((val - minVal) / range) * chartHeight;
                    return { x, y, val };
                });

                // Line path
                const linePath = points.map((p, i) =>
                    (i === 0 ? 'M' : 'L') + p.x.toFixed(1) + ' ' + p.y.toFixed(1)
                ).join(' ');

                // Area path (close to bottom)
                const areaPath = linePath +
                    ' L' + points[points.length - 1].x.toFixed(1) + ' ' + (height - padding).toFixed(1) +
                    ' L' + points[0].x.toFixed(1) + ' ' + (height - padding).toFixed(1) +
                    ' Z';

                sparkLine.setAttribute('d', linePath);
                sparkArea.setAttribute('d', areaPath);

                // Dot at last point
                const lastPoint = points[points.length - 1];
                sparkDot.setAttribute('cx', lastPoint.x.toFixed(1));
                sparkDot.setAttribute('cy', lastPoint.y.toFixed(1));

                // Trend change calculation
                const firstVal = data[0];
                const lastVal = data[data.length - 1];
                const pctChange = ((lastVal - firstVal) / firstVal) * 100;
                const isUp = pctChange >= 0;

                trendChange.textContent = (isUp ? '▲ ' : '▼ ') + Math.abs(pctChange).toFixed(0) + '%';
                trendChange.className = 'trend-change ' + (isUp ? 'up' : 'down');
            }

            // ─── Timer formatting ───────────────────────────────────
            function formatTime(seconds) {
                const mins = Math.floor(seconds / 60);
                const secs = seconds % 60;
                return String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
            }

            // ─── Button state management ────────────────────────────
            function setButtonIdle() {
                state.isFocusing = false;
                if (state.timerInterval) {
                    clearInterval(state.timerInterval);
                    state.timerInterval = null;
                }
                focusBtn.className = 'focus-btn idle';
                btnIcon.textContent = '▶';
                btnIcon.style.display = 'inline';
                btnText.textContent = 'Start Focus';
                btnText.style.display = 'inline';
                timerText.style.display = 'none';
                pulseDot.style.display = 'none';
                dashboardCard.style.borderColor = 'var(--card-border)';
            }

            function setButtonActive() {
                state.isFocusing = true;
                focusBtn.className = 'focus-btn active';
                btnIcon.textContent = '⏸';
                btnIcon.style.display = 'inline';
                btnText.textContent = 'Focusing…';
                btnText.style.display = 'inline';
                timerText.style.display = 'inline';
                timerText.textContent = formatTime(state.focusSeconds);
                pulseDot.style.display = 'inline';
                dashboardCard.style.borderColor = 'rgba(52, 211, 153, 0.4)';
            }

            function toggleFocus() {
                if (state.isFocusing) {
                    // Stop focus session
                    const elapsedMin = Math.floor(state.focusSeconds / 60);
                    if (elapsedMin > 0) {
                        state.totalMinutes += elapsedMin;
                        state.sessions += 1;
                        // Bump focus score slightly
                        state.focusScore = Math.min(100, state.focusScore + Math.min(3, elapsedMin));
                        // Update weekly data (today's value)
                        state.weeklyData[state.weeklyData.length - 1] = Math.min(100,
                            state.weeklyData[state.weeklyData.length - 1] + Math.min(2, elapsedMin)
                        );
                        renderStats();
                        renderRing();
                        renderSparkline();
                    }
                    state.focusSeconds = 0;
                    setButtonIdle();
                } else {
                    // Start focus session
                    state.focusSeconds = 0;
                    setButtonActive();
                    state.timerInterval = setInterval(() => {
                        state.focusSeconds += 1;
                        timerText.textContent = formatTime(state.focusSeconds);
                    }, 1000);
                }
            }

            // ─── Simulate live score updates (demo polish) ──────────
            function simulateScoreFluctuation() {
                // Subtle ambient animation: occasionally nudge score
                if (!state.isFocusing) {
                    const shouldNudge = Math.random() < 0.15;
                    if (shouldNudge) {
                        const delta = (Math.random() - 0.5) * 4;
                        state.focusScore = Math.min(100, Math.max(45, state.focusScore + delta));
                        renderRing(false);
                    }
                }
            }

            // ─── Initialization ─────────────────────────────────────
            function init() {
                updateDateBadge();
                renderRing(false);
                renderStats();
                renderSparkline();
                setButtonIdle();

                // Event listeners
                focusBtn.addEventListener('click', toggleFocus);

                // Ambient score fluctuation (subtle, every 4s)
                setInterval(simulateScoreFluctuation, 4000);

                // Keyboard shortcut: Space to toggle focus
                document.addEventListener('keydown', (e) => {
                    if (e.code === 'Space' && !e.target.matches('input, textarea, button')) {
                        e.preventDefault();
                        toggleFocus();
                    }
                });
            }

            // ─── Boot ───────────────────────────────────────────────
            init();
        })();
    </script>
</body>
</html>
```
### Focus Card Features

This dashboard card brings together your focus metrics and a practical timer in one view. Here's how it works:

- **Focus Score Ring** – A circular progress indicator shows your daily score (0–100) with a smooth animated transition. The ring glows softly to highlight your current level.
- **Weekly Trend Sparkline** – A lightweight SVG chart plots your last seven days of focus data. The area fill and glowing line make the trend easy to read at a glance, with a percentage change badge (▲/▼) above it.
- **Start Focus Button** – Clicking the button toggles between an idle state (blue "Start Focus") and an active state (green "Focusing…" with a live timer). When you stop a session, the elapsed minutes automatically update your total minutes, session count, and focus score.
- **Live Stats Panel** – Displays session count, total focused minutes, and your best streak. These numbers update in real time as you complete focus sessions.
- **Keyboard Shortcut** – Press the `Space` bar (when not typing in an input) to start or stop a focus session without clicking the button.

---

**Optimization Tip:** You can adjust the weekly trend data by modifying the `weeklyData` array (line ~330) and the initial focus score/sessions in the `state` object (line ~300).

