<div class="card">
  <div class="card-header">
    <span class="card-title">Focus Overview</span>
    <div class="status-dot"></div>
  </div>

  <!-- Daily Score Ring -->
  <div class="score-section">
    <div class="ring-container">
      <svg width="160" height="160" viewBox="0 0 160 160">
        <defs>
          <linearGradient id="scoreGradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stop-color="#818cf8"/>
            <stop offset="100%" stop-color="#22d3ee"/>
          </linearGradient>
        </defs>
        <circle class="ring-bg" cx="80" cy="80" r="70"/>
        <circle class="ring-progress" id="scoreRing" cx="80" cy="80" r="70"/>
      </svg>
      <div class="score-center">
        <div class="score-value" id="scoreValue">0</div>
        <div class="score-label">FOCUS SCORE</div>
      </div>
    </div>
    <div class="score-caption" id="scoreCaption">Loading…</div>
  </div>

  <!-- Weekly Sparkline -->
  <div class="trend-section">
    <div class="trend-header">
      <span class="trend-title">This Week</span>
      <span class="trend-delta delta-up" id="trendDelta">▲ +0%</span>
    </div>
    <div class="sparkline-wrap">
      <svg width="100%" height="60" viewBox="0 0 280 60" preserveAspectRatio="none">
        <defs>
          <linearGradient id="areaGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stop-color="#818cf8" stop-opacity="0.25"/>
            <stop offset="100%" stop-color="#818cf8" stop-opacity="0"/>
          </linearGradient>
        </defs>
        <path class="sparkline-area" id="sparkArea" d=""/>
        <polyline class="sparkline-line" id="sparkLine" points=""/>
        <circle class="spark-dot" id="sparkDot" r="3.5" cx="0" cy="0"/>
      </svg>
      <div class="day-labels">
        <span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span>
      </div>
    </div>
  </div>

  <!-- Start Button -->
  <button class="start-btn btn-shine" id="startBtn">Start Focus</button>
  <div class="session-timer" id="sessionTimer"></div>
</div>

<script>
(function() {
  // ---- Data ----
  const weeklyScores = [62, 71, 58, 78, 84, 90, 76];
  const todayScore = weeklyScores[weeklyScores.length - 1];

  // ---- Animate score ring & counter ----
  const CIRCUMFERENCE = 2 * Math.PI * 70;
  const ring = document.getElementById('scoreRing');
  const scoreValue = document.getElementById('scoreValue');
  const caption = document.getElementById('scoreCaption');

  function getCaption(score) {
    if (score >= 85) return 'Excellent — deep work mode 🔥';
    if (score >= 70) return 'Good — solid momentum today';
    if (score >= 50) return 'Fair — room to improve';
    return 'Low — try a focus session';
  }

  requestAnimationFrame(() => {
    setTimeout(() => {
      ring.style.strokeDashoffset = CIRCUMFERENCE * (1 - todayScore / 100);

      let current = 0;
      const duration = 1400;
      const start = performance.now();
      function tick(now) {
        const t = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - t, 3); // ease-out cubic
        scoreValue.textContent = Math.round(eased * todayScore);
        if (t < 1) requestAnimationFrame(tick);
        else caption.textContent = getCaption(todayScore);
      }
      requestAnimationFrame(tick);
    }, 200);
  });

  // ---- Sparkline ----
  const W = 280, H = 60, PAD = 6;
  const min = Math.min(...weeklyScores);
  const max = Math.max(...weeklyScores);
  const range = max - min || 1;

  const points = weeklyScores.map((v, i) => {
    const x = PAD + (i / (weeklyScores.length - 1)) * (W - PAD * 2);
    const y = H - PAD - ((v - min) / range) * (H - PAD * 2);
    return [x, y];
  });

  const ptsStr = points.map(p => p.join(',')).join(' ');
  document.getElementById('sparkLine').setAttribute('points', ptsStr);

  const areaPath = `M ${points[0][0]},${H} L ${ptsStr.split(' ').join(' L ')} L ${points[points.length-1][0]},${H} Z`;
  document.getElementById('sparkArea').setAttribute('d', areaPath);

  // Highlight last point
  const last = points[points.length - 1];
  const dot = document.getElementById('sparkDot');
  dot.setAttribute('cx', last[0]);
  dot.setAttribute('cy', last[1]);

  // Week-over-week delta
  const prevWeekAvg = 68; // simulated previous week average
  const thisWeekAvg = Math.round(weeklyScores.reduce((a,b)=>a+b)/weeklyScores.length);
  const delta = Math.round(((thisWeekAvg - prevWeekAvg) / prevWeekAvg) * 100);
  const deltaEl = document.getElementById('trendDelta');
  if (delta >= 0) {
    deltaEl.textContent = `▲ +${delta}%`;
    deltaEl.className = 'trend-delta delta-up';
  } else {
    deltaEl.textContent = `▼ ${delta}%`;
    deltaEl.className = 'trend-delta delta-down';
  }

  // ---- Start Focus button ----
  const btn = document.getElementById('startBtn');
  const timerEl = document.getElementById('sessionTimer');
  let running = false;
  let intervalId = null;

  btn.addEventListener('click', () => {
    running = !running;

    if (running) {
      btn.classList.add('running');
      btn.textContent = 'End Focus';
      let seconds = 0;
      timerEl.textContent = 'Session started · 00:00';
      intervalId = setInterval(() => {
        seconds++;
        const m = String(Math.floor(seconds / 60)).padStart(2, '0');
        const s = String(seconds % 60).padStart(2, '0');
        timerEl.textContent = `In session · ${m}:${s}`;
      }, 1000);
    } else {
      clearInterval(intervalId);
      btn.classList.remove('running');
      btn.textContent = 'Start Focus';
      timerEl.textContent = 'Session ended ✓';
      setTimeout(() => { timerEl.textContent = ''; }, 3000);
    }
  });
})();
</script>

</body>
</html>
