<body>

<div class="card">
  <div class="header">
    <h1>Daily Focus</h1>
    <span class="date" id="date"></span>
  </div>

  <div class="score-wrap">
    <div class="ring">
      <svg width="110" height="110" viewBox="0 0 110 110">
        <circle class="track" cx="55" cy="55" r="48" stroke-width="9" fill="none"/>
        <circle class="progress" id="ringProgress" cx="55" cy="55" r="48" stroke-width="9" fill="none"/>
      </svg>
      <div class="value">
        <strong id="scoreValue">0</strong>
        <span>score</span>
      </div>
    </div>
    <div class="stats">
      <div class="label">Focused today</div>
      <div class="big" id="focusedTime">3h 42m</div>
      <span class="delta" id="delta">▲ 12% vs yesterday</span>
    </div>
  </div>

  <div class="trend">
    <div class="trend-head">
      <span>Weekly trend</span>
      <span>Avg <b id="avg">—</b></span>
    </div>
    <svg class="spark" id="spark" viewBox="0 0 280 60" preserveAspectRatio="none">
      <defs>
        <linearGradient id="sparkFill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#6ee7b7" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#6ee7b7" stop-opacity="0"/>
        </linearGradient>
      </defs>
    </svg>
    <div class="days" id="days"></div>
  </div>

  <button class="btn" id="focusBtn">
    <span class="icon"></span>
    <span class="btn-text">Start Focus</span>
  </button>
</div>

<script>
  // ---- Data ----
  const todayScore = 82;
  const weekly = [64, 71, 58, 77, 69, 74, todayScore];
  const dayLabels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  // ---- Date ----
  document.getElementById('date').textContent =
    new Date().toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });

  // ---- Score ring ----
  const ring = document.getElementById('ringProgress');
  const r = 48, circ = 2 * Math.PI * r;
  ring.style.strokeDasharray = circ;
  ring.style.strokeDashoffset = circ;

  const scoreEl = document.getElementById('scoreValue');
  requestAnimationFrame(() => {
    ring.style.strokeDashoffset = circ * (1 - todayScore / 100);
    const start = performance.now(), dur = 1200;
    (function tick(now) {
      const t = Math.min(1, (now - start) / dur);
      const eased = 1 - Math.pow(1 - t, 3);
      scoreEl.textContent = Math.round(todayScore * eased);
      if (t < 1) requestAnimationFrame(tick);
    })(start);
  });

  // ---- Delta ----
  const yesterday = weekly[weekly.length - 2];
  const pct = Math.round(((todayScore - yesterday) / yesterday) * 100);
  const deltaEl = document.getElementById('delta');
  deltaEl.textContent = `${pct >= 0 ? '▲' : '▼'} ${Math.abs(pct)}% vs yesterday`;
  deltaEl.classList.toggle('down', pct < 0);

  // ---- Sparkline ----
  const svg = document.getElementById('spark');
  const W = 280, H = 60, pad = 6;
  const min = Math.min(...weekly) - 5, max = Math.max(...weekly) + 5;
  const pts = weekly.map((v, i) => ({
    x: pad + (i / (weekly.length - 1)) * (W - pad * 2),
    y: H - pad - ((v - min) / (max - min)) * (H - pad * 2)
  }));

  // smooth path via Catmull-Rom → Bezier
  function smoothPath(p) {
    let d = `M ${p[0].x} ${p[0].y}`;
    for (let i = 0; i < p.length - 1; i++) {
      const p0 = p[i - 1] || p[i], p1 = p[i], p2 = p[i + 1], p3 = p[i + 2] || p2;
      const c1x = p1.x + (p2.x - p0.x) / 6, c1y = p1.y + (p2.y - p0.y) / 6;
      const c2x = p2.x - (p3.x - p1.x) / 6, c2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2.x} ${p2.y}`;
    }
    return d;
  }

  const lineD = smoothPath(pts);
  const areaD = `${lineD} L ${pts[pts.length - 1].x} ${H} L ${pts[0].x} ${H} Z`;
  const ns = 'http://www.w3.org/2000/svg';

  const area = document.createElementNS(ns, 'path');
  area.setAttribute('d', areaD); area.setAttribute('class', 'area');
  svg.appendChild(area);

  const line = document.createElementNS(ns, 'path');
  line.setAttribute('d', lineD); line.setAttribute('class', 'line');
  svg.appendChild(line);

  const last = pts[pts.length - 1];
  const dot = document.createElementNS(ns, 'circle');
  dot.setAttribute('cx', last.x); dot.setAttribute('cy', last.y); dot.setAttribute('r', 4);
  dot.setAttribute('class', 'dot');
  svg.appendChild(dot);

  // animate line draw
  const len = line.getTotalLength();
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  line.style.transition = 'stroke-dashoffset 1.4s ease-out';
  requestAnimationFrame(() => (line.style.strokeDashoffset = 0));

  document.getElementById('avg').textContent =
    Math.round(weekly.reduce((a, b) => a + b, 0) / weekly.length);

  document.getElementById('days').innerHTML = dayLabels
    .map((d, i) => `<span class="${i === dayLabels.length - 1 ? 'today' : ''}">${d}</span>`)
    .join('');

  // ---- Focus button ----
  const btn = document.getElementById('focusBtn');
  const btnText = btn.querySelector('.btn-text');
  let running = false, interval = null, secs = 25 * 60;

  const fmt = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;

  btn.addEventListener('click', () => {
    running = !running;
    btn.classList.toggle('active', running);
    if (running) {
      secs = 25 * 60;
      btnText.innerHTML = `Focusing · <span class="timer">${fmt(secs)}</span>`;
      interval = setInterval(() => {
        secs--;
        btnText.innerHTML = `Focusing · <span class="timer">${fmt(secs)}</span>`;
        if (secs <= 0) { clearInterval(interval); running = false; btn.classList.remove('active'); btnText.textContent = 'Session complete ✓'; }
      }, 1000);
    } else {
      clearInterval(interval);
      btnText.textContent = 'Start Focus';
    }
  });
</script>
</body>
</html>
```

Everything is inline: the score ring and sparkline are SVG generated in JS, the play icon is a CSS triangle, and the button toggles into a live 25-minute countdown. Swap the `weekly` array and `todayScore` to plug in real data.

