    const focusButton = document.getElementById('focusButton');
    const btnText = document.getElementById('btnText');
    const btnIcon = document.getElementById('btnIcon');
    const sessionInfo = document.getElementById('sessionInfo');
    const sessionTimer = document.getElementById('sessionTimer');
    const focusScore = document.getElementById('focusScore');

    let isSessionRunning = false;
    let timerInterval = null;
    let elapsedSeconds = 0;

    focusButton.addEventListener('click', () => {
      isSessionRunning = !isSessionRunning;

      if (isSessionRunning) {
        // Start Focus State
        focusButton.classList.add('active-session');
        btnText.textContent = 'End Session';

        // Square Stop Icon
        btnIcon.innerHTML = '<rect x="6" y="6" width="12" height="12" rx="2"></rect>';

        sessionInfo.classList.add('visible');
        elapsedSeconds = 0;
        sessionTimer.textContent = '00:00';

        timerInterval = setInterval(() => {
          elapsedSeconds++;
          const mins = String(Math.floor(elapsedSeconds / 60)).padStart(2, '0');
          const secs = String(elapsedSeconds % 60).padStart(2, '0');
          sessionTimer.textContent = `${mins}:${secs}`;
        }, 1000);
      } else {
        // Stop Focus State
        focusButton.classList.remove('active-session');
        btnText.textContent = 'Start Focus';

        // Play Triangle Icon
        btnIcon.innerHTML = '<polygon points="5 3 19 12 5 21 5 3"></polygon>';

        sessionInfo.classList.remove('visible');
        clearInterval(timerInterval);

        // Small simulated bump to focus score if session lasted at least 5s
        if (elapsedSeconds >= 5) {
          const current = parseInt(focusScore.textContent, 10);
          if (current < 99) {
            focusScore.textContent = current + 1;
          }
        }
      }
    });

    // Interactive tooltip-like score hover on sparkline points
    const points = document.querySelectorAll('.data-point');
    const originalScore = focusScore.textContent;

    points.forEach((point) => {
      point.addEventListener('mouseenter', () => {
        const val = point.getAttribute('data-val');
        focusScore.textContent = val;
      });

      point.addEventListener('mouseleave', () => {
        focusScore.textContent = originalScore;
      });
    });
  </script>
