  <script>
    // Sample dashboard history.
    const scores = [52, 66, 60, 75, 68, 79, 84];
    const points = scores.map((score, index) => ({
      x: 18 + index * (344 / 6),
      y: 96 - ((score - 45) / 45) * 78
    }));

    let path = `M ${points[0].x} ${points[0].y}`;
    for (let i = 1; i < points.length; i++) {
      const previous = points[i - 1];
      const current = points[i];
      const middle = (previous.x + current.x) / 2;
      path += ` C ${middle} ${previous.y}, ${middle} ${current.y}, ${current.x} ${current.y}`;
    }

    document.getElementById("chart-line").setAttribute("d", path);
    document.getElementById("chart-area").setAttribute("d", `${path} L 362 108 L 18 108 Z`);

    const last = points[points.length - 1];
    const svgNS = "http://www.w3.org/2000/svg";
    [
      { radius: 9, fill: "#c2ef8714" },
      { radius: 4, fill: "#c2ef87", stroke: "#1a1d19" }
    ].forEach(({ radius, fill, stroke }) => {
      const circle = document.createElementNS(svgNS, "circle");
      circle.setAttribute("cx", last.x);
      circle.setAttribute("cy", last.y);
      circle.setAttribute("r", radius);
      circle.setAttribute("fill", fill);
      if (stroke) {
        circle.setAttribute("stroke", stroke);
        circle.setAttribute("stroke-width", "2");
      }
      document.getElementById("chart-points").appendChild(circle);
    });

    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const label = document.createElement("span");
      label.textContent = i === 0 ? "Today" : date.toLocaleDateString("en-US", { weekday: "short" });
      document.getElementById("chart-days").appendChild(label);
    }

    const duration = 25 * 60 * 1000;
    const button = document.getElementById("focus-button");
    const buttonLabel = document.getElementById("button-label");
    const buttonIcon = document.getElementById("button-icon");
    const timerRow = document.getElementById("timer-row");
    const timer = document.getElementById("timer");
    const timerStatus = document.getElementById("timer-status");
