    const playIcon = buttonIcon.getAttribute("d");
    const pauseIcon = "M5 4h3.5v12H5z M11.5 4H15v12h-3.5z";

    let remaining = duration;
    let deadline = 0;
    let running = false;
    let interval;
    let focusedMinutes = 134;
    let sessions = 4;

    function renderTime() {
      const seconds = Math.max(0, Math.ceil(remaining / 1000));
      const minutesPart = String(Math.floor(seconds / 60)).padStart(2, "0");
      const secondsPart = String(seconds % 60).padStart(2, "0");
      timer.textContent = `${minutesPart}:${secondsPart}`;
      timer.setAttribute("datetime", `PT${seconds}S`);
    }

    function setButton(label, active) {
      buttonLabel.textContent = label;
      buttonIcon.setAttribute("d", active ? pauseIcon : playIcon);
    }

    function tick() {
      remaining = Math.max(0, deadline - Date.now());
      renderTime();

      if (remaining === 0) {
        clearInterval(interval);
        running = false;
        focusedMinutes += 25;
        sessions += 1;
        document.getElementById("focused-time").textContent =
          `${Math.floor(focusedMinutes / 60)}h ${focusedMinutes % 60}m`;
        document.getElementById("session-count").textContent = `${sessions} sessions`;
        timerRow.hidden = true;
        setButton("Start Another Session", false);
        note.textContent = "Session complete. Nicely done — take a short break.";
      }
    }

    button.addEventListener("click", () => {
      if (running) {
        tick();
        if (!running) return;
        clearInterval(interval);
        running = false;
        timerStatus.textContent = "Paused";
        setButton("Resume Focus", false);
        note.textContent = "Take a breath. Your session is here when you're ready.";
        return;
      }

      if (remaining <= 0) remaining = duration;
      deadline = Date.now() + remaining;
      running = true;
      timerRow.hidden = false;
      timerStatus.textContent = "Time remaining";
      setButton("Pause Focus", true);
      note.textContent = "You've got this. Give one thing your full attention.";
      tick();
      interval = setInterval(tick, 250);
    });

    document.getElementById("reset-button").addEventListener("click", () => {
      clearInterval(interval);
      running = false;
      remaining = duration;
      timerRow.hidden = true;
      renderTime();
      setButton("Start Focus", false);
      note.textContent = "25-minute session · One thing at a time";
      button.focus();
    });

    document.addEventListener("visibilitychange", () => {
      if (!document.hidden && running) tick();
    });
  </script>
