  <script>
    const targetScore = 84;
    const weeklyData = [62, 71, 58, 76, 69, 88, 84];

    const ring = document.getElementById("ring");
    const scoreNumber = document.getElementById("scoreNumber");
    const trendDelta = document.getElementById("trendDelta");
    const sparkLine = document.getElementById("sparkLine");
    const sparkGlow = document.getElementById("sparkGlow");
    const sparkArea = document.getElementById("sparkArea");
    const sparkDot = document.getElementById("sparkDot");
    const focusButton = document.getElementById("focusButton");
    const buttonLabel = document.getElementById("buttonLabel");
    const status = document.getElementById("status");

    function animateScore() {
      const duration = 1400;
      const start = performance.now();

      function frame(now) {
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const value = Math.round(targetScore * eased);

        scoreNumber.textContent = value;
        ring.style.setProperty("--score", value);

        if (progress < 1) requestAnimationFrame(frame);
      }

      requestAnimationFrame(frame);
    }

    function renderSparkline(data) {
      const width = 240;
      const height = 76;
      const padding = 10;
      const min = Math.min(...data) - 5;
      const max = Math.max(...data) + 5;

      const points = data.map((value, index) => {
        const x = padding + (index * (width - padding * 2)) / (data.length - 1);
        const y = height - padding - ((value - min) / (max - min)) * (height - padding * 2);
        return { x, y };
      });

      const linePath = points
        .map((point, index) => `${index === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`)
        .join(" ");

      const areaPath = `${linePath} L ${points[points.length - 1].x.toFixed(2)} ${height} L ${points[0].x.toFixed(2)} ${height} Z`;

      sparkLine.setAttribute("d", linePath);
      sparkGlow.setAttribute("d", linePath);
      sparkArea.setAttribute("d", areaPath);
      sparkDot.setAttribute("cx", points[points.length - 1].x.toFixed(2));
      sparkDot.setAttribute("cy", points[points.length - 1].y.toFixed(2));

      const first = data[0];
      const last = data[data.length - 1];
      const delta = Math.round(((last - first) / first) * 100);
      trendDelta.textContent = `${delta >= 0 ? "+" : ""}${delta}%`;
      trendDelta.style.color = delta >= 0 ? "var(--success)" : "var(--danger)";
    }

    let timerId = null;
    let secondsLeft = 25 * 60;
    let running = false;

    function formatTime(totalSeconds) {
      const minutes = Math.floor(totalSeconds / 60);
      const seconds = totalSeconds % 60;
      return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
    }

    function updateButtonState() {
      focusButton.classList.toggle("running", running);
      focusButton.setAttribute("aria-pressed", String(running));
      buttonLabel.textContent = running ? "Pause Focus" : secondsLeft === 0 ? "Finish Session" : "Start Focus";
    }

    function tick() {
      secondsLeft -= 1;

      if (secondsLeft <= 0) {
        secondsLeft = 0;
        clearInterval(timerId);
        running = false;
        focusButton.classList.add("done");
        status.textContent = "Focus session complete. Nice work.";
        updateButtonState();
        buttonLabel.textContent = "Start Focus";
        return;
      }

      status.textContent = `Focusing... ${formatTime(secondsLeft)} remaining`;
    }

    focusButton.addEventListener("click", () => {
      if (secondsLeft === 0) {
        secondsLeft = 25 * 60;
        focusButton.classList.remove("done");
        status.textContent = "Ready for another 25-minute focus session.";
        updateButtonState();
        return;
      }

      running = !running;
      focusButton.classList.remove("done");

      if (running) {
        status.textContent = `Focusing... ${formatTime(secondsLeft)} remaining`;
        timerId = setInterval(tick, 1000);
      } else {
        clearInterval(timerId);
        status.textContent = "Session paused.";
      }

      updateButtonState();
    });

    animateScore();
