<div class="card">
  <div class="head">
    <span class="label">Focus Score</span>
    <span class="date" id="today"></span>
  </div>

  <div class="score-row">
    <div class="score" id="score">0</div>
    <span class="delta">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
        <path d="M12 4l7 8h-4.2v8h-5.6v-8H5z"/>
      </svg>
      +6
    </span>
  </div>

  <div class="spark">
    <svg id="spark" role="img" aria-label="Focus score over the last seven days"></svg>
    <div class="days" aria-hidden="true">
      <span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span>
    </div>
  </div>

  <button class="btn" id="btn" type="button">
    <span class="ico" id="ico"></span>
    <span class="lbl" id="lbl">Start Focus</span>
  </button>

  <div class="progress-row" id="progressRow">
    <div class="bar"><i id="barFill"></i></div>
    <span class="time" id="time" aria-live="polite">25:00</span>
  </div>
</div>

<script>
(function () {
  "use strict";

  /* ============ data ============ */
  const DATA = [58, 66, 61, 74, 69, 83, 87];
  const SCORE = DATA[DATA.length - 1];

  /* ============ date ============ */
  document.getElementById("today").textContent = new Date().toLocaleDateString(undefined, {
    weekday: "short", month: "short", day: "numeric"
  });

  /* ============ score count-up ============ */
  const scoreEl = document.getElementById("score");
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (reduce) {
    scoreEl.textContent = SCORE;
  } else {
    const t0 = performance.now();
    const DUR = 900;
    (function step(t) {
      const p = Math.min(1, (t - t0) / DUR);
      const e = 1 - Math.pow(1 - p, 3);
      scoreEl.textContent = Math.round(SCORE * e);
      if (p < 1) requestAnimationFrame(step);
    })(t0);
  }

  /* ============ sparkline ============ */
  const svg = document.getElementById("spark");

  function smoothPath(pts) {
    let d = "M " + pts[0].x + " " + pts[0].y;
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i], b = pts[i + 1];
      const cx = (a.x + b.x) / 2;
      d += " C " + cx + " " + a.y + ", " + cx + " " + b.y + ", " + b.x + " " + b.y;
    }
    return d;
  }

  function drawSpark() {
    const w = svg.clientWidth || 320;
    const h = svg.clientHeight || 72;
    svg.setAttribute("viewBox", "0 0 " + w + " " + h);

    const padX = 10, padTop = 12, padBot = 14;
    const min = Math.min.apply(null, DATA);
    const max = Math.max.apply(null, DATA);
    const range = (max - min) || 1;

    const pts = DATA.map(function (v, i) {
      return {
        x: +(padX + i * (w - padX * 2) / (DATA.length - 1)).toFixed(2),
        y: +(padTop + (1 - (v - min) / range) * (h - padTop - padBot)).toFixed(2)
      };
    });

    const line = smoothPath(pts);
    const last = pts[pts.length - 1];
    const area = line +
      " L " + last.x + " " + h +
      " L " + pts[0].x + " " + h + " Z";

    const grid = [0.25, 0.5, 0.75].map(function (f) {
      const y = (padTop + (h - padTop - padBot) * f).toFixed(1);
      return '<line x1="' + padX + '" x2="' + (w - padX) + '" y1="' + y + '" y2="' + y +
             '" stroke="rgba(255,255,255,.05)" stroke-width="1"/>';
    }).join("");

    svg.innerHTML =
      '<defs>' +
        '<linearGradient id="sg" x1="0" y1="0" x2="1" y2="0">' +
          '<stop offset="0%" stop-color="#7c5cff"/>' +
          '<stop offset="100%" stop-color="#22d3ee"/>' +
        '</linearGradient>' +
        '<linearGradient id="ag" x1="0" y1="0" x2="0" y2="1">' +
          '<stop offset="0%" stop-color="rgba(124,92,255,.38)"/>' +
          '<stop offset="100%" stop-color="rgba(124,92,255,0)"/>' +
        '</linearGradient>' +
      '</defs>' +
      grid +
      '<path d="' + area + '" fill="url(#ag)"/>' +
      '<path d="' + line + '" fill="none" stroke="url(#sg)" stroke-width="2.5" ' +
        'stroke-linecap="round" stroke-linejoin="round"/>' +
      '<circle class="halo" cx="' + last.x + '" cy="' + last.y + '" r="9" fill="rgba(34,211,238,.28)"/>' +
      '<circle cx="' + last.x + '" cy="' + last.y + '" r="4" fill="#22d3ee" ' +
        'stroke="#0f131a" stroke-width="2"/>';
  }

  drawSpark();
  if (window.ResizeObserver) {
    new ResizeObserver(drawSpark).observe(svg);
  } else {
    window.addEventListener("resize", drawSpark);
  }

  /* ============ focus timer ============ */
  const SESSION = 25 * 60; // seconds

  const btn = document.getElementById("btn");
  const ico = document.getElementById("ico");
  const lbl = document.getElementById("lbl");
  const row = document.getElementById("progressRow");
  const fill = document.getElementById("barFill");
  const timeEl = document.getElementById("time");

  const ICON_PLAY =
    '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' +
    '<path d="M8 5.4v13.2L19 12z"/></svg>';
  const ICON_PAUSE =
    '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' +
    '<rect x="7" y="5" width="3.6" height="14" rx="1.2"/>' +
    '<rect x="13.4" y="5" width="3.6" height="14" rx="1.2"/></svg>';

  let remaining = SESSION;
  let running = false;
  let ticker = null;
  let finished = false;

  function fmt(s) {
    const m = Math.floor(s / 60);
    const ss = s % 60;
    return String(m).padStart(2, "0") + ":" + String(ss).padStart(2, "0");
  }

  function render() {
    const elapsed = SESSION - remaining;
    const pct = Math.max(0, Math.min(100, (elapsed / SESSION) * 100));

    fill.style.width = pct + "%";
    timeEl.textContent = finished ? "Done" : fmt(remaining);

    if (running) {
      ico.innerHTML = ICON_PAUSE;
      lbl.textContent = "Pause";
      btn.classList.add("running");
      row.classList.add("show");
    } else {
      ico.innerHTML = ICON_PLAY;
      btn.classList.remove("running");
      if (finished) {
        lbl.textContent = "Start Focus";
        row.classList.add("show");
      } else if (remaining < SESSION) {
        lbl.textContent = "Resume";
        row.classList.add("show");
      } else {
        lbl.textContent = "Start Focus";
        row.classList.remove("show");
      }
    }
  }

  function stopTicker() {
    if (ticker) {
      clearInterval(ticker);
      ticker = null;
    }
  }

  function run() {
    running = true;
    stopTicker();
    ticker = setInterval(function () {
      remaining -= 1;
      if (remaining <= 0) {
        remaining = 0;
        finished = true;
        running = false;
        stopTicker();
      }
      render();
    }, 1000);
    render();
  }

  btn.addEventListener("click", function () {
    if (running) {
      running = false;
      stopTicker();
      render();
      return;
    }
    if (finished || remaining <= 0) {
      remaining = SESSION;
      finished = false;
    }
    run();
  });

  render();
})();
</script>
</body>
</html>
