        <title id="chart-title">Focus scores over the last seven days</title>
        <desc id="chart-desc">Scores: 48, 62, 55, 72, 67, 74, and 86. Overall upward trend.</desc>
        <defs>
          <linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#bef279" stop-opacity=".18"/>
            <stop offset="100%" stop-color="#bef279" stop-opacity="0"/>
          </linearGradient>
        </defs>
        <path d="M6 25H330 M6 60H330 M6 95H330"
              stroke="#ffffff08" stroke-dasharray="3 5" fill="none"/>
        <path id="area" fill="url(#chart-fill)"/>
        <path id="line" fill="none" stroke="#bef279" stroke-width="2.5"
              stroke-linecap="round" stroke-linejoin="round"/>
        <circle id="dot-glow" r="9" fill="#bef279" opacity=".1"/>
        <circle id="dot" r="4" fill="#bef279" stroke="#1a1c22" stroke-width="2"/>
      </svg>
      <div class="days" id="days" aria-hidden="true"></div>
    </section>

    <button id="focus-button" type="button">
      <svg id="play-icon" width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
        <path d="M5 3.5L12 8L5 12.5V3.5Z" fill="currentColor"/>
      </svg>
      <span id="button-label">Start Focus</span>
    </button>

    <div class="timer" id="timer" role="timer" aria-label="Time remaining" hidden>25:00</div>
    <p class="footer" id="status" role="status">25 minutes. One task. Zero distractions.</p>
  </main>

  <script>
    // Demo focus scores, ordered from six days ago to today.
    const scores = [48, 62, 55, 72, 67, 74, 86];
    const points = scores.map((score, index) => ({
      x: 6 + index * 54,
      y: 96 - score * 0.88
    }));
    const path = points.map((point, index) =>
      `${index ? "L" : "M"} ${point.x} ${point.y}`
    ).join(" ");

    document.getElementById("line").setAttribute("d", path);
    document.getElementById("area").setAttribute("d", `${path} L330 104 L6 104 Z`);

    const lastPoint = points[points.length - 1];
    ["dot", "dot-glow"].forEach(id => {
      const dot = document.getElementById(id);
      dot.setAttribute("cx", lastPoint.x);
      dot.setAttribute("cy", lastPoint.y);
    });

    const days = document.getElementById("days");
    for (let offset = 6; offset >= 0; offset--) {
      const date = new Date();
      date.setDate(date.getDate() - offset);
      const label = document.createElement("span");
      label.textContent = date.toLocaleDateString("en-US", { weekday: "short" });
      days.appendChild(label);
    }

    const button = document.getElementById("focus-button");
    const buttonLabel = document.getElementById("button-label");
    const playIcon = document.getElementById("play-icon");
    const timer = document.getElementById("timer");
    const status = document.getElementById("status");

    let interval = null;
    let endTime = 0;

    function stopSession(completed) {
      clearInterval(interval);
      interval = null;
      timer.hidden = true;
      playIcon.hidden = false;
      playIcon.style.display = "";
      buttonLabel.textContent = "Start Focus";
      status.textContent = completed
        ? "Session complete. Nice work — take a short break."
        : "Session ended. Start again when you're ready.";
      document.title = "Daily Focus";
    }

    function updateTimer() {
      const remaining = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
      const minutes = String(Math.floor(remaining / 60)).padStart(2, "0");
      const seconds = String(remaining % 60).padStart(2, "0");
      timer.textContent = `${minutes}:${seconds}`;
      document.title = `${minutes}:${seconds} · Focus`;
      if (remaining === 0) stopSession(true);
    }

    button.addEventListener("click", () => {
      if (interval !== null) {
        stopSession(false);
        return;
      }

      endTime = Date.now() + 25 * 60 * 1000;
      timer.hidden = false;
      playIcon.style.display = "none";
      buttonLabel.textContent = "End Session";
      status.textContent = "Focus time. Give one thing your full attention.";
      interval = setInterval(updateTimer, 250);
      updateTimer();
    });
  </script>
</body>
