</article>

<script>
(() => {
  // ---------- Data ----------
  const state = {
    score: 78,
    weekly: [62, 70, 58, 74, 81, 69, 78], // last value = today
    minutes: 184,
    sessions: 6,
    streak: 4
  };

  const SESSION_SECONDS = 25 * 60;
  const RING_R = 52;
  const RING_C = 2 * Math.PI * RING_R;

  const $ = id => document.getElementById(id);

  // ---------- Date / labels ----------
  const today = new Date();
  $('dateLabel').textContent = today.toLocaleDateString(undefined, {
    weekday: 'long', month: 'short', day: 'numeric'
  });

  const dayNames = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    dayNames.push(d.toLocaleDateString(undefined, { weekday: 'short' }));
  }
  $('days').innerHTML = dayNames
    .map((d, i) => `<span class="${i === 6 ? 'today' : ''}">${i === 6 ? 'Today' : d}</span>`)
    .join('');

  // ---------- Ring ----------
  const ring = $('ring');
  ring.style.strokeDasharray = RING_C;
  ring.style.strokeDashoffset = RING_C;

  let displayedScore = 0;
  function renderScore(target) {
    requestAnimationFrame(() => {
      ring.style.strokeDashoffset = RING_C * (1 - target / 100);
    });

    const start = displayedScore;
    const t0 = performance.now();
    const dur = 1100;
    function tick(now) {
      const p = Math.min(1, (now - t0) / dur);
      const eased = 1 - Math.pow(1 - p, 3);
      displayedScore = Math.round(start + (target - start) * eased);
      $('scoreValue').textContent = displayedScore;
      if (p < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);

    const tier = $('tier');
    let label, color;
    if (target >= 75) { label = 'Deep focus'; color = 'var(--good)'; }
    else if (target >= 50) { label = 'Steady'; color = 'var(--warn)'; }
    else { label = 'Scattered'; color = 'var(--bad)'; }
    tier.querySelector('span:last-child').textContent = label;
    tier.querySelector('.dot').style.background = color;
    tier.querySelector('.dot').style.color = color;
  }

  // ---------- Stats ----------
  function renderStats() {
    const h = Math.floor(state.minutes / 60);
    const m = state.minutes % 60;
    $('statTime').textContent = `${h}h ${m}m`;
    $('statSessions').textContent = state.sessions;
    $('statStreak').textContent = `${state.streak} day${state.streak === 1 ? '' : 's'}`;

    const w = state.weekly;
    const avg = Math.round(w.reduce((a, b) => a + b, 0) / w.length);
    $('weekAvg').textContent = `avg ${avg}`;

    const prev = w.slice(0, 6).reduce((a, b) => a + b, 0) / 6;
    const delta = Math.round(((w[6] - prev) / prev) * 100);
    const badge = $('deltaBadge');
    badge.classList.toggle('down', delta < 0);
    badge.textContent = `${delta >= 0 ? '▲' : '▼'} ${Math.abs(delta)}% vs avg`;
  }

  // ---------- Sparkline ----------
  const W = 300, H = 70, PAD = 8;
  let points = [];

  function smoothPath(pts) {
    let d = `M${pts[0].x},${pts[0].y}`;
    const t = 0.18;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i - 1] || pts[i];
      const p1 = pts[i];
      const p2 = pts[i + 1];
      const p3 = pts[i + 2] || p2;
      const c1x = p1.x + (p2.x - p0.x) * t;
      const c1y = p1.y + (p2.y - p0.y) * t;
      const c2x = p2.x - (p3.x - p1.x) * t;
      const c2y = p2.y - (p3.y - p1.y) * t;
      d += ` C${c1x},${c1y} ${c2x},${c2y} ${p2.x},${p2.y}`;
    }
    return d;
  }

  function renderSpark(animate = true) {
    const data = state.weekly;
    const min = Math.min(...data) - 6;
    const max = Math.max(...data) + 6;
    const n = data.length;

    points = data.map((v, i) => ({
      x: PAD + i * (W - PAD * 2) / (n - 1),
      y: H - PAD - ((v - min) / (max - min)) * (H - PAD * 2),
      v
    }));

    const line = smoothPath(points);
    const first = points[0], last = points[n - 1];
    $('sparkArea').setAttribute('d', `${line} L${last.x},${H} L${first.x},${H} Z`);

    const path = $('sparkLine');
    path.setAttribute('d', line);

    if (animate) {
      const len = path.getTotalLength();
      path.style.transition = 'none';
      path.style.strokeDasharray = len;
      path.style.strokeDashoffset = len;
      path.getBoundingClientRect();
      path.style.transition = '';
      requestAnimationFrame(() => { path.style.strokeDashoffset = 0; });
    }

    // Dots are drawn as HTML-free SVG circles; using an overlay to avoid stretch
    const dots = $('dots');
    dots.innerHTML = '';
    points.forEach((p, i) => {
      const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      c.setAttribute('cx', p.x);
      c.setAttribute('cy', p.y);
      c.setAttribute('r', i === n - 1 ? 3.5 : 0);
      c.setAttribute('fill', i === n - 1 ? '#22d3ee' : '#7c5cff');
      c.setAttribute('stroke', '#12151d');
      c.setAttribute('stroke-width', '2');
      c.style.transition = 'r .15s';
      dots.appendChild(c);
    });
  }

  // Hover interaction
  const spark = $('spark');
  const tooltip = $('tooltip');
  const hoverLine = $('hoverLine');

  spark.addEventListener('mousemove', e => {
    const rect = spark.getBoundingClientRect();
    const xRatio = (e.clientX - rect.left) / rect.width;
    const vx = xRatio * W;
    let idx = 0, best = Infinity;
    points.forEach((p, i) => {
      const d = Math.abs(p.x - vx);
      if (d < best) { best = d; idx = i; }
    });
    const p = points[idx];
    hoverLine.setAttribute('x1', p.x);
    hoverLine.setAttribute('x2', p.x);
    hoverLine.setAttribute('opacity', 1);

    [...$('dots').children].forEach((c, i) => {
      c.setAttribute('r', i === idx ? 4 : (i === points.length - 1 ? 3.5 : 0));
    });

    tooltip.textContent = `${idx === 6 ? 'Today' : dayNames[idx]} · ${p.v}`;
    tooltip.style.left = `${(p.x / W) * 100}%`;
    tooltip.classList.add('show');
  });

  spark.addEventListener('mouseleave', () => {
    hoverLine.setAttribute('opacity', 0);
    tooltip.classList.remove('show');
    [...$('dots').children].forEach((c, i) => {
      c.setAttribute('r', i === points.length - 1 ? 3.5 : 0);
    });
  });

  // ---------- Focus session ----------
  const startBtn = $('startBtn');
  const stopBtn = $('stopBtn');
  const sessionEl = $('session');
  const sessionBar = $('sessionBar');
  const sessionPct = $('sessionPct');
  const sessionLabel = $('sessionLabel');

  const playIcon = `<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4.5v15a1 1 0 0 0 1.5.86l12.5-7.5a1 1 0 0 0 0-1.72L8.5 3.64A1 1 0 0 0 7 4.5z"/></svg>`;

  let timer = null;
  let status = 'idle';     // idle | running | paused
  let elapsed = 0;         // seconds accumulated before current run
  let runStart = 0;        // timestamp of current run

  const fmt = s => {
    const m = Math.floor(s / 60).toString().padStart(2, '0');
    const sec = Math.floor(s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  };

  function currentElapsed() {
    return status === 'running' ? elapsed + (Date.now() - runStart) / 1000 : elapsed;
  }

  function updateSessionUI() {
    const e = Math.min(SESSION_SECONDS, currentElapsed());
    const remaining = SESSION_SECONDS - e;
    const pct = (e / SESSION_SECONDS) * 100;
    sessionBar.style.width = `${pct}%`;
    sessionPct.textContent = `${Math.floor(pct)}%`;

    if (status === 'running') {
      startBtn.innerHTML = `<span class="pulse"></span><span>Pause · ${fmt(remaining)}</span>`;
      sessionLabel.textContent = 'In focus — stay with it';
    } else if (status === 'paused') {
      startBtn.innerHTML = `<span class="pulse"></span><span>Resume · ${fmt(remaining)}</span>`;
      sessionLabel.textContent = 'Paused';
    }

    if (e >= SESSION_SECONDS) finishSession(true);
  }

  function start() {
    status = 'running';
    runStart = Date.now();
    startBtn.classList.add('running');
    startBtn.classList.remove('paused');
    stopBtn.classList.add('show');
    sessionEl.classList.add('active');
    clearInterval(timer);
    timer = setInterval(updateSessionUI, 250);
    updateSessionUI();
  }

  function pause() {
    elapsed = currentElapsed();
    status = 'paused';
    startBtn.classList.add('paused');
    clearInterval(timer);
    updateSessionUI();
  }

  function finishSession(completed) {
    const secs = Math.min(SESSION_SECONDS, currentElapsed());
    clearInterval(timer);
    status = 'idle';
    elapsed = 0;

    const mins = Math.floor(secs / 60);
    if (mins > 0) {
      state.minutes += mins;
      if (mins >= 5) state.sessions += 1;
      const gain = completed ? 6 : Math.max(1, Math.round(mins / 5));
      state.score = Math.min(100, state.score + gain);
      state.weekly[6] = state.score;
      renderScore(state.score);
      renderStats();
      renderSpark(false);
      showToast(completed
        ? `Session complete · +${gain} score`
        : `Logged ${mins} min · +${gain} score`);
    } else {
      showToast('Session too short to count');
    }

    startBtn.classList.remove('running', 'paused');
    startBtn.innerHTML = `${playIcon}<span>Start Focus</span>`;
    stopBtn.classList.remove('show');
    sessionEl.classList.remove('active');
    sessionBar.style.width = '0%';
  }

  let toastTimer;
  function showToast(msg) {
    const t = $('toast');
    t.textContent = msg;
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.remove('show'), 2400);
  }

  startBtn.addEventListener('click', () => {
    if (status === 'idle' || status === 'paused') start();
    else pause();
  });
  stopBtn.addEventListener('click', () => finishSession(false));

  // ---------- Init ----------
  renderStats();
  renderSpark(true);
  setTimeout(() => renderScore(state.score), 150);
})();
</script>
</body>
</html>
```

**What's included:**

- **Focus score ring:** an animated SVG gauge with a gradient stroke and a count-up number. It shows a tier label (Deep focus, Steady or Scattered) that changes color by score.
- **Stats:** focus time, session count and streak, plus a badge showing today versus the 6-day average.
- **Weekly sparkline:** a smoothed line and gradient area, drawn in an animation on load. Hovering shows a crosshair and a tooltip with the day and score. Day labels are generated from the current date.
- **Start Focus button:** starts a 25-minute Pomodoro-style session with a live countdown and a progress bar. Clicking again pauses and resumes, and the square button ends the session early.
- **Session credit:** finishing or ending a session adds the minutes and raises the score, then updates the ring, stats and today's point on the sparkline. A toast confirms the change.
- **Details:** respects `prefers-reduced-motion`, has keyboard focus styles, uses no external assets and works in any modern browser.

To test the timer without waiting 25 minutes, temporarily change `SESSION_SECONDS` to something like `30`.

