<body>

<div class="card" role="region" aria-label="Daily focus score card">
  <div class="card__head">
    <span class="card__title">Daily Focus</span>
    <span class="badge" id="statusBadge">On track</span>
  </div>

  <div class="score">
    <div class="score__value" id="scoreValue">0</div>
    <div class="score__meta">
      <div class="score__delta" id="scoreDelta">+0 vs yesterday</div>
      <div class="score__label">Focus score · goal 85</div>
    </div>
  </div>

  <div class="score__bar"><div class="score__fill" id="scoreFill"></div></div>

  <div class="trend">
    <div class="trend__head">
      <span class="trend__title">Weekly trend</span>
      <span class="trend__range" id="trendRange"></span>
    </div>

    <div class="spark">
      <svg viewBox="0 0 340 72" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          <linearGradient id="grad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#7c8cf8"/>
            <stop offset="100%" stop-color="#4fd1c5"/>
          </linearGradient>
          <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#4fd1c5" stop-opacity=".28"/>
            <stop offset="100%" stop-color="#4fd1c5" stop-opacity="0"/>
          </linearGradient>
        </defs>
        <path class="area" id="sparkArea" d=""></path>
        <path class="line" id="sparkLine" d=""></path>
        <circle class="dot" id="sparkDot" r="4.5" cx="0" cy="0"></circle>
      </svg>
    </div>

    <div class="days" id="dayLabels"></div>
  </div>

  <div class="actions">
    <button class="btn btn--primary" id="focusBtn">Start Focus</button>
    <button class="btn btn--ghost" id="resetBtn">Reset</button>
  </div>

  <div class="timer" id="timer">
    <span class="pulse"></span>
    Session running · <strong id="clock">25:00</strong>
  </div>
</div>

<div class="toast" id="toast"></div>

<script>
(function () {
  "use strict";

  // ---- Data -------------------------------------------------------------
  var week = [
    { day: "Mon", score: 62 },
    { day: "Tue", score: 71 },
    { day: "Wed", score: 58 },
    { day: "Thu", score: 77 },
    { day: "Fri", score: 69 },
    { day: "Sat", score: 81 },
    { day: "Sun", score: 84 }
  ];

  var today = week[week.length - 1].score;
  var yesterday = week[week.length - 2].score;
  var goal = 85;

  // ---- Score animation --------------------------------------------------
  var scoreEl = document.getElementById("scoreValue");
  var fillEl = document.getElementById("scoreFill");
  var deltaEl = document.getElementById("scoreDelta");
  var badgeEl = document.getElementById("statusBadge");

  function animateScore(target, duration) {
    var start = performance.now();
    function step(now) {
      var t = Math.min((now - start) / duration, 1);
      var eased = 1 - Math.pow(1 - t, 3);
      scoreEl.textContent = Math.round(target * eased);
      if (t < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  animateScore(today, 1200);
  fillEl.style.width = today + "%";

  var diff = today - yesterday;
  deltaEl.textContent = (diff >= 0 ? "+" : "") + diff + " vs yesterday";
  if (diff < 0) deltaEl.classList.add("down");

  if (today >= goal) {
    badgeEl.textContent = "Goal hit";
  } else if (today >= goal - 10) {
    badgeEl.textContent = "On track";
  } else {
    badgeEl.textContent = "Behind";
  }

  // ---- Sparkline --------------------------------------------------------
  var W = 340, H = 72, PAD = 8;
  var values = week.map(function (d) { return d.score; });
  var min = Math.min.apply(null, values);
  var max = Math.max.apply(null, values);
  var span = (max - min) || 1;

  function x(i) { return PAD + (i * (W - PAD * 2)) / (values.length - 1); }
  function y(v) { return H - PAD - ((v - min) / span) * (H - PAD * 2); }

  // Smooth path via Catmull-Rom -> cubic bezier
  function smoothPath(pts) {
    if (pts.length < 2) return "";
    var d = "M" + pts[0][0].toFixed(1) + "," + pts[0][1].toFixed(1);
    for (var i = 0; i < pts.length - 1; i++) {
      var p0 = pts[i - 1] || pts[i];
      var p1 = pts[i];
      var p2 = pts[i + 1];
      var p3 = pts[i + 2] || p2;
      var c1x = p1[0] + (p2[0] - p0[0]) / 6;
      var c1y = p1[1] + (p2[1] - p0[1]) / 6;
      var c2x = p2[0] - (p3[0] - p1[0]) / 6;
      var c2y = p2[1] - (p3[1] - p1[1]) / 6;
      d += " C" + c1x.toFixed(1) + "," + c1y.toFixed(1) +
           " " + c2x.toFixed(1) + "," + c2y.toFixed(1) +
           " " + p2[0].toFixed(1) + "," + p2[1].toFixed(1);
    }
    return d;
  }

  var pts = values.map(function (v, i) { return [x(i), y(v)]; });
  var lineD = smoothPath(pts);
  var areaD = lineD + " L" + x(values.length - 1).toFixed(1) + "," + (H - PAD) +
              " L" + x(0).toFixed(1) + "," + (H - PAD) + " Z";

  var lineEl = document.getElementById("sparkLine");
  var areaEl = document.getElementById("sparkArea");
  var dotEl = document.getElementById("sparkDot");

  lineEl.setAttribute("d", lineD);
  areaEl.setAttribute("d", areaD);
  dotEl.setAttribute("cx", pts[pts.length - 1][0]);
  dotEl.setAttribute("cy", pts[pts.length - 1][1]);

  var len = lineEl.getTotalLength();
  lineEl.style.setProperty("--len", len);

  var labelsEl = document.getElementById("dayLabels");
  week.forEach(function (d) {
    var s = document.createElement("span");
    s.textContent = d.day;
    labelsEl.appendChild(s);
  });

  document.getElementById("trendRange").textContent =
    min + "–" + max + " · last 7 days";

  // ---- Focus timer ------------------------------------------------------
  var btn = document.getElementById("focusBtn");
  var resetBtn = document.getElementById("resetBtn");
  var timerBox = document.getElementById("timer");
  var clock = document.getElementById("clock");
  var toast = document.getElementById("toast");

  var SESSION = 25 * 60;
  var remaining = SESSION;
  var interval = null;
  var running = false;

  function render() {
    var m = Math.floor(remaining / 60);
    var s = remaining % 60;
    clock.textContent =
      (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s;
  }

  function showToast(msg) {
    toast.textContent = msg;
    toast.classList.add("show");
    clearTimeout(showToast._t);
    showToast._t = setTimeout(function () {
      toast.classList.remove("show");
    }, 2600);
  }

  function tick() {
    remaining--;
    render();
    if (remaining <= 0) {
      stop();
      remaining = SESSION;
      render();
      showToast("Focus session complete — nice work!");
    }
  }

  function start() {
    running = true;
    btn.textContent = "End Session";
    btn.classList.add("running");
    timerBox.classList.add("visible");
    interval = setInterval(tick, 1000);
    showToast("25-minute focus session started.");
  }

  function stop() {
    running = false;
    clearInterval(interval);
    interval = null;
    btn.textContent = "Start Focus";
    btn.classList.remove("running");
    timerBox.classList.remove("visible");
  }

  btn.addEventListener("click", function () {
    if (running) {
      stop();
      showToast("Session paused at " + clock.textContent + ".");
    } else {
      start();
    }
  });

  resetBtn.addEventListener("click", function () {
    stop();
    remaining = SESSION;
    render();
    showToast("Timer reset.");
  });

  render();
})();
</script>
</body>
</html>
```



**What's included:**

- **Focus score** — animated count-up to 84, gradient progress bar toward the goal of 85, delta vs. yesterday, and a status badge (Goal hit / On track / Behind)
- **Weekly sparkline** — hand-rolled SVG with a Catmull-Rom smoothed curve, gradient stroke, fade-in area fill, animated draw-on effect, day labels, and a highlighted endpoint dot
- **Start Focus button** — toggles a working 25-minute countdown timer with a pulsing indicator; a Reset button restores it, and toast notifications confirm state changes
- **Dark theme** — layered radial background glows, subtle card gradient with inner highlight, fully responsive (max 400px, centers on any screen)

No external assets, fonts, or libraries — paste the file into any `.html` and open it in a browser.

