<script>
(() => {
  const $ = id => document.getElementById(id);
  const CIRC = 2 * Math.PI * 52;
  const SVG_W = 300, SVG_H = 72, PAD = 8;

  const ICON_PLAY  = '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5.14v13.72a1 1 0 0 0 1.52.85l10.6-6.86a1 1 0 0 0 0-1.7L9.52 4.29A1 1 0 0 0 8 5.14z"/></svg>';
  const ICON_PAUSE = '<svg viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>';

  const state = {
    score: 84,
    history: [62, 70, 58, 75, 81, 77, 84], // last value = today
    focusMin: 142,
    sessions: 4,
    streak: 6,
    durations: [15, 25, 50],
    duration: 25,
    remaining: 0,
    running: false,
    inSession: false,
    endAt: 0,
    timer: null,
    sparkDrawn: false
  };

  const card = $('card');
  const ringBar = $('ringBar');
  ringBar.style.strokeDasharray = CIRC;
  ringBar.style.strokeDashoffset = CIRC;

  /* ---------- Helpers ---------- */
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const fmtMin = m => { const h = Math.floor(m / 60), r = m % 60; return h ? `${h}h ${r}m` : `${r}m`; };
  const fmtClock = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
  const setRing = frac => { ringBar.style.strokeDashoffset = CIRC * (1 - clamp(frac, 0, 1)); };

  function animateNumber(el, from, to, dur = 1000) {
    const t0 = performance.now();
    const step = t => {
      if (state.inSession) return;
      const p = Math.min(1, (t - t0) / dur);
      const e = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(from + (to - from) * e);
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  function statusFor(s) {
    if (s >= 90) return ['Locked in', 'Top-tier focus. Protect this momentum.'];
    if (s >= 75) return ['Deep work zone', 'Strong day. One more session could push you over 90.'];
    if (s >= 55) return ['Getting there', 'A focused block now will lift your score.'];
    return ['Warming up', 'Start a short session to build momentum.'];
  }

  /* ---------- Header / Days ---------- */
  const today = new Date();
  $('date').textContent = today.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });

  const dayNames = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    dayNames.push(i === 0 ? 'Today' : d.toLocaleDateString(undefined, { weekday: 'short' }));
  }
  $('days').innerHTML = dayNames.map(n => `<span>${n}</span>`).join('');

  /* ---------- Score ---------- */
  function renderScore(prevScore = 0) {
    const s = state.score;
    const yesterday = state.history[state.history.length - 2];
    const diff = s - yesterday;
    const delta = $('delta');
    delta.className = 'delta ' + (diff > 0 ? 'up' : diff < 0 ? 'down' : 'flat');
    delta.textContent = `${diff > 0 ? '▲' : diff < 0 ? '▼' : '•'} ${Math.abs(diff)} vs yesterday`;

    const [title, sub] = statusFor(s);
    $('status').textContent = title;
    $('sub').textContent = sub;

    $('focusTime').textContent = fmtMin(state.focusMin);
    $('sessions').textContent = state.sessions;
    $('streak').textContent = state.streak + 'd';

    if (!state.inSession) {
      setRing(s / 100);
      animateNumber($('ringValue'), prevScore, s);
    }
  }

  /* ---------- Sparkline ---------- */
  let points = [];

  function smoothPath(p) {
    let d = `M${p[0][0]},${p[0][1]}`;
    for (let i = 0; i < p.length - 1; i++) {
      const p0 = p[i - 1] || p[i], p1 = p[i], p2 = p[i + 1], p3 = p[i + 2] || p2;
      const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
      const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
      d += ` C${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${p2[0].toFixed(2)},${p2[1].toFixed(2)}`;
    }
    return d;
  }

  function renderSpark() {
    const data = state.history;
    const min = Math.min(...data) - 6, max = Math.max(...data) + 6;
    points = data.map((v, i) => [
      PAD + i * (SVG_W - PAD * 2) / (data.length - 1),
      SVG_H - PAD - ((v - min) / (max - min)) * (SVG_H - PAD * 2)
    ]);

    const line = smoothPath(points);
    const last = points[points.length - 1], first = points[0];
    $('sparkArea').setAttribute('d', `${line} L${last[0]},${SVG_H} L${first[0]},${SVG_H} Z`);

    const lineEl = $('sparkLine');
    lineEl.setAttribute('d', line);

    $('sparkDots').innerHTML = points.map((p, i) =>
      `<circle class="spark-dot${i === points.length - 1 ? ' today' : ''}" cx="${p[0]}" cy="${p[1]}" r="${i === points.length - 1 ? 4 : 2.5}"/>`
    ).join('');

    if (!state.sparkDrawn) {
      const len = lineEl.getTotalLength();
      lineEl.style.strokeDasharray = len;
      lineEl.style.strokeDashoffset = len;
      lineEl.getBoundingClientRect();
      lineEl.style.transition = 'stroke-dashoffset 1.4s cubic-bezier(.22,1,.36,1)';
      lineEl.style.strokeDashoffset = 0;
      state.sparkDrawn = true;
      setTimeout(() => { lineEl.style.strokeDasharray = 'none'; lineEl.style.transition = ''; }, 1500);
    }

    const avg = Math.round(data.reduce((a, b) => a + b, 0) / data.length);
    const bestIdx = data.indexOf(Math.max(...data));
    $('avg').innerHTML = `Avg <b>${avg}</b> · Best <b>${dayNames[bestIdx]}</b>`;
  }

  // Hover interaction
  const wrap = $('sparkWrap'), svg = $('spark'), tip = $('tip');
  function onMove(e) {
    const rect = svg.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const x = ((clientX - rect.left) / rect.width) * SVG_W;
    let idx = 0, best = Infinity;
    points.forEach((p, i) => { const d = Math.abs(p[0] - x); if (d < best) { best = d; idx = i; } });
    const [px, py] = points[idx];
    $('hoverLine').setAttribute('x1', px);
    $('hoverLine').setAttribute('x2', px);
    $('hoverDot').setAttribute('cx', px);
    $('hoverDot').setAttribute('cy', py);
    tip.innerHTML = `${dayNames[idx]} · <b>${state.history[idx]}</b>`;
    const scale = rect.width / SVG_W;
    tip.style.left = clamp(px * scale, 36, rect.width - 36) + 'px';
    tip.style.top = (py * scale - 34) + 'px';
    wrap.classList.add('hovering');
  }
  svg.addEventListener('mousemove', onMove);
  svg.addEventListener('touchmove', onMove, { passive: true });
  svg.addEventListener('mouseleave', () => wrap.classList.remove('hovering'));
  svg.addEventListener('touchend', () => setTimeout(() => wrap.classList.remove('hovering'), 1200));

  /* ---------- Durations ---------- */
  function renderDurations() {
    $('durations').innerHTML = state.durations.map(m =>
      `<button class="chip" role="radio" type="button" data-min="${m}" aria-checked="${m === state.duration}" ${state.inSession ? 'disabled' : ''}>${m} min</button>`
    ).join('');
  }
  $('durations').addEventListener('click', e => {
    const b = e.target.closest('.chip');
    if (!b || state.inSession) return;
    state.duration = +b.dataset.min;
    renderDurations();
  });

  /* ---------- Session / Timer ---------- */
  const startBtn = $('startBtn'), endBtn = $('endBtn');

  function updateButtons() {
    if (!state.inSession) {
      startBtn.innerHTML = `${ICON_PLAY}<span>Start Focus</span>`;
      startBtn.classList.remove('running');
      startBtn.setAttribute('aria-pressed', 'false');
      endBtn.hidden = true;
    } else if (state.running) {
      startBtn.innerHTML = `${ICON_PAUSE}<span>Pause</span>`;
      startBtn.classList.add('running');
      startBtn.setAttribute('aria-pressed', 'true');
      endBtn.hidden = false;
    } else {
      startBtn.innerHTML = `${ICON_PLAY}<span>Resume</span>`;
      startBtn.classList.remove('running');
      startBtn.setAttribute('aria-pressed', 'false');
      endBtn.hidden = false;
    }
    renderDurations();
  }

  function tick() {
    const rem = Math.max(0, (state.endAt - Date.now()) / 1000);
    state.remaining = rem;
    const clock = fmtClock(Math.ceil(rem));
    $('ringValue').textContent = clock;
    document.title = `${clock} · Focus`;
    setRing(1 - rem / (state.duration * 60));
    if (rem <= 0) complete();
  }

  function start() {
    if (!state.inSession) {
      state.inSession = true;
      state.remaining = state.duration * 60;
      card.classList.add('in-session');
      $('ringLabel').textContent = 'Remaining';
      setRing(0);
    }
    state.running = true;
    state.endAt = Date.now() + state.remaining * 1000;
    clearInterval(state.timer);
    state.timer = setInterval(tick, 250);
    tick();
    updateButtons();
  }

  function pause() {
    state.running = false;
    clearInterval(state.timer);
    $('ringLabel').textContent = 'Paused';
    updateButtons();
  }

  function stopSession() {
    clearInterval(state.timer);
    state.running = false;
    state.inSession = false;
    card.classList.remove('in-session');
    $('ringLabel').textContent = 'Focus score';
    document.title = 'Focus Dashboard';
    updateButtons();
  }

  function endEarly() {
    const elapsedMin = Math.floor((state.duration * 60 - state.remaining) / 60);
    state.focusMin += elapsedMin;
    stopSession();
    renderScore(state.score);
    toast(elapsedMin > 0 ? `Session ended · ${elapsedMin}m logged` : 'Session cancelled', elapsedMin > 0);
  }

  function complete() {
    const prev = state.score;
    const gain = Math.max(1, Math.round(state.duration / 8));
    state.score = Math.min(100, state.score + gain);
    state.history[state.history.length - 1] = state.score;
    state.sessions += 1;
    state.focusMin += state.duration;
    stopSession();
    renderSpark();
    renderScore(prev);
    toast(`Session complete · +${state.score - prev} focus`, true);
  }

  startBtn.addEventListener('click', () => {
    if (state.running) {
      pause();
    } else {
      start();
      $('ringLabel').textContent = 'Remaining';
    }
  });
  endBtn.addEventListener('click', endEarly);

  /* ---------- Toast ---------- */
  let toastTimer;
  function toast(msg, positive = true) {
    const t = $('toast');
    t.textContent = msg;
    t.style.color = positive ? 'var(--good)' : 'var(--muted)';
    t.style.borderColor = positive ? 'rgba(52,211,153,.35)' : 'var(--border)';
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => t.classList.remove('show'), 2600);
  }

  /* ---------- Init ---------- */
  updateButtons();
  renderSpark();
  requestAnimationFrame(() => renderScore(0));
})();
</script>
</body>
</html>
```

**What's included:**

- **Focus score ring**: an animated gradient SVG ring with a count-up number, a delta vs. yesterday badge, and a status message based on score tier.
- **Stat tiles**: total focused time, sessions completed, and current streak.
- **Weekly sparkline**: a smooth Catmull-Rom curve with a gradient fill and a draw-in animation. Hover or touch to see per-day values in a tooltip. It also shows the 7-day average and your best day.
- **Start Focus button**: you pick 15, 25, or 50 minutes. The ring switches into countdown mode with a cyan gradient, the tab title shows the live timer, and you can pause, resume, or end early. Finishing a session raises today's score, updates the sparkline, and shows a toast.
- **No external dependencies**: it uses system fonts, and all icons are inline SVG. It respects `prefers-reduced-motion` and includes basic ARIA labels.

To plug in real data, replace the values in the `state` object (`score`, `history`, `focusMin`, `sessions`, `streak`) with values from your backend or localStorage.

