            <stop offset="0%" stop-color="#7c8cff"/>
            <stop offset="100%" stop-color="#4fd1c5"/>
          </linearGradient>
        </defs>
        <circle class="track" cx="64" cy="64" r="54" fill="none" stroke-width="10"/>
        <circle class="value" id="ring-value" cx="64" cy="64" r="54" fill="none" stroke-width="10"/>
      </svg>
      <div class="center">
        <div class="score" id="score">0</div>
        <div class="score-label">of 100</div>
      </div>
    </div>

    <div class="meta">
      <div class="stat">
        <div class="k">vs. yesterday</div>
        <div class="v"><span class="delta" id="delta"></span></div>
      </div>
      <div class="stat">
        <div class="k">Focus time</div>
        <div class="v" id="focus-time">0h 0m</div>
      </div>
      <div class="stat">
        <div class="k">Sessions</div>
        <div class="v" id="sessions">0</div>
      </div>
    </div>
  </div>

  <div class="trend">
    <div class="trend-head">
      <span>Weekly trend</span>
      <span>Avg <strong id="avg">–</strong></span>
    </div>
    <div class="spark-wrap" id="spark-wrap">
      <svg class="spark" id="spark" viewBox="0 0 300 84" preserveAspectRatio="none" aria-label="Weekly focus score sparkline"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
    <div class="days" id="days"></div>
  </div>

  <button class="btn" id="start-btn" type="button" aria-live="polite">
    <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.5v11a.5.5 0 0 0 .77.42l8.5-5.5a.5.5 0 0 0 0-.84l-8.5-5.5A.5.5 0 0 0 4 2.5z"/></svg>
    <span id="btn-label">Start Focus</span>
    <span class="timer" id="btn-timer"></span>
  </button>
