<script>
(() => {
  // ---- Data (replace with real values) ----
  const weekScores = [62, 70, 58, 75, 81, 77, 86]; // last 7 days, today last
  let focusMinutes = 154;
  let sessions = 4;
  const SESSION_MINUTES = 25;

  // ---- Elements ----
  const $ = id => document.getElementById(id);
  const ring = $('ring-value');
  const scoreEl = $('score');
  const R = 54, C = 2 * Math.PI * R;
  ring.style.strokeDasharray = C;
  ring.style.strokeDashoffset = C;

  // ---- Date & day labels ----
  const now = new Date();
  $('today-date').textContent = now.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' });

  const dayNames = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(now); d.setDate(now.getDate() - i);
    dayNames.push(d.toLocaleDateString(undefined, { weekday: 'short' }));
  }
  $('days').innerHTML = dayNames.map((n, i) =>
    `<span class="${i === 6 ? 'today' : ''}">${n.slice(0, 1)}</span>`).join('');

  // ---- Score display ----
  function renderScore(target, animate = true) {
    ring.style.strokeDashoffset = C * (1 - target / 100);
    if (!animate) { scoreEl.textContent = target; return; }
    const start = parseInt(scoreEl.textContent, 10) || 0;
    const t0 = performance.now(), dur = 1000;
    (function tick(t) {
      const p = Math.min((t - t0) / dur, 1);
      const e = 1 - Math.pow(1 - p, 3);
      scoreEl.textContent = Math.round(start + (target - start) * e);
      if (p < 1) requestAnimationFrame(tick);
    })(t0);
  }

  function renderStats() {
    const today = weekScores[6], yest = weekScores[5];
    const diff = today - yest;
    const d = $('delta');
    d.className = 'delta ' + (diff >= 0 ? 'up' : 'down');
    d.textContent = (diff >= 0 ? '▲ +' : '▼ ') + diff + ' pts';
    $('focus-time').textContent = `${Math.floor(focusMinutes / 60)}h ${focusMinutes % 60}m`;
    $('sessions').textContent = sessions;
    $('avg').textContent = Math.round(weekScores.reduce((a, b) => a + b, 0) / weekScores.length);
  }

  // ---- Sparkline ----
  const svg = $('spark'), tooltip = $('tooltip'), wrap = $('spark-wrap');
  const W = 300, H = 84, PAD = 8;
  let pts = [];

  function renderSpark() {
    const min = Math.min(...weekScores) - 5;
    const max = Math.max(...weekScores) + 5;
    pts = weekScores.map((v, i) => [
      PAD + (i * (W - PAD * 2)) / (weekScores.length - 1),
      H - PAD - ((v - min) / (max - min)) * (H - PAD * 2)
    ]);

    // smooth path (cardinal-ish spline)
    let d = `M${pts[0][0]},${pts[0][1]}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;
      const t = 0.18;
      d += ` C${p1[0] + (p2[0] - p0[0]) * t},${p1[1] + (p2[1] - p0[1]) * t}` +
           ` ${p2[0] - (p3[0] - p1[0]) * t},${p2[1] - (p3[1] - p1[1]) * t}` +
           ` ${p2[0]},${p2[1]}`;
    }
    const area = `${d} L${pts[pts.length - 1][0]},${H} L${pts[0][0]},${H} Z`;

    svg.innerHTML = `
      <defs>
        <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#7c8cff" stop-opacity=".35"/>
          <stop offset="100%" stop-color="#7c8cff" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path d="${area}" fill="url(#areaGrad)"/>
      <line class="guide" id="guide" y1="0" y2="${H}" x1="0" x2="0"/>
      <path class="line" d="${d}" vector-effect="non-scaling-stroke"/>
      ${pts.map((p, i) => `<circle class="dot ${i === 6 ? 'active' : ''}" data-i="${i}" cx="${p[0]}" cy="${p[1]}" r="3.5" vector-effect="non-scaling-stroke"/>`).join('')}
    `;
  }

  function showTip(clientX) {
    const rect = svg.getBoundingClientRect();
    const x = ((clientX - rect.left) / rect.width) * W;
    let idx = 0, best = Infinity;
    pts.forEach((p, i) => { const dd = Math.abs(p[0] - x); if (dd < best) { best = dd; idx = i; } });
    const g = $('guide');
    g.setAttribute('x1', pts[idx][0]); g.setAttribute('x2', pts[idx][0]);
    g.classList.add('on');
    tooltip.textContent = `${dayNames[idx]} · ${weekScores[idx]}`;
    tooltip.style.left = (pts[idx][0] / W) * rect.width + 'px';
    tooltip.classList.add('on');
  }
  function hideTip() {
    tooltip.classList.remove('on');
    const g = $('guide'); if (g) g.classList.remove('on');
  }
  wrap.addEventListener('mousemove', e => showTip(e.clientX));
  wrap.addEventListener('touchmove', e => showTip(e.touches[0].clientX), { passive: true });
  wrap.addEventListener('mouseleave', hideTip);
  wrap.addEventListener('touchend', hideTip);

  // ---- Focus session button ----
  const btn = $('start-btn'), label = $('btn-label'), timerEl = $('btn-timer');
  let interval = null, remaining = 0, elapsedAtStart = 0;

  const fmt = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;

  function startSession() {
    remaining = SESSION_MINUTES * 60;
    btn.classList.add('running');
    label.textContent = 'Stop Focus';
    timerEl.textContent = '· ' + fmt(remaining);
    interval = setInterval(() => {
      remaining--;
      timerEl.textContent = '· ' + fmt(remaining);
      if (remaining <= 0) endSession(true);
    }, 1000);
  }

  function endSession(completed) {
    clearInterval(interval); interval = null;
    btn.classList.remove('running');
    label.textContent = 'Start Focus';
    timerEl.textContent = '';
    if (completed) {
      sessions += 1;
      focusMinutes += SESSION_MINUTES;
      weekScores[6] = Math.min(100, weekScores[6] + 2);
      renderStats(); renderSpark(); renderScore(weekScores[6]);
    }
  }

  btn.addEventListener('click', () => interval ? endSession(false) : startSession());

  // ---- Init ----
  renderStats();
  renderSpark();
  requestAnimationFrame(() => renderScore(weekScores[6]));
})();
</script>
</body>
</html>
```

**What's included**
- **Daily focus score:** an animated gradient ring with a count-up number, plus a delta versus yesterday, total focus time, and session count.
- **Weekly trend sparkline:** a smooth SVG line with an area fill, and a hover/touch tooltip that snaps to each day.
- **Start Focus button:** it starts a 25-minute countdown and turns into a "Stop Focus" button while running. Completing a full session updates the score, time, sessions, and sparkline.

To use real data, edit `weekScores` (the last 7 days, with today last), `focusMinutes`, and `sessions` at the top of the script. To change the session length, edit `SESSION_MINUTES`.

