      <span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span>
      <span>Fri</span><span>Sat</span><span>Sun</span>
    </div>
  </div>

  <div class="trend-row">
    <span>Weekly average: <span id="weeklyAvg">—</span></span>
    <span id="trendDelta"></span>
  </div>

  <button class="start-btn" id="startBtn">Start Focus</button>
</div>

<script>
  // --- Data ---
  const weekData = [
    { day: 'Mon', score: 62 },
    { day: 'Tue', score: 71 },
    { day: 'Wed', score: 58 },
    { day: 'Thu', score: 80 },
    { day: 'Fri', score: 74 },
    { day: 'Sat', score: 45 },
    { day: 'Sun', score: 87 }
  ];

  const todayScore = weekData[6].score;

  // --- Date badge ---
  document.getElementById('dateBadge').textContent =
    new Date().toLocaleDateString(undefined, { month: 'short', day: 'numeric' });

  // --- Animated score count-up ---
  const scoreEl = document.getElementById('scoreValue');
  let current = 0;
  const countInterval = setInterval(() => {
    current += Math.max(1, Math.ceil((todayScore - current) / 8));
    if (current >= todayScore) {
      current = todayScore;
      clearInterval(countInterval);
    }
    scoreEl.textContent = current;
  }, 30);

  // --- Sparkline (SVG) ---
  const svg = document.getElementById('sparkline');
  const W = 320, H = 70, PAD = 8;
  const maxScore = 100;

  const x = i => PAD + (i * (W - PAD * 2)) / (weekData.length - 1);
  const y = s => H - PAD - (s / maxScore) * (H - PAD * 2);

  const pts = weekData.map((d, i) => [x(i), y(d.score)]);

  // Smooth path (Catmull-Rom to bezier)
  function smoothPath(points) {
    if (points.length < 2) return '';
    let d = `M ${points[0][0]} ${points[0][1]}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[Math.max(0, i - 1)];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = points[Math.min(points.length - 1, i + 2)];
      const c1x = p1[0] + (p2[0] - p0[0]) / 6;
      const c1y = p1[1] + (p2[1] - p0[1]) / 6;
      const c2x = p2[0] - (p3[0] - p1[0]) / 6;
      const c2y = p2[1] - (p3[1] - p1[1]) / 6;
      d += ` C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2[0]} ${p2[1]}`;
    }
    return d;
  }

  const linePath = smoothPath(pts);
  const areaPath = linePath + ` L ${x(weekData.length - 1)} ${H} L ${x(0)} ${H} Z`;

  // Defs: gradient
  const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
  defs.innerHTML = `
    <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#4f8cff" stop-opacity="0.35"/>
      <stop offset="100%" stop-color="#4f8cff" stop-opacity="0"/>
    </linearGradient>`;
  svg.appendChild(defs);

  // Area fill
  const area = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  area.setAttribute('d', areaPath);
  area.setAttribute('fill', 'url(#areaGrad)');
  svg.appendChild(area);

  // Line
  const line = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  line.setAttribute('d', linePath);
  line.setAttribute('fill', 'none');
  line.setAttribute('stroke', '#4f8cff');
  line.setAttribute('stroke-width', '2.5');
  line.setAttribute('stroke-linecap', 'round');
  svg.appendChild(line);

  // Hover dots + tooltip
  const tooltip = document.getElementById('sparkTooltip');
  const dots = weekData.map((d, i) => {
    const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    dot.setAttribute('cx', pts[i][0]);
    dot.setAttribute('cy', pts[i][1]);
    dot.setAttribute('r', '4');
    dot.setAttribute('class', 'spark-dot');
    svg.appendChild(dot);
    return dot;
  });

  svg.addEventListener('mousemove', e => {
    const rect = svg.getBoundingClientRect();
    const mx = ((e.clientX - rect.left) / rect.width) * W;
    let nearest = 0, bestDist = Infinity;
    pts.forEach((p, i) => {
      const dist = Math.abs(p[0] - mx);
      if (dist < bestDist) { bestDist = dist; nearest = i; }
    });
    dots.forEach((dot, i) => dot.setAttribute('opacity', i === nearest ? '1' : '0'));
    const d = weekData[nearest];
    tooltip.textContent = `${d.day}: ${d.score}`;
    tooltip.style.left = (pts[nearest][0] / W * 100) + '%';
    tooltip.style.top = (pts[nearest][1] / H * 100) + '%';
    tooltip.style.opacity = '1';
  });

  svg.addEventListener('mouseleave', () => {
    tooltip.style.opacity = '0';
    dots.forEach(dot => dot.setAttribute('opacity', '0'));
  });

  // --- Weekly stats ---
  const avg = Math.round(weekData.reduce((s, d) => s + d.score, 0) / weekData.length);
  document.getElementById('weeklyAvg').textContent = avg;

  const delta = todayScore - avg;
  const deltaEl = document.getElementById('trendDelta');
  if (delta >= 0) {
    deltaEl.innerHTML = `<span class="up">▲ +${delta} vs avg</span>`;
  } else {
    deltaEl.innerHTML = `<span class="down">▼ ${delta} vs avg</span>`;
  }

  // --- Start Focus button ---
  const btn = document.getElementById('startBtn');
  let focusing = false, seconds = 0, timerId = null;

  btn.addEventListener('click', () => {
    focusing = !focusing;
    if (focusing) {
      btn.classList.add('focusing');
      btn.innerHTML = '<span class="pulse-ring"></span>Focusing — 00:00';
      timerId = setInterval(() => {
        seconds++;
        const mm = String(Math.floor(seconds / 60)).padStart(2, '0');
        const ss = String(seconds % 60).padStart(2, '0');
        btn.innerHTML = `<span class="pulse-ring"></span>Focusing — ${mm}:${ss}`;
      }, 1000);
    } else {
      clearInterval(timerId);
      seconds = 0;
      btn.classList.remove('focusing');
      btn.textContent = 'Start Focus';
    }
  });
</script>

</body>
</html>
```

