  </section>

  <button class="btn" id="startBtn">Start Focus</button>
</main>

<script>
(function () {
  "use strict";

  // ---- Sample data (swap in a real data source as needed) ----
  const week = [58, 72, 41, 80, 66, 61, 64]; // Mon..Sun, last = today
  let score = week[6];

  const $ = (id) => document.getElementById(id);
  const scoreEl = $("score"), ringFg = $("ringFg"), spark = $("spark");
  const deltaEl = $("delta"), btn = $("startBtn"), card = $("card"), dateEl = $("date");

  const CIRC = 2 * Math.PI * 52;
  ringFg.style.strokeDasharray = CIRC;
  ringFg.style.strokeDashoffset = CIRC; // start empty

  dateEl.textContent = new Date().toLocaleDateString(undefined,
    { weekday: "short", month: "short", day: "numeric" });

  // ---- Animated score count-up + progress ring ----
  function setScore(target) {
    const start = parseInt(scoreEl.textContent, 10) || 0;
    const t0 = performance.now(), dur = 1000;
    ringFg.style.strokeDashoffset = CIRC * (1 - target / 100);
    (function tick(now) {
      const p = Math.min((now - t0) / dur, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      scoreEl.textContent = Math.round(start + (target - start) * eased);
      if (p < 1) requestAnimationFrame(tick);
    })(t0);
  }

  // ---- Sparkline (pure SVG, built at runtime) ----
  function drawSpark(values) {
    const W = 292, H = 64, P = 8, NS = "http://www.w3.org/2000/svg";
    const min = Math.min(...values), max = Math.max(...values);
    const range = (max - min) || 1;
    const pts = values.map((v, i) => [
      P + (i * (W - 2 * P)) / (values.length - 1),
      H - P - ((v - min) / range) * (H - 2 * P)
    ]);
    const coord = (p) => p[0].toFixed(1) + "," + p[1].toFixed(1);

    const defs = document.createElementNS(NS, "defs");
    defs.innerHTML =
      '<linearGradient id="fill" x1="0" y1="0" x2="0" y2="1">' +
      '<stop offset="0" stop-color="#4cc2ff" stop-opacity=".28"/>' +
      '<stop offset="1" stop-color="#4cc2ff" stop-opacity="0"/></linearGradient>';
    spark.appendChild(defs);

    const area = document.createElementNS(NS, "path");
    area.setAttribute("d",
      "M" + pts[0][0].toFixed(1) + "," + H +
      " L" + pts.map(coord).join(" L") +
      " L" + pts[pts.length - 1][0].toFixed(1) + "," + H + " Z");
    area.setAttribute("fill", "url(#fill)");
    spark.appendChild(area);

    const line = document.createElementNS(NS, "polyline");
    line.setAttribute("points", pts.map(coord).join(" "));
    line.setAttribute("fill", "none");
    line.setAttribute("stroke", "#4cc2ff");
    line.setAttribute("stroke-width", "2");
    line.setAttribute("stroke-linejoin", "round");
    line.setAttribute("stroke-linecap", "round");
    spark.appendChild(line);

    pts.forEach((p, i) => {
      const last = i === pts.length - 1;
      const c = document.createElementNS(NS, "circle");
      c.setAttribute("cx", p[0].toFixed(1));
      c.setAttribute("cy", p[1].toFixed(1));
      c.setAttribute("r", last ? 4 : 2.5);
      c.setAttribute("fill", last ? "#4cc2ff" : "#232c38");
      if (last) {
        c.setAttribute("stroke", "#0b0f14");
        c.setAttribute("stroke-width", "2");
      }
      const t = document.createElementNS(NS, "title");
      t.textContent = values[i];
      c.appendChild(t);
      spark.appendChild(c);
    });
  }

  function redrawSpark() {
    spark.innerHTML = "";
    drawSpark(week);
  }

  // ---- Day-over-day delta ----
  function setDelta() {
    const d = week[6] - week[5];
    deltaEl.textContent = (d >= 0 ? "▲ +" : "▼ ") + d + " vs yesterday";
    deltaEl.className = "delta " + (d >= 0 ? "up" : "down");
  }

  // ---- Focus session timer ----
  let timer = null;
  btn.addEventListener("click", () => {
    if (timer) {
      clearInterval(timer);
      timer = null;
      const mins = (Date.now() - t0) / 60000;
      score = Math.min(100, Math.round(score + mins * 2));
      week[6] = score;
      setScore(score);
      setDelta();
      redrawSpark();
      btn.textContent = "Start Focus";
      btn.classList.remove("stop");
      card.classList.remove("focusing");
    } else {
      t0 = Date.now();
      card.classList.add("focusing");
      btn.classList.add("stop");
      const tick = () => {
        const s = Math.floor((Date.now() - t0) / 1000);
        btn.textContent = "End Focus · " +
          String(Math.floor(s / 60)).padStart(2, "0") + ":" +
          String(s % 60).padStart(2, "0");
      };
      tick();
      timer = setInterval(tick, 250);
    }
  });
  let t0 = 0;

  // ---- Init ----
  redrawSpark();
  setDelta();
  setTimeout(() => setScore(score), 150);
})();
</script>
</body>
</html>
