        </desc>
        <defs>
          <linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#b59aff" stop-opacity=".22"/>
            <stop offset="100%" stop-color="#b59aff" stop-opacity="0"/>
          </linearGradient>
        </defs>
        <path d="M8 30H342 M8 60H342 M8 90H342"
              stroke="#ffffff08" stroke-dasharray="3 5" fill="none"/>
        <path d="M8 78 L64 56 L120 66 L176 30 L232 46 L288 38 L342 14
                 L342 100 L8 100 Z"
              fill="url(#area-gradient)"/>
        <path d="M8 78 L64 56 L120 66 L176 30 L232 46 L288 38 L342 14"
              fill="none" stroke="#b59aff" stroke-width="2.5"
              stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="342" cy="14" r="8" fill="#b59aff" opacity=".12"/>
        <circle cx="342" cy="14" r="4" fill="#cbb8ff" stroke="#191b27" stroke-width="2"/>
      </svg>
      <div class="days" aria-hidden="true">
        <span>6d ago</span><span>5d</span><span>4d</span>
        <span>3d</span><span>2d</span><span>1d</span>
        <span class="today">Today</span>
      </div>
    </section>

    <button id="focus-button" type="button">
      <svg id="button-icon" width="16" height="16" viewBox="0 0 16 16"
           fill="currentColor" aria-hidden="true">
        <path d="M5 3.2v9.6L13 8z"/>
      </svg>
      <span id="button-label">Start Focus</span>
    </button>

    <div class="session" id="session">
      <span id="session-status" role="status">
        <span class="status-dot" aria-hidden="true"></span>Ready when you are
      </span>
      <span class="timer" id="timer" aria-label="Session duration">25:00</span>
    </div>
  </main>

  <script>
    const button = document.getElementById("focus-button");
    const label = document.getElementById("button-label");
    const icon = document.getElementById("button-icon");
    const session = document.getElementById("session");
    const status = document.getElementById("session-status");
    const timer = document.getElementById("timer");

    const duration = 25 * 60;
    let running = false;
    let remaining = duration;
    let deadline = 0;
    let interval;

    function renderTime() {
      const minutes = Math.floor(remaining / 60);
      const seconds = remaining % 60;
      timer.textContent =
        String(minutes).padStart(2, "0") + ":" +
        String(seconds).padStart(2, "0");
    }

    function setStatus(text) {
      status.innerHTML = '<span class="status-dot" aria-hidden="true"></span>';
      status.append(document.createTextNode(text));
    }

    function updateButton() {
      label.textContent = running
        ? "Pause Focus"
        : remaining === duration ? "Start Focus" : "Resume Focus";
      icon.innerHTML = running
        ? '<path d="M4 3h3v10H4zM9 3h3v10H9z"/>'
        : '<path d="M5 3.2v9.6L13 8z"/>';
      session.classList.toggle("running", running);
    }

    function tick() {
      remaining = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      renderTime();
      if (remaining === 0) {
        clearInterval(interval);
        running = false;
        remaining = duration;
        updateButton();
        setStatus("Session complete. Nice work!");
      }
    }

    button.addEventListener("click", () => {
      if (running) {
        tick();
        clearInterval(interval);
        running = false;
        setStatus(remaining === duration ? "Session complete. Nice work!" : "Session paused");
      } else {
        running = true;
        deadline = Date.now() + remaining * 1000;
        renderTime();
        setStatus("Focus session in progress");
        interval = setInterval(tick, 250);
      }
      updateButton();
    });
  </script>
</body>
</html>
