      <defs>
        <linearGradient id="fillGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#6c8cff" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#6c8cff" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path id="sparkArea" fill="url(#fillGrad)" d=""/>
      <path id="sparkLine" fill="none" stroke="#8f9cff" stroke-width="2.5"
            stroke-linejoin="round" stroke-linecap="round" d=""/>
      <circle id="sparkDot" r="4" fill="#3ddc97" cx="0" cy="0"/>
    </svg>
    <div class="days">
      <span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span>
      <span>Fri</span><span>Sat</span><span>Sun</span>
