<script>
  const todayScore = 74;
  const weekScores = [58, 63, 55, 70, 66, 72, todayScore];
  const yesterdayScore = weekScores[weekScores.length - 2];

  const dateEl = document.getElementById('date');
  dateEl.textContent = new Date().toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });

  const scoreNum = document.getElementById('scoreNum');
  const ringProgress = document.getElementById('ringProgress');
  const circumference = 2 * Math.PI * 46;
  ringProgress.style.strokeDasharray = circumference;

  function animateScore(target) {
    let current = 0;
    const step = () => {
      current += Math.ceil((target - current) / 8) || 1;
      if (current >= target) current = target;
      scoreNum.textContent = current;
      if (current < target) requestAnimationFrame(step);
    };
    step();
    ringProgress.style.strokeDashoffset = circumference * (1 - target / 100);
  }

  function label(score) {
    if (score >= 85) return 'Deep focus';
    if (score >= 70) return 'Solid session';
    if (score >= 50) return 'Getting there';
    return 'Scattered';
  }

  const diff = todayScore - yesterdayScore;
  const deltaEl = document.getElementById('delta');
  deltaEl.textContent = (diff >= 0 ? '+' : '') + diff + ' vs yesterday';
  if (diff < 0) {
    deltaEl.style.color = '#ff6b8a';
    deltaEl.style.background = 'rgba(255, 107, 138, 0.1)';
  }

  document.getElementById('scoreLabel').textContent = label(todayScore);
  const avg = Math.round(weekScores.reduce((a, b) => a + b, 0) / weekScores.length);
  document.getElementById('avgWeek').textContent = 'Avg ' + avg;

  function drawSparkline(data) {
    const w = 300, h = 60, pad = 6;
    const min = Math.min(...data), max = Math.max(...data);
    const range = max - min || 1;
    const pts = data.map((v, i) => ({
      x: (i / (data.length - 1)) * w,
      y: pad + (1 - (v - min) / range) * (h - pad * 2)
    }));
    let line = `M${pts[0].x},${pts[0].y}`;
    for (let i = 1; i < pts.length; i++) {
      const p0 = pts[i - 1], p1 = pts[i];
      const cx = (p0.x + p1.x) / 2;
      line += ` C${cx},${p0.y} ${cx},${p1.y} ${p1.x},${p1.y}`;
    }
    const area = `${line} L${w},${h} L0,${h} Z`;
    document.getElementById('sparkLine').setAttribute('d', line);
    document.getElementById('sparkArea').setAttribute('d', area);
    const last = pts[pts.length - 1];
    const dot = document.getElementById('sparkDot');
    dot.setAttribute('cx', last.x);
    dot.setAttribute('cy', last.y);
  }

  drawSparkline(weekScores);
  setTimeout(() => animateScore(todayScore), 200);

  const startBtn = document.getElementById('startBtn');
  const timerEl = document.getElementById('timer');
  let timerId = null;
  let remaining = 0;

  function fmt(s) {
    const m = Math.floor(s / 60).toString().padStart(2, '0');
    const sec = (s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  }

  startBtn.addEventListener('click', () => {
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
      startBtn.textContent = 'Start Focus';
      startBtn.classList.remove('active');
      timerEl.textContent = '';
      return;
    }
    remaining = 25 * 60;
    startBtn.textContent = 'Stop Focus';
    startBtn.classList.add('active');
    timerEl.textContent = fmt(remaining) + ' remaining';
    timerId = setInterval(() => {
      remaining--;
      if (remaining <= 0) {
        clearInterval(timerId);
        timerId = null;
        startBtn.textContent = 'Start Focus';
        startBtn.classList.remove('active');
        timerEl.textContent = 'Session complete';
        return;
      }
      timerEl.textContent = fmt(remaining) + ' remaining';
    }, 1000);
  });
</script>

</body>
</html>
