<script>
(function () {
  "use strict";

  /* ---------------- data ---------------- */
  const SCORE = 82;
  const WEEK = [42, 55, 48, 67, 61, 74, 82];
  const DAYS = ["M", "T", "W", "T", "F", "S", "S"];

  const $ = (id) => document.getElementById(id);
  const card = $("card");
  const ringFg = $("ringFg");
  const scoreNum = $("scoreNum");
  const sparkLine = $("sparkLine");
  const sparkArea = $("sparkArea");
  const sparkDots = $("sparkDots");
  const daysEl = $("days");
  const btn = $("focusBtn");
  const btnLabel = $("btnLabel");
  const btnIcon = $("btnIcon");
  const progressBar = $("progressBar");
  const hint = $("hint");

  const CIRC = 2 * Math.PI * 52;

  /* ---------------- date ---------------- */
  $("todayDate").textContent = new Date().toLocaleDateString(undefined, {
    weekday: "long", month: "short", day: "numeric"
  });

  /* ---------------- ring ---------------- */
  ringFg.style.strokeDasharray = CIRC.toFixed(2);

  function animateRing() {
    requestAnimationFrame(() => {
      ringFg.style.strokeDashoffset = (CIRC * (1 - SCORE / 100)).toFixed(2);
    });
  }

  function countUp() {
    const dur = 1200;
    const t0 = performance.now();
    (function step(now) {
      const p = Math.min((now - t0) / dur, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      scoreNum.textContent = Math.round(eased * SCORE);
      if (p < 1) requestAnimationFrame(step);
    })(t0);
  }

  /* ---------------- sparkline ---------------- */
  const W = 300, H = 84, PAD = 10;
  const max = Math.max(...WEEK);
  const min = Math.min(...WEEK);
  const span = (max - min) || 1;

  const pts = WEEK.map((v, i) => ({
    x: PAD + (i * (W - PAD * 2)) / (WEEK.length - 1),
    y: H - PAD - ((v - min) / span) * (H - PAD * 2)
  }));

  function smoothPath(points) {
    let d = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i - 1] || points[i];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = points[i + 2] || p2;
      const c1x = p1.x + (p2.x - p0.x) / 6;
      const c1y = p1.y + (p2.y - p0.y) / 6;
      const c2x = p2.x - (p3.x - p1.x) / 6;
      const c2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
    }
    return d;
  }

  const lineD = smoothPath(pts);
  const areaD = `${lineD} L ${pts[pts.length - 1].x.toFixed(2)} ${H} L ${pts[0].x.toFixed(2)} ${H} Z`;

  sparkLine.setAttribute("d", lineD);
  sparkArea.setAttribute("d", areaD);

  // dots
  pts.forEach((p, i) => {
    const isLast = i === pts.length - 1;
    if (isLast) {
      const halo = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      halo.setAttribute("class", "spark-dot last-halo");
      halo.setAttribute("cx", p.x);
      halo.setAttribute("cy", p.y);
      halo.setAttribute("r", 4);
      sparkDots.appendChild(halo);
    }
    const c = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    c.setAttribute("class", "spark-dot" + (isLast ? " last" : ""));
    c.setAttribute("cx", p.x);
    c.setAttribute("cy", p.y);
    c.setAttribute("r", isLast ? 3.6 : 2.6);
    const t = document.createElementNS("http://www.w3.org/2000/svg", "title");
    t.textContent = `${DAYS[i]} — ${WEEK[i]}`;
    c.appendChild(t);
    sparkDots.appendChild(c);
  });

  // day labels
  DAYS.forEach((d, i) => {
    const s = document.createElement("span");
    s.textContent = d;
    if (i === DAYS.length - 1) s.className = "today";
    daysEl.appendChild(s);
  });

  // average label
  const avg = Math.round(WEEK.reduce((a, b) => a + b, 0) / WEEK.length);
  $("avgLabel").textContent = `avg ${avg}`;

  // draw-in animation
  function drawSpark() {
    const len = sparkLine.getTotalLength();
    sparkLine.style.strokeDasharray = len;
    sparkLine.style.strokeDashoffset = len;
    sparkLine.style.transition = "none";
    requestAnimationFrame(() => {
      sparkLine.style.transition = "stroke-dashoffset 1.6s cubic-bezier(.22,1,.36,1)";
      sparkLine.style.strokeDashoffset = "0";
    });
    setTimeout(() => sparkArea.classList.add("in"), 420);
  }

  /* ---------------- focus session ---------------- */
  const SESSION_MS = 25 * 60 * 1000;
  let sessionStart = null;
  let ticker = null;

  const PLAY = '<path d="M3.5 2.2v11.6l10-5.8-10-5.8z" fill="currentColor" stroke="none"/>';
  const STOP = '<rect x="3.6" y="3.6" width="8.8" height="8.8" rx="1.6" fill="currentColor" stroke="none"/>';

  function fmt(ms) {
    const total = Math.max(0, Math.ceil(ms / 1000));
    const m = Math.floor(total / 60);
    const s = total % 60;
    return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }

  function startSession() {
    sessionStart = Date.now();
    card.classList.add("focusing");
    btn.classList.add("focusing");
    btnIcon.innerHTML = STOP;
    hint.textContent = "Session in progress — stay off your phone";

    ticker = setInterval(() => {
      const elapsed = Date.now() - sessionStart;
      const remaining = SESSION_MS - elapsed;
      const pct = Math.min(elapsed / SESSION_MS, 1) * 100;

      progressBar.style.width = pct.toFixed(2) + "%";
      btnLabel.innerHTML = `Focusing · <span class="timer">${fmt(remaining)}</span>`;

      if (remaining <= 0) finishSession();
    }, 200);

    // immediate paint
    btnLabel.innerHTML = `Focusing · <span class="timer">${fmt(SESSION_MS)}</span>`;
  }

  function stopSession() {
    clearInterval(ticker);
    ticker = null;
    sessionStart = null;
    card.classList.remove("focusing");
    btn.classList.remove("focusing");
    btnIcon.innerHTML = PLAY;
    btnLabel.textContent = "Start Focus";
    progressBar.style.width = "0%";
    hint.textContent = "25-minute deep work session";
  }

  function finishSession() {
    clearInterval(ticker);
    ticker = null;
    sessionStart = null;
    card.classList.remove("focusing");
    btn.classList.remove("focusing");
    btnIcon.innerHTML = PLAY;
    btnLabel.textContent = "Start Focus";
    progressBar.style.width = "100%";
    hint.textContent = "Session complete — nice work";

    setTimeout(() => { progressBar.style.width = "0%"; }, 1400);
  }

  btn.addEventListener("click", () => {
    if (ticker) stopSession();
    else startSession();
  });

  /* ---------------- boot ---------------- */
  window.addEventListener("load", () => {
    animateRing();
    countUp();
    drawSpark();
  });

  // fallback if load already fired
  if (document.readyState === "complete") {
    animateRing();
    countUp();
    drawSpark();
  }
})();
</script>
</body>
</html>
```
### Focus Card: Score, Trend & Session Mechanics

The card combines a live focus score, a weekly trend chart, and a one-click session timer to keep your deep work on track.

- **Score ring & count-up** — The circular ring fills to 82/100 on load, while the number animates from 0 to 82. A “Live” badge and today’s date sit in the header.
- **Weekly sparkline** — A smooth SVG line plots seven daily values (42–82) with a gradient stroke, area fill, and a pulsing halo on the last point. Day labels and an average label are generated automatically.
- **Start Focus button** — Clicking it starts a 25-minute countdown. The button switches to a stop icon, the card gets a cyan glow, and the progress bar fills as time passes. Clicking again stops the session, and finishing resets everything with a completion hint.
- **Responsive & reduced-motion** — The card is centered and scales down on small screens; animations are disabled when the user prefers reduced motion.
---

**Optimization Tip:** You can customize the focus score, weekly values, and session length by editing the `SCORE`, `WEEK`, and `SESSION_MS` variables at the top of the script. The `DAYS` array holds the weekday labels.

