  let weekData = [64, 72, 58, 75, 81, 69, 78];   // Mon .. Sun (last = today)
  let score = weekData[weekData.length - 1];

  /* ================= refs ================= */
  const $ = id => document.getElementById(id);
  const scoreNum = $('scoreNum');
  const ringBar = $('ringBar');
  const sparkSvg = $('sparkSvg');
  const tooltip = $('tooltip');
  const trendBadge = $('trendBadge');
  const statusText = $('statusText');
  const btn = $('focusBtn');
  const btnText = $('btnText');
  const btnTimer = $('btnTimer');
  const note = $('sessionNote');

  /* ================= date label ================= */
  $('dateLabel').textContent = new Date().toLocaleDateString(
    undefined, { weekday: 'short', month: 'short', day: 'numeric' }
  );

  /* ================= score ring ================= */
  const RING_C = 2 * Math.PI * 52;             // circumference
  ringBar.style.strokeDasharray = RING_C;
  ringBar.style.strokeDashoffset = RING_C;     // start empty

  let scoreAnim = null;
  function animateScore(from, to, dur = 1200) {
    if (scoreAnim) cancelAnimationFrame(scoreAnim);
    const start = performance.now();
    const frame = t => {
      const p = Math.min(1, (t - start) / dur);
      const eased = 1 - Math.pow(1 - p, 3);    // easeOutCubic
      const val = from + (to - from) * eased;
      scoreNum.textContent = Math.round(val);
      ringBar.style.strokeDashoffset = RING_C * (1 - val / 100);
      if (p < 1) scoreAnim = requestAnimationFrame(frame);
    };
    scoreAnim = requestAnimationFrame(frame);
  }

  function updateStatus(s) {
    statusText.textContent =
      s >= 85 ? 'Peak focus — personal best zone' :
      s >= 70 ? 'Deep work streak · 3 days' :
      s >= 50 ? 'Steady — keep the momentum' :
                'Low focus day · time to lock in';
  }

  /* ================= sparkline ================= */
  const VB_W = 320, VB_H = 96;
  const PAD_X = 16, PAD_TOP = 14, PAD_BOTTOM = 22;

  // Catmull-Rom -> cubic bezier for a smooth curve
  function smoothPath(pts) {
    let d = `M${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[Math.max(0, i - 1)];
      const p1 = pts[i], p2 = pts[i + 1];
      const p3 = pts[Math.min(pts.length - 1, i + 2)];
      const c1x = p1[0] + (p2[0] - p0[0]) / 6, c1y = p1[1] + (p2[1] - p0[1]) / 6;
      const c2x = p2[0] - (p3[0] - p1[0]) / 6, c2y = p2[1] - (p3[1] - p1[1]) / 6;
      d += ` C${c1x.toFixed(1)} ${c1y.toFixed(1)}, ${c2x.toFixed(1)} ${c2y.toFixed(1)}, ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
    }
    return d;
  }

  function renderSparkline() {
    tooltip.style.opacity = 0;
    const n = weekData.length;
    const minV = Math.min(...weekData), maxV = Math.max(...weekData);
    const range = Math.max(1, maxV - minV);
    const plotH = VB_H - PAD_TOP - PAD_BOTTOM;
    const xs = weekData.map((_, i) => PAD_X + (i * (VB_W - PAD_X * 2)) / (n - 1));
    const ys = weekData.map(v => PAD_TOP + (1 - (v - minV) / range) * plotH);
    const pts = xs.map((x, i) => [x, ys[i]]);

    const line = smoothPath(pts);
    const base = VB_H - PAD_BOTTOM + 8;
    const area = `${line} L${xs[n - 1].toFixed(1)} ${base} L${xs[0].toFixed(1)} ${base} Z`;

    let dots = '', hits = '', labels = '';
    for (let i = 0; i < n; i++) {
      const today = i === n - 1;
      const cx = xs[i].toFixed(1), cy = ys[i].toFixed(1);
      dots += `<circle cx="${cx}" cy="${cy}" r="${today ? 4.5 : 3}" fill="${today ? '#22d3ee' : '#5b6478'}"${today ? ' filter="drop-shadow(0 0 4px rgba(34,211,238,.8))"' : ''}/>`;
      hits += `<circle class="hit" data-i="${i}" cx="${cx}" cy="${cy}" r="16" fill="transparent"/>`;
      labels += `<text x="${cx}" y="${VB_H - 4}" text-anchor="middle" font-size="9" font-weight="${today ? 700 : 400}" fill="${today ? '#22d3ee' : '#5b6478'}">${DAY_INITIALS[i]}</text>`;
    }

    sparkSvg.innerHTML = `
      <defs>
        <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stop-color="#22d3ee"/>
          <stop offset="100%" stop-color="#818cf8"/>
        </linearGradient>
        <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="rgba(34,211,238,.26)"/>
          <stop offset="100%" stop-color="rgba(34,211,238,0)"/>
        </linearGradient>
      </defs>
      <path class="spark-area" d="${area}" fill="url(#areaGrad)"/>
      <path class="spark-line" d="${line}" fill="none" stroke="url(#lineGrad)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
      <g class="spark-dots">${dots}${hits}</g>
      ${labels}
    `;

    // draw-in animation for the line
    const path = sparkSvg.querySelector('.spark-line');
    const len = path.getTotalLength();
    path.style.strokeDasharray = len;
    path.style.strokeDashoffset = len;
    path.getBoundingClientRect();               // force reflow
    path.style.transition = 'stroke-dashoffset 1.1s ease';
    path.style.strokeDashoffset = 0;
  }

  /* sparkline tooltips (event delegation) */
  sparkSvg.addEventListener('mouseover', e => {
    const t = e.target;
    if (!t.classList || !t.classList.contains('hit')) return;
    const i = +t.dataset.i;
    tooltip.textContent = `${DAY_NAMES[i]} · ${weekData[i]}`;
    tooltip.style.left = (parseFloat(t.getAttribute('cx')) / VB_W * 100) + '%';
    tooltip.style.top = (parseFloat(t.getAttribute('cy')) / VB_H * 100) + '%';
    tooltip.style.opacity = 1;
  });
  sparkSvg.addEventListener('mouseout', e => {
    if (e.target.classList && e.target.classList.contains('hit')) tooltip.style.opacity = 0;
  });

  /* ================= trend badge ================= */
  function updateTrend() {
    const today = weekData[weekData.length - 1];
    const prev = weekData.slice(0, -1);
    const avg = prev.reduce((a, b) => a + b, 0) / prev.length;
    const pct = ((today - avg) / avg) * 100;
    const up = pct >= 0;
    trendBadge.textContent = `${up ? '▲' : '▼'} ${Math.abs(pct).toFixed(0)}% vs week avg`;
    trendBadge.classList.toggle('down', !up);
  }

  /* ================= focus session ================= */
  let running = false, startTs = 0, tick = null;
  const fmt = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;

  btn.addEventListener('click', () => {
    if (!running) {
      running = true;
      startTs = Date.now();
      btn.classList.add('running');
      btn.setAttribute('aria-label', 'End focus session');
      btnText.textContent = 'End Focus';
      tick = setInterval(() => {
        btnTimer.textContent = '· ' + fmt(Math.floor((Date.now() - startTs) / 1000));
      }, 250);
    } else {
      running = false;
      clearInterval(tick);
      const elapsed = Math.floor((Date.now() - startTs) / 1000);
      btn.classList.remove('running');
      btn.setAttribute('aria-label', 'Start a focus session');
      btnTimer.textContent = '';
      btnText.textContent = 'Start Focus';

      // award points (1 per minute, min 1) and refresh the card
      const earned = Math.max(1, Math.round(elapsed / 60));
      const old = score;
      score = Math.min(100, score + earned);
      animateScore(old, score, 800);
      updateStatus(score);
      weekData[weekData.length - 1] = score;
      renderSparkline();
      updateTrend();

      note.textContent = `Session saved · +${score - old} pts · ${fmt(elapsed)} focused`;
      note.classList.add('show');
      setTimeout(() => note.classList.remove('show'), 4000);
    }
  });

  /* ================= init ================= */
  updateStatus(score);
  updateTrend();
  renderSparkline();
  animateScore(0, score);
</script>
</body>
</html>
```

**What's included:**

- **Focus score** — animated count-up inside a gradient progress ring (SVG, `stroke-dashoffset` driven), with a dynamic status line that changes based on the score.
- **Weekly sparkline** — smooth Catmull-Rom curve with gradient stroke, fading area fill, day labels, today's point highlighted, and hover tooltips showing each day's value. A trend badge computes today vs. the week average.
- **Start Focus button** — toggles into a running state with a pulsing dot and live session timer. Ending a session awards points (1 per minute), animates the ring/score upward, redraws the sparkline with today's new value, and shows a confirmation note.
- **Fully self-contained** — no external images, fonts, or libraries; everything is inline HTML/CSS/JS with system fonts and hand-drawn SVG. Also respects `prefers-reduced-motion`.

