<script>
  // Date
  document.getElementById('date').textContent =
    new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });

  // Animated score + ring
  const targetScore = 87;
  const scoreEl = document.getElementById('score');
  const ring = document.getElementById('ring');
  const circumference = 314;

  requestAnimationFrame(() => {
    ring.style.strokeDashoffset = circumference - (circumference * targetScore / 100);
  });

  let current = 0;
  const counter = setInterval(() => {
    current++;
    scoreEl.textContent = current;
    if (current >= targetScore) clearInterval(counter);
  }, 16);

  // Sparkline
  const data = [
    { day: 'Monday', value: 62 },
    { day: 'Tuesday', value: 71 },
    { day: 'Wednesday', value: 68 },
    { day: 'Thursday', value: 79 },
    { day: 'Friday', value: 84 },
    { day: 'Saturday', value: 76 },
    { day: 'Sunday', value: 87 }
  ];

  const svg = document.getElementById('sparkline');
  const tooltip = document.getElementById('tooltip');
  const W = 360, H = 86, P = 12;
  const min = Math.min(...data.map(d => d.value)) - 8;
  const max = Math.max(...data.map(d => d.value)) + 6;

  const points = data.map((d, i) => ({
    x: P + i * ((W - P * 2) / (data.length - 1)),
    y: H - P - ((d.value - min) / (max - min)) * (H - P * 2),
    ...d
  }));

  // Smooth path
  function smoothPath(pts) {
    let d = `M ${pts[0].x},${pts[0].y}`;
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i], p1 = pts[i + 1];
      const mx = (p0.x + p1.x) / 2;
      d += ` C ${mx},${p0.y} ${mx},${p1.y} ${p1.x},${p1.y}`;
    }
    return d;
  }

  const linePath = smoothPath(points);
  const areaPath = `${linePath} L ${points[points.length-1].x},${H} L ${points[0].x},${H} Z`;

  svg.innerHTML = `
    <defs>
      <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stop-color="#818cf8"/>
        <stop offset="100%" stop-color="#e879f9"/>
      </linearGradient>
      <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#818cf8" stop-opacity="0.35"/>
        <stop offset="100%" stop-color="#818cf8" stop-opacity="0"/>
      </linearGradient>
    </defs>
    <path d="${areaPath}" fill="url(#areaGrad)"/>
    <path d="${linePath}" fill="none" stroke="url(#lineGrad)" stroke-width="3" stroke-linecap="round"/>
    ${points.map((p,i) => `
      <circle cx="${p.x}" cy="${p.y}" r="12" fill="transparent" style="cursor:pointer" data-i="${i}"></circle>
      <circle cx="${p.x}" cy="${p.y}" r="${i===points.length-1?5:4}" fill="#12151d" stroke="${i===points.length-1?'#e879f9':'#818cf8'}" stroke-width="2.5" pointer-events="none"></circle>
    `).join('')}
  `;

  svg.querySelectorAll('circle[data-i]').forEach(circle => {
    circle.addEventListener('mouseenter', () => {
      const p = points[+circle.dataset.i];
      tooltip.innerHTML = `${p.day}: <b>${p.value} / 100</b>`;
    });
    circle.addEventListener('mouseleave', () => {
      tooltip.textContent = 'Hover a point to see details';
    });
    circle.addEventListener('click', () => {
      const p = points[+circle.dataset.i];
      tooltip.innerHTML = `${p.day}: <b>${p.value} / 100</b>`;
    });
  });

  // Focus timer
  const btn = document.getElementById('focusBtn');
  const btnText = document.getElementById('btnText');
  const timerEl = document.getElementById('timer');
  let interval = null, remaining = 25 * 60, running = false;

  function renderTimer() {
    const m = String(Math.floor(remaining / 60)).padStart(2, '0');
    const s = String(remaining % 60).padStart(2, '0');
    timerEl.innerHTML = `${m}:${s}<small>${running ? 'Focus session in progress' : 'Paused'}</small>`;
  }

  btn.addEventListener('click', () => {
    running = !running;
    btn.classList.toggle('running', running);
    timerEl.style.display = 'block';

    if (running) {
      btnText.textContent = 'Pause Focus';
      renderTimer();
      interval = setInterval(() => {
        remaining--;
        renderTimer();
        if (remaining <= 0) {
          clearInterval(interval);
          running = false;
          btn.classList.remove('running');
          btnText.textContent = 'Start Focus';
          timerEl.innerHTML = `Done!<small>Great work — session complete</small>`;
          remaining = 25 * 60;
        }
      }, 1000);
    } else {
      btnText.textContent = 'Resume Focus';
      clearInterval(interval);
      renderTimer();
    }
  });
</script>
</body>
</html>
