<script>
  // Date
  document.getElementById('currentDate').textContent = new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }) + ' • Today';

  // Animated Score Ring
  const score = 84;
  const circumference = 2 * Math.PI * 45;
  const progressRing = document.getElementById('progressRing');
  const scoreValue = document.getElementById('scoreValue');
  progressRing.style.strokeDasharray = circumference;
  progressRing.style.strokeDashoffset = circumference;

  setTimeout(() => {
    progressRing.style.strokeDashoffset = circumference - (score / 100) * circumference;
    let current = 0;
    const timer = setInterval(() => {
      current += 2;
      if (current >= score) {
        current = score;
        clearInterval(timer);
      }
      scoreValue.innerHTML = current + '<small>/100</small>';
    }, 20);
  }, 300);

  // Sparkline
  const data = [42, 58, 45, 72, 60, 78, 84];
  const svg = document.getElementById('sparkline');
  const w = 300, h = 64, pad = 6;
  const max = Math.max(...data), min = Math.min(...data);
  const range = max - min || 1;

  const points = data.map((v, i) => {
    const x = pad + (i / (data.length - 1)) * (w - pad * 2);
    const y = h - pad - ((v - min) / range) * (h - pad * 2) - 8;
    return {x, y, v};
  });

  const linePath = points.map((p,i) => `${i===0?'M':'L'} ${p.x} ${p.y}`).join(' ');
  const areaPath = linePath + ` L ${points[points.length-1].x} ${h} L ${points[0].x} ${h} Z`;

  svg.innerHTML += `<path class="sparkline-area" d="${areaPath}" />`;
  svg.innerHTML += `<path class="sparkline-line" d="${linePath}" />`;

  points.forEach((p, i) => {
    if (i === points.length - 1) {
      svg.innerHTML += `<circle class="sparkline-dot" cx="${p.x}" cy="${p.y}" r="5" />`;
      svg.innerHTML += `<circle class="sparkline-dot" cx="${p.x}" cy="${p.y}" r="2.5" fill="white" stroke="none" />`;
    } else {
      svg.innerHTML += `<circle cx="${p.x}" cy="${p.y}" r="2.5" fill="#2a2a36" stroke="#3a3a4a" stroke-width="1.2" />`;
    }
  });

  // Start Focus Button Logic
  const btn = document.getElementById('focusBtn');
  const btnText = document.getElementById('btnText');
  let focusing = false;
  let interval;
  let seconds = 25 * 60;

  btn.addEventListener('click', () => {
    focusing = !focusing;
    if (focusing) {
      btn.classList.add('focusing');
      btn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg> <span class="timer" id="timer">25:00</span> • Focusing`;
      const timerEl = document.getElementById('timer');
      interval = setInterval(() => {
        seconds--;
        if (seconds <= 0) {
          clearInterval(interval);
          btnText.textContent = "Session Complete!";
          btn.classList.remove('focusing');
          focusing = false;
          seconds = 25 * 60;
          return;
        }
        const m = String(Math.floor(seconds / 60)).padStart(2, '0');
        const s = String(seconds % 60).padStart(2, '0');
        if (timerEl) timerEl.textContent = `${m}:${s}`;
      }, 1000);
    } else {
      btn.classList.remove('focusing');
      clearInterval(interval);
      btn.innerHTML = `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5.14v14l11-7z"/></svg> <span>Start Focus</span>`;
    }
  });
</script>
</body>
</html>
