        <svg class="sparkline-svg" id="sparklineSvg" viewBox="0 0 300 75" preserveAspectRatio="none">
          <defs>
            <linearGradient id="sparkline-gradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stop-color="#6366f1" />
              <stop offset="100%" stop-color="#6366f1" stop-opacity="0" />
            </linearGradient>
          </defs>
          <path class="sparkline-area" id="sparklineArea" d=""></path>
