        </svg>
        <span id="btnText">Start Focus</span>
      </button>
      <div class="timer-display" id="timerDisplay">4h 12m logged today</div>
    </div>
  </div>

  <script>
    // Data Configuration
    const dailyScore = 88;
    const weeklyData = [68, 74, 71, 85, 79, 92, dailyScore];
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

    // Animate Gauge & Score Number on Load
    window.addEventListener('DOMContentLoaded', () => {
      const gaugeFill = document.getElementById('gaugeFill');
      const scoreValue = document.getElementById('scoreValue');
      const circumference = 2 * Math.PI * 36; // r = 36

      // Animate SVG Stroke
      setTimeout(() => {
        const offset = circumference - (dailyScore / 100) * circumference;
        gaugeFill.style.strokeDashoffset = offset;
      }, 100);

      // Animate Number Counter
      let current = 0;
      const duration = 1000;
      const stepTime = Math.max(Math.floor(duration / dailyScore), 10);
      const timer = setInterval(() => {
        current += 2;
        if (current >= dailyScore) {
          current = dailyScore;
          clearInterval(timer);
        }
        scoreValue.textContent = current;
      }, stepTime);

      renderSparkline();
    });

    // Build SVG Sparkline
    function renderSparkline() {
      const width = 300;
      const height = 70;
      const paddingX = 10;
      const paddingY = 12;

      const minVal = Math.min(...weeklyData) - 10;
      const maxVal = Math.max(...weeklyData) + 5;

      const points = weeklyData.map((val, idx) => {
        const x = paddingX + (idx / (weeklyData.length - 1)) * (width - paddingX * 2);
        const y = height - paddingY - ((val - minVal) / (maxVal - minVal)) * (height - paddingY * 2);
        return { x, y, val, day: days[idx] };
      });

      // Generate smooth cubic bezier curve or polyline
      const lineCoords = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
      const areaCoords = `${lineCoords} L ${points[points.length - 1].x.toFixed(1)} ${height} L ${points[0].x.toFixed(1)} ${height} Z`;

      document.getElementById('sparklineLine').setAttribute('d', lineCoords);
      document.getElementById('sparklineArea').setAttribute('d', areaCoords);

      // Average calculation
      const avg = Math.round(weeklyData.reduce((a, b) => a + b, 0) / weeklyData.length);
      document.getElementById('weeklyAvg').textContent = `Avg: ${avg} pts`;

      // Render Interactive Points
      const pointsGroup = document.getElementById('sparklinePoints');
      const tooltip = document.getElementById('tooltip');

      points.forEach((p) => {
        const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('class', 'sparkline-point');
        circle.setAttribute('cx', p.x);
        circle.setAttribute('cy', p.y);
        circle.setAttribute('r', '4');

        circle.addEventListener('mouseenter', () => {
          tooltip.style.opacity = '1';
          tooltip.textContent = `${p.day}: ${p.val} pts`;
          tooltip.style.left = `${(p.x / width) * 100}%`;
          tooltip.style.top = `${(p.y / 75) * 100}%`;
        });

        circle.addEventListener('mouseleave', () => {
          tooltip.style.opacity = '0';
        });

        pointsGroup.appendChild(circle);
      });
    }

    // Focus Session Button & Timer Logic
    let isFocusing = false;
    let secondsElapsed = 0;
    let timerInterval = null;

    const focusBtn = document.getElementById('focusBtn');
    const btnText = document.getElementById('btnText');
    const btnIcon = document.getElementById('btnIcon');
    const timerDisplay = document.getElementById('timerDisplay');
    const statusText = document.getElementById('statusText');
    const statusBadge = document.getElementById('statusBadge');
    const statusDot = document.getElementById('statusDot');

    focusBtn.addEventListener('click', () => {
      isFocusing = !isFocusing;

      if (isFocusing) {
        focusBtn.classList.add('active');
        btnText.textContent = 'End Focus Session';
        btnIcon.innerHTML = '<rect x="6" y="6" width="12" height="12" rx="2"></rect>';

        statusText.textContent = 'In Session';
        statusBadge.style.backgroundColor = 'rgba(99, 102, 241, 0.15)';
        statusBadge.style.color = '#818cf8';
        statusBadge.style.borderColor = 'rgba(99, 102, 241, 0.35)';
        statusDot.style.backgroundColor = '#818cf8';
        statusDot.style.boxShadow = '0 0 8px #818cf8';

        secondsElapsed = 0;
        timerDisplay.textContent = 'Session: 00:00';
        timerInterval = setInterval(() => {
          secondsElapsed++;
          const mins = String(Math.floor(secondsElapsed / 60)).padStart(2, '0');
          const secs = String(secondsElapsed % 60).padStart(2, '0');
          timerDisplay.textContent = `Session: ${mins}:${secs}`;
        }, 1000);
      } else {
        clearInterval(timerInterval);
        focusBtn.classList.remove('active');
        btnText.textContent = 'Start Focus';
        btnIcon.innerHTML = '<polygon points="5 3 19 12 5 21 5 3"></polygon>';

        statusText.textContent = 'Optimal';
        statusBadge.style.backgroundColor = 'rgba(16, 185, 129, 0.15)';
        statusBadge.style.color = 'var(--accent-secondary)';
        statusBadge.style.borderColor = 'rgba(16, 185, 129, 0.3)';
        statusDot.style.backgroundColor = 'var(--accent-secondary)';
        statusDot.style.boxShadow = '0 0 8px var(--accent-secondary)';

        timerDisplay.textContent = '4h 12m logged today';
      }
    });
  </script>
</body>
</html>
