<script>
(function() {
  const canvas = document.getElementById('spark');
  const ctx = canvas.getContext('2d');
  const data = [62, 74, 68, 85, 91, 87, 94];
  const labels = ['M','T','W','T','F','S','S'];

  function draw() {
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;
    const pad = 12;
    const step = (w - pad * 2) / (data.length - 1);
    const max = Math.max(...data);
    const min = Math.min(...data);
    const range = max - min || 1;

    const pts = data.map((v, i) => ({
      x: pad + i * step,
      y: h - pad - ((v - min) / range) * (h - pad * 2)
    }));

    // Gradient fill
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, 'rgba(108, 92, 231, 0.45)');
    grad.addColorStop(1, 'rgba(108, 92, 231, 0.02)');

    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) {
      const cx1 = (pts[i-1].x + pts[i].x) / 2;
      const cy1 = pts[i-1].y;
      const cx2 = (pts[i-1].x + pts[i].x) / 2;
      const cy2 = pts[i].y;
      ctx.bezierCurveTo(cx1, cy1, cx2, cy2, pts[i].x, pts[i].y);
    }
    ctx.lineTo(pts[pts.length-1].x, h);
    ctx.lineTo(pts[0].x, h);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // Line
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) {
      const cx1 = (pts[i-1].x + pts[i].x) / 2;
      const cy1 = pts[i-1].y;
      const cx2 = (pts[i-1].x + pts[i].x) / 2;
      const cy2 = pts[i].y;
      ctx.bezierCurveTo(cx1, cy1, cx2, cy2, pts[i].x, pts[i].y);
    }
    ctx.strokeStyle = '#6c5ce7';
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();

    // Dots
    pts.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = '#15151e';
      ctx.fill();
      ctx.strokeStyle = '#6c5ce7';
      ctx.lineWidth = 2.5;
      ctx.stroke();
    });

    // Labels
    ctx.fillStyle = '#7a7a90';
    ctx.font = '12px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    labels.forEach((l, i) => ctx.fillText(l, pts[i].x, h - 18));
  }

  window.addEventListener('resize', draw);
  window.addEventListener('load', draw);

  // Timer logic
  const startBtn = document.getElementById('startBtn');
  const overlay = document.getElementById('overlay');
  const timerEl = document.getElementById('timer');
  const stopBtn = document.getElementById('stopBtn');
  const scoreEl = document.getElementById('score');
  let interval = null;
  let seconds = 25 * 60;

  function formatTime(s) {
    const m = Math.floor(s / 60).toString().padStart(2, '0');
    const sec = (s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  }

  startBtn.addEventListener('click', () => {
    startBtn.style.display = 'none';
    overlay.classList.add('active');
    seconds = 25 * 60;
    timerEl.textContent = formatTime(seconds);
    interval = setInterval(() => {
      seconds--;
      timerEl.textContent = formatTime(seconds);
      if (seconds <= 0) {
        clearInterval(interval);
        timerEl.textContent = 'Done!';
        scoreEl.textContent = '94';
        setTimeout(() => {
          overlay.classList.remove('active');
          startBtn.style.display = 'block';
        }, 1500);
      }
    }, 1000);
  });

  stopBtn.addEventListener('click', () => {
    clearInterval(interval);
    overlay.classList.remove('active');
    startBtn.style.display = 'block';
  });
})();
</script>
</body>
</html>
