          <stop offset="0%" stop-color="#4ade80"/>
          <stop offset="100%" stop-color="#22d3ee"/>
        </linearGradient>
      </defs>
      <circle class="gauge-bg" cx="50" cy="50" r="45"></circle>
      <circle class="gauge-fg" cx="50" cy="50" r="45" transform="rotate(-90 50 50)"></circle>
      <text x="50" y="56" text-anchor="middle" fill="#e6e9ef" font-size="26" font-weight="700" font-family="sans-serif">87</text>
    </svg>
    <div class="score-info">
      <div class="score-main-label">Daily Focus Score</div>
      <div class="score-sub">out of 100</div>
      <div class="score-delta">+6 vs yesterday</div>
    </div>
  </div>

  <div class="trend-section">
    <div class="trend-header">
      <span>Weekly Trend</span>
      <span class="trend-change">▲ 12%</span>
    </div>
    <svg class="sparkline" id="sparkline" viewBox="0 0 200 48" preserveAspectRatio="none">
      <defs>
        <linearGradient id="sparkGradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stop-color="#22d3ee" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#22d3ee" stop-opacity="0"/>
        </linearGradient>
      </defs>
    </svg>
    <div class="spark-days">
      <span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span>
