<script>
  document.getElementById('today-date').textContent = new Date().toLocaleDateString(undefined, { month: 'short', day: 'numeric' });

  const weekData = [55, 62, 58, 70, 68, 81, 87];
  const min = Math.min(...weekData);
  const max = Math.max(...weekData);
  const width = 200;
  const height = 48;
  const padding = 6;

  const points = weekData.map((val, i) => {
    const x = (i / (weekData.length - 1)) * width;
    const y = height - padding - ((val - min) / (max - min || 1)) * (height - 2 * padding);
    return { x, y, val };
  });

  const linePath = points.map((p, i) => (i === 0 ? 'M' : 'L') + p.x + ',' + p.y).join(' ');
  const areaPath = linePath + ` L${width},${height} L0,${height} Z`;

  const sparkline = document.getElementById('sparkline');
  const NS = 'http://www.w3.org/2000/svg';

  const area = document.createElementNS(NS, 'path');
  area.setAttribute('d', areaPath);
  area.setAttribute('class', 'area');
  area.setAttribute('fill', 'url(#sparkGradient)');
  sparkline.appendChild(area);

  const line = document.createElementNS(NS, 'path');
  line.setAttribute('d', linePath);
  line.setAttribute('class', 'line');
  sparkline.appendChild(line);

  const last = points[points.length - 1];
  const dot = document.createElementNS(NS, 'circle');
  dot.setAttribute('cx', last.x);
  dot.setAttribute('cy', last.y);
  dot.setAttribute('r', 3);
  dot.setAttribute('class', 'last-point');
  sparkline.appendChild(dot);

  window.addEventListener('load', () => {
    const gaugeFg = document.querySelector('.gauge-fg');
    const score = 87;
    const circumference = 2 * Math.PI * 45;
    gaugeFg.style.strokeDasharray = circumference;
    gaugeFg.style.strokeDashoffset = circumference - (score / 100) * circumference;

    line.style.strokeDasharray = 500;
    line.style.strokeDashoffset = 0;
    area.style.opacity = 1;
  });

  const btn = document.getElementById('focusBtn');
  let timer = null;
  let timeLeft = 25 * 60;

  function updateBtn() {
    const m = Math.floor(timeLeft / 60).toString().padStart(2, '0');
    const s = (timeLeft % 60).toString().padStart(2, '0');
    btn.textContent = `Focusing... ${m}:${s}`;
  }

  btn.addEventListener('click', () => {
    if (timer) {
      clearInterval(timer);
      timer = null;
      btn.classList.remove('focusing');
      btn.textContent = 'Start Focus';
      timeLeft = 25 * 60;
    } else {
      btn.classList.add('focusing');
      updateBtn();
      timer = setInterval(() => {
        timeLeft--;
        if (timeLeft <= 0) {
          clearInterval(timer);
          timer = null;
          btn.classList.remove('focusing');
          btn.textContent = 'Focus Complete!';
          setTimeout(() => {
            btn.textContent = 'Start Focus';
          }, 2000);
          timeLeft = 25 * 60;
        } else {
          updateBtn();
        }
      }, 1000);
    }
  });
</script>
