  .cta.running:hover{
    filter:brightness(1.15);
    box-shadow:inset 0 0 0 1px #41506e;
  }

  .cta-icon{flex-shrink:0}

  /* ---------- Session ---------- */
  .session{
    margin-top:14px;
    animation:fadeIn .3s ease both;
  }

  .session-bar{
    height:4px;
    border-radius:99px;
    background:#1c2230;
    overflow:hidden;
  }

  .session-bar i{
    display:block;
    height:100%;
    width:0%;
    border-radius:99px;
    background:linear-gradient(90deg,var(--accent),var(--accent-2));
    transition:width .35s linear;
  }

  .session-meta{
    display:flex;
    justify-content:space-between;
    margin-top:8px;
    font-size:11px;
    color:var(--muted);
    font-variant-numeric:tabular-nums;
  }

  .session-meta strong{
    color:#c9d6ee;
    font-weight:650;
  }

  @keyframes fadeIn{
    from{opacity:0;transform:translateY(-4px)}
    to{opacity:1;transform:translateY(0)}
  }

  @media (prefers-reduced-motion: reduce){
    *{animation-duration:.001ms !important;transition-duration:.001ms !important}
  }
</style>
</head>
<body>

<div class="card">

  <header class="card-head">
    <div>
      <p class="eyebrow">Today</p>
      <h1 class="title">Focus Score</h1>
    </div>
    <span class="badge"><span class="dot"></span>12 day streak</span>
  </header>

  <div class="ring-wrap">
    <svg class="ring" viewBox="0 0 140 140" aria-hidden="true">
      <defs>
        <linearGradient id="ringGrad" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#5b8cff"/>
          <stop offset="100%" stop-color="#a855f7"/>
        </linearGradient>
      </defs>
      <circle class="ring-track" cx="70" cy="70" r="56"/>
      <circle class="ring-progress" cx="70" cy="70" r="56"/>
    </svg>
    <div class="ring-center">
      <div class="score" id="score">0</div>
      <div class="score-label">out of 100</div>
    </div>
  </div>

  <div class="trend">
    <div class="trend-head">
      <span>This week</span>
      <span class="delta" id="delta">+0%</span>
    </div>
    <svg class="spark" viewBox="0 0 300 70" aria-hidden="true">
      <defs>
        <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#5b8cff" stop-opacity=".34"/>
          <stop offset="100%" stop-color="#5b8cff" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <path id="sparkArea" fill="url(#areaGrad)" opacity="0"/>
      <path class="spark-line" id="sparkLine"/>
      <circle class="spark-dot" id="sparkDot" r="4"/>
    </svg>
    <div class="days" id="days"></div>
  </div>

  <button class="cta" id="cta" type="button">
    <svg class="cta-icon" viewBox="0 0 24 24" width="16" height="16" aria-hidden="true">
      <path id="ctaIcon" d="M8 5v14l11-7z" fill="currentColor"/>
    </svg>
    <span id="ctaLabel">Start Focus</span>
  </button>

  <div class="session" id="session" hidden>
    <div class="session-bar"><i id="sessionFill"></i></div>
    <div class="session-meta">
      <span><strong id="sessionTime">25:00</strong> remaining</span>
      <span>Deep work</span>
    </div>
  </div>

</div>

<script>
(function () {
  "use strict";

  /* =========================================================
     DATA
     ========================================================= */
  var SCORE = 82;
  var WEEK = [42, 58, 51, 67, 74, 69, 82];
  var DAYS = ["M", "T", "W", "T", "F", "S", "S"];

  /* =========================================================
     SCORE RING
     ========================================================= */
  var RADIUS = 56;
  var CIRC = 2 * Math.PI * RADIUS;

  var ringEl = document.querySelector(".ring-progress");
  var scoreEl = document.getElementById("score");

  ringEl.style.strokeDasharray = CIRC;
  ringEl.style.strokeDashoffset = CIRC;

  function animateScore(target, duration) {
    var start = performance.now();

    function frame(now) {
      var t = Math.min(1, (now - start) / duration);
      var eased = 1 - Math.pow(1 - t, 3);
      var value = target * eased;

      scoreEl.textContent = Math.round(value);
      ringEl.style.strokeDashoffset = CIRC * (1 - value / 100);

      if (t < 1) requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
  }

  /* =========================================================
     SPARKLINE
     ========================================================= */
  var VB_W = 300;
  var VB_H = 70;
  var PAD = 8;

  var lo = Math.min.apply(null, WEEK) - 12;
  var hi = Math.max.apply(null, WEEK) + 12;

  function px(i) {
    return PAD + i * (VB_W - 2 * PAD) / (WEEK.length - 1);
  }

  function py(v) {
    return (VB_H - PAD) - ((v - lo) / (hi - lo)) * (VB_H - 2 * PAD);
  }

  var points = WEEK.map(function (v, i) {
    return [px(i), py(v)];
  });

  function smoothPath(pts) {
    var d = "M " + pts[0][0].toFixed(2) + " " + pts[0][1].toFixed(2);

    for (var i = 0; i < pts.length - 1; i++) {
      var x0 = pts[i][0], y0 = pts[i][1];
      var x1 = pts[i + 1][0], y1 = pts[i + 1][1];
      var mx = (x0 + x1) / 2;

      d += " C " + mx.toFixed(2) + " " + y0.toFixed(2) +
           ", " + mx.toFixed(2) + " " + y1.toFixed(2) +
           ", " + x1.toFixed(2) + " " + y1.toFixed(2);
    }

    return d;
  }

  var lineEl = document.getElementById("sparkLine");
  var areaEl = document.getElementById("sparkArea");
  var dotEl = document.getElementById("sparkDot");

  var linePath = smoothPath(points);
  var last = points[points.length - 1];
  var first = points[0];

  lineEl.setAttribute("d", linePath);
  areaEl.setAttribute(
    "d",
    linePath + " L " + last[0].toFixed(2) + " " + VB_H +
    " L " + first[0].toFixed(2) + " " + VB_H + " Z"
  );

  dotEl.setAttribute("cx", last[0].toFixed(2));
  dotEl.setAttribute("cy", last[1].toFixed(2));

  /* Day labels positioned exactly under each data point */
  var daysEl = document.getElementById("days");

  DAYS.forEach(function (label, i) {
    var span = document.createElement("span");
    span.textContent = label;
    span.style.left = (px(i) / VB_W * 100).toFixed(3) + "%";
    if (i === DAYS.length - 1) span.className = "today";
    daysEl.appendChild(span);
  });

  /* Week-over-week delta */
  var prev = WEEK[WEEK.length - 2];
  var curr = WEEK[WEEK.length - 1];
  var delta = Math.round(((curr - prev) / prev) * 100);
  document.getElementById("delta").textContent =
    (delta >= 0 ? "+" : "") + delta + "%";

  /* =========================================================
     FOCUS TIMER
     ========================================================= */
  var TOTAL = 25 * 60;
  var remaining = TOTAL;
  var running = false;
  var tickId = null;

  var cta = document.getElementById("cta");
  var ctaLabel = document.getElementById("ctaLabel");
  var ctaIcon = document.getElementById("ctaIcon");
  var sessionEl = document.getElementById("session");
  var fillEl = document.getElementById("sessionFill");
  var timeEl = document.getElementById("sessionTime");

  var ICON_PLAY = "M8 5v14l11-7z";
  var ICON_PAUSE = "M7 5h4v14H7zM13 5h4v14h-4z";

  function fmt(seconds) {
    var m = Math.floor(seconds / 60);
    var s = seconds % 60;
    return String(m).padStart(2, "0") + ":" + String(s).padStart(2, "0");
  }

  function renderSession() {
    timeEl.textContent = fmt(remaining);
    fillEl.style.width = (((TOTAL - remaining) / TOTAL) * 100).toFixed(2) + "%";
  }

  function tick() {
    remaining -= 1;

    if (remaining <= 0) {
      completeSession();
      return;
    }

    renderSession();
  }

  function completeSession() {
    clearInterval(tickId);
    tickId = null;
    running = false;
    remaining = TOTAL;

    cta.classList.remove("running");
    ctaIcon.setAttribute("d", ICON_PLAY);
    ctaLabel.textContent = "Session complete";

    sessionEl.hidden = true;
    fillEl.style.width = "0%";
    timeEl.textContent = fmt(TOTAL);

    setTimeout(function () {
      if (!running) ctaLabel.textContent = "Start Focus";
    }, 1800);
  }

  cta.addEventListener("click", function () {
    if (running) {
      /* Pause */
      clearInterval(tickId);
      tickId = null;
      running = false;

      cta.classList.remove("running");
      ctaIcon.setAttribute("d", ICON_PLAY);
      ctaLabel.textContent = "Resume";
      return;
    }

    /* Start / resume */
    running = true;

    cta.classList.add("running");
    ctaIcon.setAttribute("d", ICON_PAUSE);
    ctaLabel.textContent = "Pause";

    sessionEl.hidden = false;
    renderSession();

    tickId = setInterval(tick, 1000);
  });

  /* =========================================================
     ENTRANCE ANIMATIONS
     ========================================================= */
  animateScore(SCORE, 1300);

  var lineLength = lineEl.getTotalLength();
  lineEl.style.strokeDasharray = lineLength;
  lineEl.style.strokeDashoffset = lineLength;

  requestAnimationFrame(function () {
    lineEl.style.transition = "stroke-dashoffset 1.3s cubic-bezier(.4,0,.2,1)";
    lineEl.style.strokeDashoffset = 0;

    areaEl.style.transition = "opacity 1s ease .25s";
    areaEl.style.opacity = 1;

    dotEl.style.transition = "opacity .5s ease 1.1s";
    dotEl.style.opacity = 1;
  });
})();
</script>
</body>
</html>
```
### Focus Card Features & Interaction

This card packs three useful pieces into one compact widget.

- **Animated score ring** — The circular progress ring fills up to your daily focus score (82 by default) with a smooth count-up animation.
- **Weekly trend sparkline** — A curved line chart shows the last seven days of focus data, with day labels and a percentage change indicator.
- **Focus timer button** — Clicking “Start Focus” launches a 25-minute countdown with a progress bar and pause/resume functionality.
---

**Optimization Tip:** You can replace the hardcoded `SCORE` and `WEEK` arrays in the script with your own data, and adjust `TOTAL` to change the focus session length.

