<div class="card">
  <div class="header">
    <div class="label">Daily Focus Score</div>
    <div class="score-wrapper">
      <div class="score" id="score">0</div>
      <div class="sub-score">/ 100</div>
    </div>
  </div>
  <div class="sparkline-wrap">
    <svg viewBox="0 0 340 60" preserveAspectRatio="none">
      <path class="sparkline-path" id="sparklinePath" d=""></path>
    </svg>
    <div class="sparkline-label">Weekly Trend</div>
  </div>
  <button class="start-btn" id="startBtn">Start Focus</button>
</div>

<script>
  const scoreEl = document.getElementById('score');
  const pathEl = document.getElementById('sparklinePath');
  const btn = document.getElementById('startBtn');

  // Generate 7 data points for the weekly trend
  const data = Array.from({ length: 7 }, () => Math.floor(Math.random() * 35) + 60);
  const currentScore = data[data.length - 1];

  // Animate the score counting up
  const duration = 1000;
  const startTime = performance.now();

  function animateScore(now) {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const ease = 1 - (1 - progress) * (1 - progress); // ease-out quad
    scoreEl.textContent = Math.floor(ease * currentScore);
    if (progress < 1) {
      requestAnimationFrame(animateScore);
    }
  }
  requestAnimationFrame(animateScore);

  // Build the sparkline path
  const width = 340;
  const height = 60;
  const padding = 16;
  const plotWidth = width - padding * 2;
  const plotHeight = height - padding * 2;
  const step = plotWidth / (data.length - 1);

  const minVal = 50;
  const maxVal = 100;
  const getY = (val) => {
    const t = (val - minVal) / (maxVal - minVal);
    return height - padding - t * plotHeight;
  };

  let d = `M ${padding} ${getY(data[0])}`;
  for (let i = 1; i < data.length; i++) {
    const x = padding + i * step;
    const y = getY(data[i]);
    d += ` L ${x} ${y}`;
  }
  pathEl.setAttribute('d', d);

  // Add data point dots
  const svg = pathEl.parentElement;
  data.forEach((val, i) => {
    const x = padding + i * step;
    const y = getY(val);
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('cx', x);
    circle.setAttribute('cy', y);
    circle.setAttribute('r', 3);
    circle.setAttribute('class', 'sparkline-dot');
    svg.appendChild(circle);
  });

  // Start Focus button logic
  let focusing = false;
  let seconds = 0;
  btn.addEventListener('click', () => {
    if (!focusing) {
      focusing = true;
      btn.textContent = 'Focusing...';
      btn.classList.add('focusing');
      btn.disabled = true;
      seconds = 0;

      const interval = setInterval(() => {
        seconds++;
        if (seconds >= 5) {
          clearInterval(interval);
          focusing = false;
          btn.textContent = 'Start Focus';
          btn.classList.remove('focusing');
          btn.disabled = false;
          // Simulate a score bump after a focus session
          const newScore = Math.min(100, Math.floor(Math.random() * 12) + currentScore);
          scoreEl.textContent = newScore;
        }
      }, 1000);
    }
  });
</script>
</body>
