  }

  .tooltip .tt-day {
    color: #8b93a7;
  }

  .tooltip .tt-val {
    font-weight: 700;
    color: #c4b5fd;
  }

  /* ---------- Stats ---------- */
  .stats-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-top: 24px;
  }

  .stat {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 14px;
    padding: 12px 8px;
    text-align: center;
  }

  .stat-value {
    display: block;
    font-size: 18px;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
  }

  .stat-label {
    display: block;
    font-size: 11px;
    color: var(--text-dim);
    margin-top: 2px;
  }

  /* ---------- Focus button ---------- */
  .focus-btn {
    margin-top: 20px;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 14px;
    border: none;
    border-radius: 14px;
    background: linear-gradient(135deg, #8b5cf6, #6366f1);
    color: #fff;
    font-size: 15px;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    white-space: nowrap;
    box-shadow: 0 10px 24px rgba(99, 102, 241, 0.35);
    transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.3s ease;
    -webkit-tap-highlight-color: transparent;
