  }

  .focus-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 14px 30px rgba(99, 102, 241, 0.45);
  }

  .focus-btn:active {
    transform: scale(0.98);
  }

  .focus-btn:focus-visible {
