    outline-offset: 2px;
  }

  .focus-btn.focusing {
    background: linear-gradient(135deg, #4c1d95, #4338ca);
    box-shadow: 0 10px 24px rgba(99, 102, 241, 0.2);
  }

  .btn-icon {
    display: flex;
  }

  .pulse-dot {
    display: none;
    width: 8px;
    height: 8px;
    border-radius: 50%;
