    animation: pulse 1.2s ease-in-out infinite;
  }

  .focus-btn.focusing .pulse-dot {
    display: block;
  }

  .focus-btn.focusing .btn-icon {
    display: none;
  }

  .btn-text {
    font-variant-numeric: tabular-nums;
  }

  @keyframes pulse {
    0%, 100% { transform: scale(1); opacity: 1; }
