<script>
(function () {
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // ---------- Data ----------
  var score = 84;
  var data = [62, 70, 58, 75, 80, 72, 84];

  // Real weekday labels for the last 7 days
  var dayLabels = [];
  for (var i = 6; i >= 0; i--) {
    var d = new Date();
    d.setDate(d.getDate() - i);
    dayLabels.push(d.toLocaleDateString('en-US', { weekday: 'narrow' }));
  }

  // ---------- Header date ----------
  document.getElementById('dateBadge').textContent =
    new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

  // ---------- Delta row ----------
  var prev = data[data.length - 2];
  var curr = data[data.length - 1];
  var pct = prev === 0 ? 0 : Math.round(((curr - prev) / prev) * 100);
  var up = pct >= 0;
  document.getElementById('deltaRow').innerHTML =
    '<span class="delta-up" style="color:' + (up ? '#34d399' : '#f87171') + '">' +
    (up ? '▲' : '▼') + ' ' + Math.abs(pct) + '%</span>' +
    '<span class="delta-text">vs yesterday</span>';

  // ---------- Average / best ----------
  var avg = Math.round(data.reduce(function (a, b) { return a + b; }, 0) / data.length);
  document.getElementById('avgValue').textContent = avg;
  document.getElementById('bestValue').textContent = Math.max.apply(null, data);

  // ---------- Sparkline geometry ----------
  var SVGNS = 'http://www.w3.org/2000/svg';
  var W = 280, H = 80, PAD = 12;
  var min = Math.min.apply(null, data);
  var max = Math.max.apply(null, data);
  var range = max - min || 1;

  var pts = data.map(function (v, i) {
    return {
      x: PAD + (i * (W - 2 * PAD)) / (data.length - 1),
      y: H - PAD - ((v - min) / range) * (H - 2 * PAD)
    };
  });

  function smoothPath(points) {
    var d = 'M ' + points[0].x + ',' + points[0].y;
    for (var i = 0; i < points.length - 1; i++) {
      var p0 = points[i - 1] || points[i];
      var p1 = points[i];
      var p2 = points[i + 1];
      var p3 = points[i + 2] || p2;
      var c1x = p1.x + (p2.x - p0.x) / 6;
      var c1y = p1.y + (p2.y - p0.y) / 6;
      var c2x = p2.x - (p3.x - p1.x) / 6;
      var c2y = p2.y - (p3.y - p1.y) / 6;
      d += ' C ' + c1x + ',' + c1y + ' ' + c2x + ',' + c2y + ' ' + p2.x + ',' + p2.y;
    }
    return d;
  }

  var linePath = smoothPath(pts);
  var areaPath = linePath +
    ' L ' + pts[pts.length - 1].x + ',' + (H - PAD) +
    ' L ' + pts[0].x + ',' + (H - PAD) + ' Z';

  var sparkSvg = document.getElementById('sparkSvg');
  document.getElementById('sparkLine').setAttribute('d', linePath);
  document.getElementById('sparkArea').setAttribute('d', areaPath);

  // Average guide line
  var avgY = H - PAD - ((avg - min) / range) * (H - 2 * PAD);
  var avgLine = document.getElementById('avgLine');
  avgLine.setAttribute('x1', PAD);
  avgLine.setAttribute('x2', W - PAD);
  avgLine.setAttribute('y1', avgY);
  avgLine.setAttribute('y2', avgY);

  // Weekday labels
  var wdGroup = document.getElementById('weekdays');
  pts.forEach(function (p, i) {
    var t = document.createElementNS(SVGNS, 'text');
    t.setAttribute('x', p.x);
    t.setAttribute('y', H - 3);
    t.setAttribute('class', 'weekday');
    t.textContent = dayLabels[i];
    wdGroup.appendChild(t);
  });

  // Dots
  var dotsGroup = document.getElementById('sparkDots');
  pts.forEach(function (p, i) {
    var c = document.createElementNS(SVGNS, 'circle');
    c.setAttribute('cx', p.x);
    c.setAttribute('cy', p.y);
    c.setAttribute('r', i === pts.length - 1 ? 4.5 : 3);
    c.setAttribute('class', i === pts.length - 1 ? 'dot dot-last' : 'dot');
    dotsGroup.appendChild(c);
  });

  // "today" label near the last dot
  var lastPt = pts[pts.length - 1];
  var todayLabel = document.createElementNS(SVGNS, 'text');
  todayLabel.setAttribute('x', lastPt.x);
  todayLabel.setAttribute('y', lastPt.y - 12);
  todayLabel.setAttribute('class', 'today-label');
  todayLabel.textContent = 'today';
  sparkSvg.appendChild(todayLabel);

  // ---------- Animations ----------
  var lineEl = document.getElementById('sparkLine');
  var len = lineEl.getTotalLength();

  if (reduceMotion) {
    lineEl.style.strokeDasharray = len;
    lineEl.style.strokeDashoffset = 0;
    sparkSvg.classList.add('loaded');
  } else {
    lineEl.style.strokeDasharray = len;
    lineEl.style.strokeDashoffset = len;
    void lineEl.getBoundingClientRect();
    lineEl.style.transition = 'stroke-dashoffset 1.4s ease .2s';
    lineEl.style.strokeDashoffset = 0;
    setTimeout(function () { sparkSvg.classList.add('loaded'); }, 50);
  }

  // Ring
  var ring = document.getElementById('ringFg');
  var R = 68;
  var C = 2 * Math.PI * R;
  ring.style.strokeDasharray = C;
  if (reduceMotion) {
    ring.style.strokeDashoffset = C * (1 - score / 100);
  } else {
    ring.style.strokeDashoffset = C;
    void ring.getBoundingClientRect();
    ring.style.transition = 'stroke-dashoffset 1.2s cubic-bezier(.4,0,.2,1)';
    ring.style.strokeDashoffset = C * (1 - score / 100);
  }

  // Score count-up
  var scoreEl = document.getElementById('scoreValue');
  if (reduceMotion) {
    scoreEl.textContent = score;
  } else {
    var start = performance.now();
    var dur = 1200;
    function tick(now) {
      var t = Math.min((now - start) / dur, 1);
      var eased = 1 - Math.pow(1 - t, 3);
      scoreEl.textContent = Math.round(eased * score);
      if (t < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  // ---------- Tooltip / hover ----------
  var wrap = document.getElementById('sparkWrap');
  var tip = document.getElementById('tooltip');
  var guide = document.getElementById('guideLine');

  wrap.addEventListener('mousemove', function (e) {
    var rect = sparkSvg.getBoundingClientRect();
    var x = ((e.clientX - rect.left) / rect.width) * W;
    var nearest = 0;
    var best = Infinity;
    pts.forEach(function (p, i) {
      var d = Math.abs(p.x - x);
      if (d < best) { best = d; nearest = i; }
    });
    var p = pts[nearest];
    guide.setAttribute('x1', p.x);
    guide.setAttribute('x2', p.x);
    tip.innerHTML = '<span class="tt-day">' + dayLabels[nearest] + '</span> · <span class="tt-val">' + data[nearest] + '</span>';
    tip.style.left = (p.x / W) * rect.width + 'px';
    tip.style.top = (p.y / H) * rect.height + 'px';
    tip.classList.add('visible');
    wrap.classList.add('hovering');
  });

  wrap.addEventListener('mouseleave', function () {
    tip.classList.remove('visible');
    wrap.classList.remove('hovering');
  });

  // ---------- Focus button ----------
  var btn = document.getElementById('focusBtn');
  var btnText = document.getElementById('btnText');
  var card = document.getElementById('card');
  var focusing = false;
  var seconds = 0;
  var timerId = null;

  function fmt(s) {
    var m = String(Math.floor(s / 60)).padStart(2, '0');
    var ss = String(s % 60).padStart(2, '0');
    return m + ':' + ss;
  }

  btn.addEventListener('click', function () {
    focusing = !focusing;
    btn.setAttribute('aria-pressed', String(focusing));

    if (focusing) {
      btn.classList.add('focusing');
      card.classList.add('focusing');
      btnText.textContent = 'Focusing… 00:00';
      seconds = 0;
      timerId = setInterval(function () {
        seconds++;
        btnText.textContent = 'Focusing… ' + fmt(seconds);
      }, 1000);
    } else {
      clearInterval(timerId);
      timerId = null;
      btn.classList.remove('focusing');
      card.classList.remove('focusing');
      btnText.textContent = 'Start Focus';
      seconds = 0;
    }
  });
})();
</script>

</body>
</html>
