  <script>
    const scores = [58, 64, 61, 72, 77, 80, 84];

    function createSmoothPath(points) {
      return points.reduce((path, point, index, allPoints) => {
        if (index === 0) {
          return `M ${point[0]} ${point[1]}`;
        }

        const previous = allPoints[index - 1];
        const middleX = (previous[0] + point[0]) / 2;

        return (
          path +
          ` C ${middleX} ${previous[1]}, ` +
          `${middleX} ${point[1]}, ` +
          `${point[0]} ${point[1]}`
        );
      }, "");
    }

    function renderSparkline() {
      const svg = document.getElementById("sparkline");
      const width = 360;
      const height = 116;
      const top = 12;
      const bottom = 101;
      const left = 4;
      const right = 356;

      const minimum = Math.min(...scores) - 8;
      const maximum = Math.max(...scores) + 5;
      const range = maximum - minimum;

      const points = scores.map((score, index) => {
        const x = left + (index * (right - left)) / (scores.length - 1);
        const y = bottom - ((score - minimum) / range) * (bottom - top);
        return [x, y];
      });

      const linePath = createSmoothPath(points);
      const areaPath = `${linePath} L ${right} ${bottom} L ${left} ${bottom} Z`;

      svg.innerHTML = `
        <defs>
          <linearGradient id="lineGradient" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#7666ed" />
            <stop offset="100%" stop-color="#b4aaff" />
