            <stop offset="100%" stop-color="#8b7cff" stop-opacity="0" />
          </linearGradient>
          <filter id="pointGlow" x="-100%" y="-100%" width="300%" height="300%">
            <feGaussianBlur stdDeviation="3" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        <g stroke="rgba(255,255,255,0.06)" stroke-width="1">
          <line x1="0" y1="28" x2="360" y2="28" />
          <line x1="0" y1="56" x2="360" y2="56" />
          <line x1="0" y1="84" x2="360" y2="84" />
        </g>

        <path d="${areaPath}" fill="url(#areaGradient)" />
        <path
          d="${linePath}"
          fill="none"
          stroke="url(#lineGradient)"
          stroke-width="3"
          stroke-linecap="round"
          stroke-linejoin="round"
        />

        ${points
          .slice(0, -1)
          .map(
            ([x, y]) => `
              <circle
                cx="${x}"
                cy="${y}"
                r="2.5"
                fill="#b4aaff"
                opacity="0.75"
              />
            `
          )
          .join("")}

        <circle
          cx="${points[points.length - 1][0]}"
          cy="${points[points.length - 1][1]}"
          r="7"
          fill="rgba(180,170,255,0.18)"
          filter="url(#pointGlow)"
        />
        <circle
          cx="${points[points.length - 1][0]}"
          cy="${points[points.length - 1][1]}"
          r="3.5"
          fill="#c9c2ff"
          stroke="#7666ed"
          stroke-width="2"
        />
      `;
    }

    function updateDate() {
      const date = new Date();
      const formattedDate = new Intl.DateTimeFormat("en-US", {
        weekday: "short",
        month: "short",
        day: "numeric"
      }).format(date);

      document.getElementById("today").textContent = formattedDate;
    }

    const button = document.getElementById("focusButton");
    const buttonLabel = document.getElementById("buttonLabel");
    const status = document.getElementById("status");

    let timer = null;
    let remainingSeconds = 25 * 60;
    let isRunning = false;

    function formatTime(seconds) {
      const minutes = Math.floor(seconds / 60);
      const remainder = seconds % 60;
      return `${String(minutes).padStart(2, "0")}:${String(remainder).padStart(2, "0")}`;
    }

    function stopTimer(message = "Focus session paused. Your progress is saved.") {
      clearInterval(timer);
      timer = null;
      isRunning = false;
      button.classList.remove("is-active");
      button.setAttribute("aria-pressed", "false");
      buttonLabel.textContent = "Resume Focus";
      status.textContent = message;
    }

    function startTimer() {
      if (isRunning) {
        return;
      }

      isRunning = true;
      button.classList.add("is-active");
      button.setAttribute("aria-pressed", "true");
      buttonLabel.textContent = `Focusing · ${formatTime(remainingSeconds)}`;
      status.textContent = "Focus session active. Your timer is running.";

      timer = setInterval(() => {
        remainingSeconds -= 1;
        buttonLabel.textContent = `Focusing · ${formatTime(remainingSeconds)}`;

        if (remainingSeconds <= 0) {
          clearInterval(timer);
          timer = null;
          isRunning = false;
          remainingSeconds = 25 * 60;
          button.classList.remove("is-active");
          button.setAttribute("aria-pressed", "false");
          buttonLabel.textContent = "Start Focus";
          status.textContent = "Focus session complete. Great work.";
        }
      }, 1000);
    }

    button.addEventListener("click", () => {
      if (isRunning) {
        stopTimer();
      } else {
        startTimer();
      }
    });

    updateDate();
    renderSparkline();
  </script>
