    const firstPoint = points[0];
    const lastPoint = points[points.length - 1];

    document.getElementById("trendLine").setAttribute("d", linePath);
    document.getElementById("trendArea").setAttribute(
      "d",
      `${linePath} L ${lastPoint.x} ${height} L ${firstPoint.x} ${height} Z`
    );

    document.getElementById("trendPoints").innerHTML = points
      .map((point, index) => {
        const isLast = index === points.length - 1;
        const halo = isLast
          ? `<circle cx="${point.x}" cy="${point.y}" r="9" fill="#aa9cff" opacity="0.13"></circle>`
          : "";

        return `${halo}<circle
          cx="${point.x}"
          cy="${point.y}"
          r="${isLast ? 4.5 : 2.7}"
          fill="${isLast ? "#aa9cff" : "#161b25"}"
          stroke="#aa9cff"
          stroke-width="${isLast ? 2 : 1.5}"
        ></circle>`;
      })
      .join("");

    // Start Focus toggles a 25-minute countdown.
    const SESSION_DURATION = 25 * 60;
    const focusButton = document.getElementById("focusButton");
    const buttonLabel = document.getElementById("buttonLabel");
    const buttonMeta = document.getElementById("buttonMeta");
    const sessionText = document.getElementById("sessionText");
    const statusIndicator = document.getElementById("statusIndicator");

    let endTime = null;
    let timerId = null;

    function formatTime(totalSeconds) {
      const minutes = Math.floor(totalSeconds / 60);
      const seconds = totalSeconds % 60;
      return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
    }

    function updateTimer() {
      const secondsRemaining = Math.max(
        0,
        Math.ceil((endTime - Date.now()) / 1000)
      );

      buttonMeta.textContent = formatTime(secondsRemaining);

      if (secondsRemaining === 0) {
        endSession(true);
      }
    }

    function startSession() {
      endTime = Date.now() + SESSION_DURATION * 1000;

      focusButton.classList.add("is-active");
      focusButton.setAttribute("aria-pressed", "true");
      statusIndicator.classList.add("active");
      buttonLabel.textContent = "End Focus";
      sessionText.textContent = "Focus session in progress";

      updateTimer();
      timerId = window.setInterval(updateTimer, 1000);
    }

    function endSession(completed = false) {
      window.clearInterval(timerId);
      timerId = null;
      endTime = null;

      focusButton.classList.remove("is-active");
      focusButton.setAttribute("aria-pressed", "false");
      statusIndicator.classList.remove("active");
      buttonLabel.textContent = "Start Focus";
      buttonMeta.textContent = "25 min";
      sessionText.textContent = completed
        ? "Session complete — nice work."
        : "Session ended. Ready when you are.";
    }

    focusButton.addEventListener("click", () => {
      if (endTime) {
        endSession();
      } else {
        startSession();
      }
    });
  </script>
</body>
</html>
