  <script>
    // Weekly sparkline
    const weeklyScores = [64, 70, 66, 76, 73, 78, 86];
    const width = 320;
    const left = 8;
    const right = 8;
    const top = 14;
    const bottom = 82;
    const minimum = Math.min(...weeklyScores) - 8;
    const maximum = Math.max(...weeklyScores) + 8;

    const points = weeklyScores.map((score, index) => ({
      x: left + index * ((width - left - right) / (weeklyScores.length - 1)),
      y: bottom - ((score - minimum) / (maximum - minimum)) * (bottom - top)
    }));

    function createSmoothPath(points) {
      return points.slice(1).reduce((path, point, index) => {
        const previous = points[index];
        const controlX = (previous.x + point.x) / 2;
        return `${path} C ${controlX} ${previous.y}, ${controlX} ${point.y}, ${point.x} ${point.y}`;
      }, `M ${points[0].x} ${points[0].y}`);
    }

    const linePath = createSmoothPath(points);
    const lastPoint = points[points.length - 1];

    document.getElementById("trend-line").setAttribute("d", linePath);
    document.getElementById("trend-area").setAttribute(
      "d",
      `${linePath} L ${lastPoint.x} 96 L ${points[0].x} 96 Z`
    );

    ["point-halo", "last-point"].forEach((id) => {
      const point = document.getElementById(id);
      point.setAttribute("cx", lastPoint.x);
      point.setAttribute("cy", lastPoint.y);
    });

    // Focus session timer
    const SESSION_LENGTH = 25 * 60;
    const focusButton = document.getElementById("focus-button");
    const buttonLabel = document.getElementById("button-label");
    const sessionStatus = document.getElementById("session-status");
    const sessionTime = document.getElementById("session-time");

    let remaining = SESSION_LENGTH;
    let timer = null;

    function renderTime() {
      const minutes = Math.floor(remaining / 60);
      const seconds = remaining % 60;
      sessionTime.textContent =
        `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
      sessionTime.setAttribute("datetime", `PT${remaining}S`);
    }

    function stopSession(message, resetTimer = true) {
      if (timer !== null) {
        window.clearInterval(timer);
      }

      timer = null;
      focusButton.classList.remove("is-running");
      focusButton.setAttribute("aria-pressed", "false");
      buttonLabel.textContent = "Start Focus";
      sessionStatus.textContent = message;

      if (resetTimer) {
        remaining = SESSION_LENGTH;
        renderTime();
      }
    }

    focusButton.addEventListener("click", () => {
      if (timer !== null) {
        stopSession("Session ended. Ready when you are.");
        return;
      }

      if (remaining === 0) {
        remaining = SESSION_LENGTH;
      }

      focusButton.classList.add("is-running");
      focusButton.setAttribute("aria-pressed", "true");
      buttonLabel.textContent = "End Focus";
      sessionStatus.textContent = "Focus in progress";
      renderTime();

      timer = window.setInterval(() => {
        remaining -= 1;
        renderTime();

        if (remaining === 0) {
          stopSession("Session complete — nice work!", false);
        }
      }, 1000);
    });
  </script>
