  .start.running{
    background:linear-gradient(180deg, rgba(255,255,255,.075), rgba(255,255,255,.03));
    border-color:rgba(255,255,255,.14);
    color:var(--text);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.07);
  }

  .start.running:hover{
    transform:translateY(-1px);
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.09),
      0 12px 26px -16px rgba(0,0,0,.9);
  }

  .start.running .i-play{ display:none; }
  .start.running .dot{ display:block; }

  /* Complete state */
  .start.done{
    background:linear-gradient(180deg, rgba(52,211,153,.18), rgba(52,211,153,.08));
    border-color:rgba(52,211,153,.4);
    color:#8ff0c8;
    box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
  }

  .start.done .dot{ display:block; background:var(--good); animation:none; }
  .start.done .i-play{ display:none; }

  @media (prefers-reduced-motion: reduce){
    .start, .dot{ transition:none; animation:none; }
  }
</style>
</head>
<body>

  <section class="card" aria-label="Daily focus score">

    <div class="head">
      <span class="eyebrow">Focus Score</span>
      <span class="pill">Today</span>
    </div>

