      <span class="score" id="scoreValue">82</span>
      <span class="score-max">/100</span>
      <span class="delta" title="vs. last week">&#9650; 6</span>
    </div>

    <p class="sub">3h 12m of deep work &middot; 4 sessions</p>

    <div class="chart-wrap">
      <svg class="chart" viewBox="0 0 320 84" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          <linearGradient id="strokeGrad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%"   stop-color="#7c5cff"/>
            <stop offset="55%"  stop-color="#8b7bff"/>
            <stop offset="100%" stop-color="#22d3ee"/>
          </linearGradient>
          <linearGradient id="fillGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stop-color="#7c5cff" stop-opacity=".34"/>
            <stop offset="100%" stop-color="#7c5cff" stop-opacity="0"/>
          </linearGradient>
        </defs>
        <path id="area" fill="url(#fillGrad)"/>
        <path id="line" fill="none" stroke="url(#strokeGrad)" stroke-width="2.5"
              stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>
        <g id="dots"></g>
      </svg>
      <div class="days" id="days"></div>
    </div>

