          <path d="M8 5.2v13.6L19 12z" fill="currentColor"/>
        </svg>
        <span class="dot"></span>
      </span>
      <span class="label" id="btnLabel">Start Focus</span>
      <span class="timer" id="btnTimer"></span>
    </button>

  </section>

<script>
(function () {
  "use strict";

  /* ---------------- Sparkline ---------------- */
  const data     = [58, 64, 61, 72, 68, 79, 82];
  const dayShort = ["M", "T", "W", "T", "F", "S", "S"];
  const dayFull  = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  const W = 320, H = 84;
  const padX = 14, padTop = 12, padBot = 12;

  const lo = Math.min.apply(null, data) - 8;
  const hi = Math.max.apply(null, data) + 6;

  const pts = data.map(function (v, i) {
    return {
      x: padX + i * (W - padX * 2) / (data.length - 1),
      y: H - padBot - ((v - lo) / (hi - lo)) * (H - padTop - padBot),
      v: v
    };
  });

  function smoothPath(p) {
    let d = "M " + p[0].x.toFixed(2) + " " + p[0].y.toFixed(2);
    const t = 0.18;
    for (let i = 0; i < p.length - 1; i++) {
      const p0 = p[i - 1] || p[i];
      const p1 = p[i];
      const p2 = p[i + 1];
      const p3 = p[i + 2] || p2;

      const c1x = p1.x + (p2.x - p0.x) * t;
      const c1y = p1.y + (p2.y - p0.y) * t;
      const c2x = p2.x - (p3.x - p1.x) * t;
      const c2y = p2.y - (p3.y - p1.y) * t;

      d += " C " + c1x.toFixed(2) + " " + c1y.toFixed(2) +
           ", " + c2x.toFixed(2) + " " + c2y.toFixed(2) +
           ", " + p2.x.toFixed(2) + " " + p2.y.toFixed(2);
    }
    return d;
  }

  const lineEl = document.getElementById("line");
  const areaEl = document.getElementById("area");
  const dotsEl = document.getElementById("dots");
  const daysEl = document.getElementById("days");

  const lineD = smoothPath(pts);
  lineEl.setAttribute("d", lineD);
  areaEl.setAttribute(
    "d",
    lineD +
    " L " + pts[pts.length - 1].x.toFixed(2) + " " + (H - 2) +
    " L " + pts[0].x.toFixed(2) + " " + (H - 2) + " Z"
  );

  const SVGNS = "http://www.w3.org/2000/svg";

  pts.forEach(function (p, i) {
    const isLast = i === pts.length - 1;

    if (isLast) {
      const halo = document.createElementNS(SVGNS, "circle");
      halo.setAttribute("cx", p.x);
      halo.setAttribute("cy", p.y);
      halo.setAttribute("r", 9);
      halo.setAttribute("fill", "#22d3ee");
      halo.setAttribute("opacity", "0.16");
      dotsEl.appendChild(halo);
    }

    const c = document.createElementNS(SVGNS, "circle");
    c.setAttribute("cx", p.x);
    c.setAttribute("cy", p.y);
    c.setAttribute("r", isLast ? 4 : 2.6);
    c.setAttribute("fill", isLast ? "#22d3ee" : "#8b7bff");
    c.setAttribute("opacity", isLast ? "1" : "0.55");

    const title = document.createElementNS(SVGNS, "title");
    title.textContent = dayFull[i] + " · " + p.v + "/100";
    c.appendChild(title);

    dotsEl.appendChild(c);
  });

  dayShort.forEach(function (label, i) {
    const s = document.createElement("span");
    s.textContent = label;
    s.style.left = (pts[i].x / W * 100).toFixed(3) + "%";
    if (i === dayShort.length - 1) s.className = "today";
    daysEl.appendChild(s);
  });

  /* Draw-in animation */
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (!reduceMotion) {
    const len = lineEl.getTotalLength();
    lineEl.style.strokeDasharray = len;
    lineEl.style.strokeDashoffset = len;
    areaEl.style.opacity = "0";

    // force layout so the transition has a starting frame
    void lineEl.getBoundingClientRect();

    lineEl.style.transition = "stroke-dashoffset 1.15s cubic-bezier(.4,0,.2,1)";
    areaEl.style.transition = "opacity .9s ease .25s";

    requestAnimationFrame(function () {
      lineEl.style.strokeDashoffset = "0";
      areaEl.style.opacity = "1";
    });
  }

  /* ---------------- Focus timer ---------------- */
  const DURATION = 25 * 60; // seconds

  const btn      = document.getElementById("startBtn");
  const btnLabel = document.getElementById("btnLabel");
  const btnTimer = document.getElementById("btnTimer");

  let remaining = DURATION;
  let running   = false;
  let tickId    = null;
  let doneId    = null;

  function fmt(sec) {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return m + ":" + (s < 10 ? "0" + s : s);
  }

  function startSession() {
    clearTimeout(doneId);
    btn.classList.remove("done");
    btn.classList.add("running");
    btn.setAttribute("aria-pressed", "true");

    running = true;
    btnLabel.textContent = "Focusing";
    btnTimer.textContent = fmt(remaining);

    tickId = setInterval(function () {
      remaining -= 1;
      if (remaining <= 0) {
        finishSession();
        return;
      }
      btnTimer.textContent = fmt(remaining);
    }, 1000);
  }

  function stopSession() {
    clearInterval(tickId);
    tickId = null;
    running = false;
    remaining = DURATION;

    btn.classList.remove("running");
    btn.setAttribute("aria-pressed", "false");
    btnLabel.textContent = "Start Focus";
    btnTimer.textContent = "";
  }

  function finishSession() {
    clearInterval(tickId);
    tickId = null;
    running = false;
    remaining = DURATION;

    btn.classList.remove("running");
    btn.classList.add("done");
    btn.setAttribute("aria-pressed", "false");
    btnLabel.textContent = "Session complete";
    btnTimer.textContent = "";

    doneId = setTimeout(function () {
      btn.classList.remove("done");
      btnLabel.textContent = "Start Focus";
    }, 2600);
  }

  btn.addEventListener("click", function () {
    if (running) {
      stopSession();
    } else {
      startSession();
    }
  });
})();
</script>
</body>
</html>
