              fill="url(#fill)"/>
        <polyline points="0,58 50,46 100,64 150,37 200,43 250,25 300,16"
                  fill="none" stroke="#a394ff" stroke-width="3"
                  stroke-linecap="round" stroke-linejoin="round"/>
