  </main>

  <script>
    const button = document.getElementById("focus-button");
    const status = document.getElementById("status");
    let endTime = null;
    let timer = null;

    function updateTimer() {
      const seconds = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
      const minutes = Math.floor(seconds / 60);
      const remainder = String(seconds % 60).padStart(2, "0");
      status.textContent = `Focus session: ${minutes}:${remainder} remaining`;

      if (seconds === 0) {
        clearInterval(timer);
        timer = null;
        endTime = null;
        button.textContent = "Start Focus";
        button.classList.remove("running");
        status.textContent = "Focus session complete. Great work!";
      }
    }

    button.addEventListener("click", () => {
      if (timer !== null) {
        clearInterval(timer);
        timer = null;
        endTime = null;
        button.textContent = "Start Focus";
        button.classList.remove("running");
        status.textContent = "Focus session stopped.";
        return;
      }

      endTime = Date.now() + 25 * 60 * 1000;
      button.textContent = "Stop Focus";
      button.classList.add("running");
      updateTimer();
      timer = setInterval(updateTimer, 1000);
    });
