<script>
(function () {
  "use strict";

  /* ---------- Score ring + count-up ---------- */
  const scoreEl = document.getElementById("score");
  const ringFg  = document.getElementById("ringFg");
  const TARGET  = 84;
  const CIRC    = 2 * Math.PI * 52;

  ringFg.style.strokeDasharray = CIRC;

  const easeOut = t => 1 - Math.pow(1 - t, 3);
  const DURATION = 1150;
  let startTs = null;

  function animateScore(ts) {
    if (startTs === null) startTs = ts;
    const p = Math.min((ts - startTs) / DURATION, 1);
    const eased = easeOut(p);
    const value = TARGET * eased;

    scoreEl.textContent = Math.round(value);
    ringFg.style.strokeDashoffset = CIRC * (1 - value / 100);

    if (p < 1) requestAnimationFrame(animateScore);
  }
  requestAnimationFrame(animateScore);

  /* ---------- Sparkline ---------- */
  const data = [58, 64, 61, 72, 69, 78, 84];
  const W = 280, H = 70, PAD = 9;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const span = max - min || 1;

  const pts = data.map((v, i) => ({
    x: PAD + (i * (W - PAD * 2)) / (data.length - 1),
    y: H - PAD - ((v - min) / span) * (H - PAD * 2)
  }));

  let d = `M ${pts[0].x.toFixed(2)} ${pts[0].y.toFixed(2)}`;
  for (let i = 1; i < pts.length; i++) {
    const p0 = pts[i - 1], p1 = pts[i];
    const cx = (p1.x - p0.x) * 0.42;
    d += ` C ${(p0.x + cx).toFixed(2)} ${p0.y.toFixed(2)}, ${(p1.x - cx).toFixed(2)} ${p1.y.toFixed(2)}, ${p1.x.toFixed(2)} ${p1.y.toFixed(2)}`;
  }

  document.getElementById("linePath").setAttribute("d", d);
  document.getElementById("areaPath").setAttribute("d", `${d} L ${pts[pts.length - 1].x} ${H} L ${pts[0].x} ${H} Z`);

  const dots = document.getElementById("dots");
  pts.forEach((p, i) => {
    const isLast = i === pts.length - 1;
    const c = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    c.setAttribute("cx", p.x.toFixed(2));
    c.setAttribute("cy", p.y.toFixed(2));
    c.setAttribute("r", isLast ? 3.6 : 2.1);
    c.setAttribute("fill", isLast ? "#22d3ee" : "#8b5cf6");
    c.setAttribute("opacity", isLast ? "1" : ".55");
    if (isLast) {
      c.setAttribute("stroke", "rgba(34,211,238,.28)");
      c.setAttribute("stroke-width", "5");
    }
    dots.appendChild(c);
  });

  const avg = Math.round(data.reduce((a, b) => a + b, 0) / data.length);
  document.getElementById("avgLabel").textContent = `avg ${avg}`;

  /* ---------- Focus session timer ---------- */
  const btn = document.getElementById("startBtn");
  const btnLabel = document.getElementById("btnLabel");
  const glyph = btn.querySelector(".glyph");
  const foot = document.getElementById("foot");

  const SESSION = 25 * 60;
  let remaining = SESSION;
  let state = "idle"; // idle | running | paused
  let ticker = null;

  const fmt = s => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  function render() {
    if (state === "running") {
      btn.classList.add("running");
      glyph.textContent = "\u23F8";
      btnLabel.textContent = fmt(remaining);
      foot.textContent = "Session running \u00b7 tap to pause";
    } else if (state === "paused") {
      btn.classList.add("running");
      glyph.textContent = "\u25B6";
      btnLabel.textContent = `Resume \u00b7 ${fmt(remaining)}`;
      foot.textContent = "Paused \u00b7 tap to resume";
    } else {
      btn.classList.remove("running");
      glyph.textContent = "\u25B6";
      btnLabel.textContent = "Start Focus";
      foot.textContent = "25:00 deep work block \u00b7 notifications muted";
    }
  }

  function stopTicker() {
    clearInterval(ticker);
    ticker = null;
  }

  btn.addEventListener("click", () => {
    if (state === "running") {
      state = "paused";
      stopTicker();
      render();
      return;
    }

    if (state === "idle") remaining = SESSION;
    state = "running";
    render();

    stopTicker();
    ticker = setInterval(() => {
      remaining -= 1;
      if (remaining <= 0) {
        remaining = 0;
        stopTicker();
        state = "idle";
        render();
        foot.textContent = "Block complete \u00b7 nice work";
        return;
      }
      render();
    }, 1000);
  });

  render();
})();
</script>
</body>
</html>
