            const height = svg.clientHeight;
            const padding = 10;

            const min = Math.min(...weeklyData) - 10;
            const max = Math.max(...weeklyData) + 10;

            const points = weeklyData.map((value, index) => {
                const x = padding + (index / (weeklyData.length - 1)) * (width - padding * 2);
                const y = height - padding - ((value - min) / (max - min)) * (height - padding * 2);
                return { x, y, value };
