            areaD += ` L ${points[points.length - 1].x} ${height - padding} Z`;
            areaPath.setAttribute('d', areaD);
            areaPath.setAttribute('fill', 'url(#areaGradient)');
            svg.appendChild(areaPath);

            // Line path
            const linePath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            let lineD = `M ${points[0].x} ${points[0].y}`;
            points.forEach((p, i) => {
                if (i > 0) {
                    const prev = points[i - 1];
                    const cpx1 = prev.x + (p.x - prev.x) / 3;
                    const cpx2 = prev.x + (p.x - prev.x) * 2 / 3;
                    lineD += ` C ${cpx1} ${prev.y}, ${cpx2} ${p.y}, ${p.x} ${p.y}`;
                }
            });
            linePath.setAttribute('d', lineD);
            linePath.setAttribute('fill', 'none');
            linePath.setAttribute('stroke', 'url(#lineGradient)');
            linePath.setAttribute('stroke-width', '2.5');
            linePath.setAttribute('stroke-linecap', 'round');
            svg.appendChild(linePath);

            // Interactive dots
            points.forEach((p, i) => {
                const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                dot.setAttribute('cx', p.x);
                dot.setAttribute('cy', p.y);
                dot.setAttribute('r', '4');
                dot.setAttribute('fill', i === points.length - 1 ? '#22c55e' : '#6366f1');
                dot.setAttribute('stroke', '#1a1a1f');
                dot.setAttribute('stroke-width', '2');
                dot.style.cursor = 'pointer';
                dot.style.transition = 'r 0.2s';

                dot.addEventListener('mouseenter', () => {
                    dot.setAttribute('r', '6');
                    tooltip.textContent = `${days[i]}: ${p.value}%`;
                    tooltip.style.left = `${p.x}px`;
                    tooltip.style.top = `${p.y + 16}px`;
                    tooltip.style.opacity = '1';
                });

                dot.addEventListener('mouseleave', () => {
                    dot.setAttribute('r', '4');
                    tooltip.style.opacity = '0';
                });

                svg.appendChild(dot);
            });
        }

        // Focus button functionality
        let isFocusing = false;
        const startButton = document.getElementById('startButton');
        const buttonIcon = document.getElementById('buttonIcon');
        const buttonText = document.getElementById('buttonText');

        startButton.addEventListener('click', () => {
            isFocusing = !isFocusing;

            if (isFocusing) {
                startButton.classList.add('active');
                buttonIcon.innerHTML = '<rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/>';
                buttonText.textContent = 'End Focus Session';
                buttonText.classList.add('pulse');
            } else {
                startButton.classList.remove('active');
                buttonIcon.innerHTML = '<polygon points="5,3 19,12 5,21"/>';
                buttonText.textContent = 'Start Focus Session';
                buttonText.classList.remove('pulse');
            }
        });

        // Initialize
        window.addEventListener('load', () => {
            setTimeout(animateScore, 300);
            drawSparkline();
        });

        // Handle resize
        window.addEventListener('resize', () => {
            const svg = document.getElementById('sparkline');
            svg.innerHTML = '';
            drawSparkline();
        });
    </script>
</body>
</html>
```

This creates a polished dark-mode dashboard card featuring:

**Visual Elements:**
- **Circular progress ring** with animated score (gradient from purple to green)
- **Session stats** showing completed sessions, focus time, and comparison to yesterday
- **Smooth curved sparkline** with gradient fill and interactive hover tooltips
- **Day labels** under the sparkline chart

**Interactions:**
- Score animates from 0 to the target value on load
- Hovering over sparkline dots shows the value for that day
- The "Start Focus" button toggles between start/end states with:
  - Play/pause icon changes
  - Color shift (purple → red)
  - Pulsing text when active

**Styling:**
- Dark gradient background with subtle borders
- Purple-to-green accent gradient throughout
- Smooth hover effects and shadows
- Fully responsive sparkline that redraws on resize
